-- ----------------------------
-- Table structure for aid_ai_provider
-- ----------------------------
DROP TABLE IF EXISTS `aid_ai_provider`;
CREATE TABLE `aid_ai_provider`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `provider_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '服务商展示名称 (如: 字节火山引擎, OpenAI)',
  `provider_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '服务商唯一编码 (系统内路由标识, 如: bytedance)',
  `logo_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '服务商LOGO图标URL（厂家品牌图标，所属模型共用）',
  `base_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '官方默认API基础网关地址',
  `api_key` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '官方默认API秘钥 (加密存储)',
  `api_secret` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '官方扩展秘钥 (如需)',
  `auth_header` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'Authorization' COMMENT '鉴权 header 名（默认 Authorization，Azure 用 api-key）',
  `auth_prefix` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'Bearer ' COMMENT '鉴权前缀（默认 Bearer，部分厂商无前缀）',
  `extra_headers` json NULL COMMENT '自定义 header（JSON 对象，如 {\"api-version\":\"2024-02-01\"}）',
  `extra_body` json NULL COMMENT '请求体附加参数（JSON 对象，如思考模式：{\"thinking\":{\"type\":\"disabled\"}}）',
  `extra_query` json NULL COMMENT '自定义 query string（JSON 对象，百度千帆等需要）',
  `api_key_apply_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'API Key 申请页直链',
  `official_doc_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '官方接口文档首页',
  `official_price_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '官方定价页直链（后台配价一键核对）',
  `task_query_suffix` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '任务查询路径模板（%s 为 taskId 占位符），用于异步任务轮询',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '渠道状态 (0正常 1停用)',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志 (0存在 1删除)',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `supports_callback` tinyint(1) NULL DEFAULT 0 COMMENT '是否支持回调通知',
  `schedule_strategy_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '默认调度策略JSON',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_provider_code`(`provider_code`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 21 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'AI服务商' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aid_ai_provider
-- ----------------------------
INSERT INTO `aid_ai_provider` VALUES (1,'阿里百炼','dashscope','/aid/2026/07/06/a1c2f4b38230472cb5074382afa97dcc.jpg','https://dashscope.aliyuncs.com','',NULL,'Authorization','Bearer ',NULL,NULL,NULL,'https://bailian.console.aliyun.com/cn-beijing?tab=model#/api-key','https://help.aliyun.com/zh/model-studio/what-is-model-studio?spm=a2c4g.11174283.0.i0',NULL,'/api/v1/tasks/%s','0','0','2026-04-18 22:48:55','admin','2026-07-28 00:44:15','system','阿里百炼服务商',0,'{\"dispatchMode\": \"POLL_ONLY\", \"backoffFactor\": 1.5, \"maxRetryCount\": 120, \"maxConcurrency\": 20, \"maxLifeSeconds\": 3600, \"modelConcurrency\": 10, \"supportsCallback\": false, \"maxIntervalSeconds\": 30, \"baseIntervalSeconds\": 5, \"providerConcurrency\": 20, \"firstPollDelaySeconds\": 5, \"progressTimeoutSeconds\": 600}');
