INSERT INTO `aid_ai_provider` VALUES (4,'Google Gemini','gemini','/aid/2026/06/28/780b866cf29b41269d455f6bba017ab1.png','https://generativelanguage.googleapis.com','',NULL,'Authorization','Bearer ',NULL,NULL,NULL,'https://aistudio.google.com/apikey','https://ai.google.dev/gemini-api/docs','https://ai.google.dev/gemini-api/docs/pricing',NULL,'0','0','2026-05-01 00:00:00','system','2026-07-29 00:28:33','system','Google Gemini 服务商；REST :streamGenerateContent?alt=sse；x-goog-api-key 鉴权\nhttps://generativelanguage.googleapis.com',0,'{\"dispatchMode\": \"POLL_ONLY\", \"backoffFactor\": 1.5, \"maxRetryCount\": 120, \"maxConcurrency\": 20, \"maxLifeSeconds\": 3600, \"supportsCallback\": false, \"maxIntervalSeconds\": 30, \"baseIntervalSeconds\": 5, \"firstPollDelaySeconds\": 5, \"progressTimeoutSeconds\": 600}');
INSERT INTO `aid_ai_provider` VALUES (6,'OpenAI','openai','/aid/2026/06/28/ae4d1a37233c454da5abe3bc6f66840b.png','https://api.openai.com','',NULL,'Authorization','Bearer ',NULL,NULL,NULL,'https://platform.openai.com/api-keys','https://developers.openai.com/api/docs','https://developers.openai.com/api/docs/pricing',NULL,'1','0','2026-05-05 22:04:04','system','2026-07-29 00:28:33','system','OpenAI / ChatGPT 文本大模型服务商；base_url 可改为代理地址',0,'{\"dispatchMode\": \"POLL_ONLY\", \"backoffFactor\": 1.5, \"maxRetryCount\": 120, \"maxConcurrency\": 20, \"maxLifeSeconds\": 3600, \"supportsCallback\": false, \"maxIntervalSeconds\": 30, \"baseIntervalSeconds\": 5, \"firstPollDelaySeconds\": 5, \"progressTimeoutSeconds\": 600}');
INSERT INTO `aid_ai_provider` VALUES (9,'豆包语音合成','volcengine_tts','/aid/2026/06/28/be834b781cbd4931b6e4b358c5cc618d.jpg','https://openspeech.bytedance.com','',NULL,'Authorization','Bearer ',NULL,NULL,NULL,'https://console.volcengine.com/speech/new/setting/apikeys','https://www.volcengine.com/docs/6561/1257543','https://www.volcengine.com/docs/6561/1359370',NULL,'0','0','2026-05-10 23:04:07','system','2026-07-28 00:44:15','system','豆包语音合成 / 声音复刻统一网关；鉴权头：X-Api-App-Id / X-Api-Access-Key / X-Api-Resource-Id；异步提交 /api/v3/tts/submit + 轮询 /api/v3/tts/query',0,'{\"dispatchMode\": \"POLL_ONLY\", \"backoffFactor\": 1.5, \"maxRetryCount\": 120, \"maxConcurrency\": 20, \"maxLifeSeconds\": 3600, \"supportsCallback\": false, \"maxIntervalSeconds\": 30, \"baseIntervalSeconds\": 5, \"firstPollDelaySeconds\": 5, \"progressTimeoutSeconds\": 600}');
INSERT INTO `aid_ai_provider` VALUES (11,'MiniMax','minimax','/aid/2026/06/28/c00ff4fa7c5a4540bd3e0ce7757a0dc7.png','https://api.minimaxi.com','',NULL,'Authorization','Bearer ',NULL,NULL,NULL,'https://platform.minimaxi.com/user-center/basic-information/interface-key','https://platform.minimaxi.com/docs','https://platform.minimaxi.com/docs/guides/pricing-paygo',NULL,'1','0','2026-05-12 14:38:50','system','2026-07-28 00:44:15','system','MiniMax 全模态：首次接入 TTS 异步长文本 /v1/t2a_async_v2；Bearer API Key 认证；后续可扩展文本 / 音乐 / 视频 / 音色克隆等',0,'{\"dispatchMode\": \"POLL_ONLY\", \"backoffFactor\": 1.5, \"maxRetryCount\": 120, \"maxConcurrency\": 20, \"maxLifeSeconds\": 3600, \"supportsCallback\": false, \"maxIntervalSeconds\": 30, \"baseIntervalSeconds\": 5, \"firstPollDelaySeconds\": 5, \"progressTimeoutSeconds\": 600}');
INSERT INTO `aid_ai_provider` VALUES (17,'Agnes AI','agnes','/aid/2026/07/06/5960f856dcfa475ca2139e50837898f4.png','https://api.agnes-ai.cn','',NULL,'Authorization','Bearer ',NULL,NULL,NULL,'https://apihub.agnes-ai.com','https://wiki.agnes-ai.cn','https://wiki.agnes-ai.cn','/agnesapi?video_id=%s','0','0','2026-06-05 19:37:49','system','2026-07-29 18:30:19','system','Agnes AI（Sapiens AI）OpenAI 兼容网关：文本(/v1/chat/completions) + 图片(/v1/images/generations) + 视频(/v1/videos)；视频异步轮询 /v1/videos/{task_id}',0,'{\"dispatchMode\": \"POLL_ONLY\", \"backoffFactor\": 1.5, \"maxRetryCount\": 120, \"maxConcurrency\": 20, \"maxLifeSeconds\": 3600, \"supportsCallback\": false, \"maxIntervalSeconds\": 30, \"baseIntervalSeconds\": 5, \"firstPollDelaySeconds\": 5, \"progressTimeoutSeconds\": 600}');
INSERT INTO `aid_ai_provider` VALUES (18,'Vidu','vidu','/aid/2026/06/28/29a1c29484e04e5393e25cc46a2dff49.jpg','https://api.vidu.cn','',NULL,'Authorization','Token ',NULL,NULL,NULL,'https://platform.vidu.cn/','https://platform.vidu.cn/docs/introduction',NULL,'/ent/v2/tasks/%s/creations','0','0','2026-06-26 11:14:34','','2026-07-28 00:44:15','system','Vidu 多模态（图片/视频）；回调优先+轮询兜底',1,'{\"dispatchMode\": \"CALLBACK_FIRST\", \"backoffFactor\": 1.5, \"maxRetryCount\": 120, \"maxConcurrency\": 1, \"maxLifeSeconds\": 3600, \"callbackBaseUrl\": \"\", \"modelConcurrency\": 10, \"supportsCallback\": true, \"maxIntervalSeconds\": 30, \"baseIntervalSeconds\": 5, \"providerConcurrency\": 20, \"firstPollDelaySeconds\": 10, \"progressTimeoutSeconds\": 600}');
INSERT INTO `aid_ai_provider` VALUES (20,'DeepSeek','deepseek','/aid/2026/07/17/33919808cdb2492da44d8889ff305675.jpg','https://api.deepseek.com','',NULL,'Authorization','Bearer ',NULL,NULL,NULL,'https://platform.deepseek.com/api_keys','https://api-docs.deepseek.com/zh-cn/','https://api-docs.deepseek.com/zh-cn/quick_start/pricing',NULL,'0','0','2026-07-16 11:14:05','system','2026-07-28 00:44:15','system','DeepSeek 开放平台（OpenAI 兼容 /chat/completions，base_url 无 /v1）；api_key 待运营填写；并发上限账号粒度 flash=2500/pro=500，超限上游 429',0,'{\"dispatchMode\": \"POLL_ONLY\", \"backoffFactor\": 1.5, \"maxRetryCount\": 120, \"maxConcurrency\": 5, \"maxLifeSeconds\": 3600, \"supportsCallback\": false, \"maxIntervalSeconds\": 30, \"baseIntervalSeconds\": 5, \"firstPollDelaySeconds\": 5, \"progressTimeoutSeconds\": 600}');
-- ----------------------------
-- Table structure for aid_ai_voice_library
-- ----------------------------
DROP TABLE IF EXISTS `aid_ai_voice_library`;
CREATE TABLE `aid_ai_voice_library`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `provider_id` bigint(20) NULL DEFAULT NULL COMMENT '所属服务商ID（冗余自 aid_ai_model.provider_id）',
  `model_id` bigint(20) NOT NULL COMMENT '所属AI模型ID（主归属，关联 aid_ai_model.id）',
  `voice_code` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '厂商侧真实 voice_id / 音色编码',
  `voice_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '展示名称',
  `avatar_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '头像图URL',
  `avatar_prompt` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '头像提示',
  `sample_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '试听音频URL',
  `sample_text` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '试听文案',
  `language` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '语言区域码：zh-CN / en-US / ja-JP',
  `gender` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '性别：female / male / neutral',
  `age_range` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '年龄段：child/teen/young/adult/middle/elderly',
  `character_types` json NULL COMMENT '角色类型 tag_code JSON 数组',
  `voice_styles` json NULL COMMENT '使用场景 tag_code JSON 数组',
  `tone_tags` json NULL COMMENT '音调 tag_code JSON 数组',
  `emotion_tags` json NULL COMMENT '擅长情感编码 JSON 数组（来源 aid_config.voice_emotion）',
  `supports_emotion` tinyint(1) NULL DEFAULT 0 COMMENT '是否支持情感参数',
  `supports_speed` tinyint(1) NULL DEFAULT 0 COMMENT '是否支持语速参数',
  `supports_pitch` tinyint(1) NULL DEFAULT 0 COMMENT '是否支持音调参数',
  `default_speed` decimal(4, 1) NULL DEFAULT 1.0 COMMENT '默认语速（0.5 ~ 2.0）',
  `default_pitch` decimal(4, 1) NULL DEFAULT 0.0 COMMENT '默认音调（-12 ~ 12）',
  `sample_rate` int(11) NULL DEFAULT NULL COMMENT '采样率，示例 16000/24000/48000',
  `audio_format` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '音频格式：mp3/wav/pcm',
  `offline_time` datetime NOT NULL DEFAULT '9999-12-31 00:00:00' COMMENT '下架时间(9999-12-31表示永不下架)',
  `sort_order` int(11) NOT NULL DEFAULT 0 COMMENT '排序（越大越靠前）',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '状态：0启用 1停用',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '删除标志：0存在 2删除',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_model_voice`(`model_id`, `voice_code`) USING BTREE,
  INDEX `idx_status_del_flag`(`status`, `del_flag`) USING BTREE,
  INDEX `idx_status_del_offline`(`status`, `del_flag`, `offline_time`) USING BTREE,
  INDEX `idx_provider_model`(`provider_id`, `model_id`) USING BTREE,
  INDEX `idx_language_gender_age`(`language`, `gender`, `age_range`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2021 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'AI音色库' ROW_FORMAT = Dynamic;

