INSERT INTO `aid_ai_voice_library` VALUES (17, 9, 42, 'zh_male_yizhipiannan_uranus_bigtts', '译制片男 2.0', '/aid/voice/avatar/2026/05/22/译制片男 2.0.jpg', '年轻男性戴金边眼镜，短发整齐，身穿白衬衫与黑色西装外套，背景纯白。人物面部清晰，神情沉稳，整体风格简洁正式，色彩对比鲜明', '/aid/voice/sample/2026/05/17/6ee25d6058d84ef487a5d999e51606f5.mp3', '在一个遥远的地方，流传着一段传说。', 'zh-CN', 'male', 'middle', '[\"大叔\"]', '[\"旁白\", \"角色配音\"]', '[\"沉稳\", \"磁性\"]', '[\"ASMR\"]', 1, 1, 1, 1.0, 0.0, 24000, 'mp3', '9999-12-31 00:00:00', 484, '0', NULL, '0', 'admin', '2026-05-10 23:44:32', 'system', '2026-05-22 23:07:39');
