INSERT INTO `aid_ai_voice_library` VALUES (20, 9, 42, 'zh_male_ruyaqingnian_uranus_bigtts', '儒雅青年 2.0', '/aid/voice/avatar/2026/05/22/儒雅青年 2.0.jpg', '年轻男性神情沉静，黑色长发微卷，身穿白色衬衫，冷色调背景虚化，清冷气质', '/aid/voice/sample/2026/05/17/f7d3040a84884984a144a3dd2a6ce4c8.mp3', '且听风吟，岁月静好。', 'zh-CN', 'male', 'young', '[\"青年\"]', '[\"对话\", \"旁白\"]', '[\"儒雅\", \"温柔\"]', '[\"ASMR\"]', 1, 1, 1, 1.0, 0.0, 24000, 'mp3', '9999-12-31 00:00:00', 481, '0', NULL, '0', 'admin', '2026-05-10 23:44:32', 'system', '2026-05-22 23:07:39');
