INSERT INTO `aid_ai_voice_library` VALUES (26, 9, 42, 'zh_male_fanjuanqingnian_uranus_bigtts', '反卷青年 2.0', '/aid/voice/avatar/2026/05/22/反卷青年 2.0.jpg', '年轻男性戴黑色棒球帽，帽前白色字母，肤色白皙，五官清秀，浅青色背景，风格简洁清新', '/aid/voice/sample/2026/05/17/3c16ec808a234053a14dbe3500e41ae3.mp3', '卷什么卷，躺平不好吗？', 'zh-CN', 'male', 'young', '[\"青年\"]', '[\"对话\"]', '[\"直率\"]', '[\"ASMR\"]', 1, 1, 1, 1.0, 0.0, 24000, 'mp3', '9999-12-31 00:00:00', 475, '0', NULL, '0', 'admin', '2026-05-10 23:44:32', 'system', '2026-05-22 23:07:39');
INSERT INTO `aid_ai_voice_library` VALUES (27, 9, 42, 'zh_female_wenroushunv_uranus_bigtts', '温柔淑女 2.0', '/aid/voice/avatar/2026/05/22/温柔淑女 2.0.jpg', '年轻女性面带淡然神情，黑发整齐，佩戴银色耳坠。背景为浅色渐变，整体风格清新自然', '/aid/voice/sample/2026/05/17/f849b2897a8946669d3c437806f63343.mp3', '翻开这一页，故事才刚刚开始。', 'zh-CN', 'female', 'adult', '[\"御姐\"]', '[\"对话\", \"有声书\"]', '[\"温柔\"]', '[\"ASMR\"]', 1, 1, 1, 1.0, 0.0, 24000, 'mp3', '9999-12-31 00:00:00', 474, '0', NULL, '0', 'admin', '2026-05-10 23:44:32', 'system', '2026-05-22 23:07:39');
INSERT INTO `aid_ai_voice_library` VALUES (28, 9, 42, 'zh_male_huolixiaoge_uranus_bigtts', '活力小哥 2.0', '/aid/voice/avatar/2026/05/22/活力小哥 2.0.jpg', '年轻男子灿烂笑容，手持彩色糖果，蓝色渐变背景，活泼可爱风格', '/aid/voice/sample/2026/05/17/6b988080f1c9455587d0c7573a62b3b4.mp3', '走！现在就出发吧！', 'zh-CN', 'male', 'young', '[\"弟弟\", \"少年\"]', '[\"对话\", \"有声书\"]', '[\"开朗\", \"活泼\"]', '[\"ASMR\"]', 1, 1, 1, 1.0, 0.0, 24000, 'mp3', '9999-12-31 00:00:00', 473, '0', NULL, '0', 'admin', '2026-05-10 23:44:32', 'system', '2026-05-22 23:07:39');
