INSERT INTO `aid_ai_voice_library` VALUES (79, 9, 42, 'zh_male_sunwukong_uranus_bigtts', '猴哥 2.0', '/aid/voice/avatar/2026/05/22/猴哥 2.0.jpg', '卡通猴子头像，棕色毛发，大眼睛，微笑表情，身穿红蓝相间衣服，背景为绿色渐变圆形，整体风格活泼可爱，色彩鲜明', '/aid/voice/sample/2026/05/17/2923ba26c2b74c6a868c8959ed62fff5.mp3', '俺老孙来也！吃俺一棒！', 'zh-CN', 'male', 'adult', '[\"IP人物\"]', '[\"视频配音\", \"角色配音\"]', '[\"开朗\", \"磁性\"]', '[\"ASMR\"]', 1, 1, 1, 1.0, 0.0, 24000, 'mp3', '9999-12-31 00:00:00', 399, '0', NULL, '0', 'admin', '2026-05-10 23:44:32', 'system', '2026-05-22 23:07:39');
INSERT INTO `aid_ai_voice_library` VALUES (80, 9, 42, 'zh_male_dayi_uranus_bigtts', '大壹 2.0', '/aid/voice/avatar/2026/05/22/大壹 2.0.jpg', '年轻男性正面凝视，短发整齐，五官清秀，肤色白皙。背景为柔和的暖黄色，整体风格简洁明亮', '/aid/voice/sample/2026/05/17/af46a0b13fa341cc9d2b5959cacfb41c.mp3', '大家好，我是大壹，欢迎收看！', 'zh-CN', 'male', 'young', '[\"青年\"]', '[\"视频配音\", \"对话\"]', '[\"开朗\", \"清澈\"]', '[\"ASMR\"]', 1, 1, 1, 1.0, 0.0, 24000, 'mp3', '9999-12-31 00:00:00', 398, '0', NULL, '0', 'admin', '2026-05-10 23:44:32', 'system', '2026-05-22 23:07:39');
INSERT INTO `aid_ai_voice_library` VALUES (81, 9, 42, 'zh_female_mizai_uranus_bigtts', '黑猫侦探社咪仔 2.0', '/aid/voice/avatar/2026/05/22/黑猫侦探社咪仔 2.0.jpg', '短发女性，面带微笑，肤色白皙，眼神温和。背景为浅蓝色，整体风格清新自然', '/aid/voice/sample/2026/05/17/a94aab93f8a34d7688c410e6fb9488aa.mp3', '喵~真相就藏在这些线索里！', 'zh-CN', 'female', 'young', '[\"少女\", \"IP人物\"]', '[\"视频配音\", \"角色配音\"]', '[\"奶气\", \"活泼\"]', '[\"ASMR\"]', 1, 1, 1, 1.0, 0.0, 24000, 'mp3', '9999-12-31 00:00:00', 397, '0', NULL, '0', 'admin', '2026-05-10 23:44:32', 'system', '2026-05-22 23:07:39');
INSERT INTO `aid_ai_voice_library` VALUES (82, 9, 42, 'zh_female_jitangnv_uranus_bigtts', '鸡汤女 2.0', '/aid/voice/avatar/2026/05/22/鸡汤女 2.0.jpg', '年轻女性，黑色短发，戴细框眼镜，面带微笑。背景为浅蓝色，整体风格清新明亮', '/aid/voice/sample/2026/05/17/0dcaa8e4883e4e54b8b631ff3a63858a.mp3', '你不是失败，你只是在成长。', 'zh-CN', 'female', 'adult', '[\"御姐\"]', '[\"视频配音\", \"有声书\"]', '[\"温暖\", \"温柔\"]', '[\"ASMR\"]', 1, 1, 1, 1.0, 0.0, 24000, 'mp3', '9999-12-31 00:00:00', 396, '0', NULL, '0', 'admin', '2026-05-10 23:44:32', 'system', '2026-05-22 23:07:39');
INSERT INTO `aid_ai_voice_library` VALUES (83, 9, 42, 'zh_female_liuchangnv_uranus_bigtts', '流畅女声 2.0', '/aid/voice/avatar/2026/05/22/流畅女声 2.0.jpg', '年轻女性微笑，黑发微卷齐刘海，绿植背景虚化，自然光，清新自然', '/aid/voice/sample/2026/05/17/5827b7393e28490e875c4daa81071a06.mp3', '从数据来看，这个结论很清晰。', 'zh-CN', 'female', 'adult', '[\"御姐\"]', '[\"视频配音\", \"旁白\"]', '[\"清澈\"]', '[\"ASMR\"]', 1, 1, 1, 1.0, 0.0, 24000, 'mp3', '9999-12-31 00:00:00', 395, '0', NULL, '0', 'admin', '2026-05-10 23:44:32', 'system', '2026-05-22 23:07:39');
INSERT INTO `aid_ai_voice_library` VALUES (84, 9, 42, 'zh_male_ruyayichen_uranus_bigtts', '儒雅逸辰 2.0', '/aid/voice/avatar/2026/05/22/儒雅逸辰 2.0.jpg', '年轻男性神情淡然，短发整齐，五官立体，肤色自然，浅绿色背景，风格简洁清新', '/aid/voice/sample/2026/05/17/e1146906eda54599a5a4b8e4c34f51da.mp3', '世间万物，皆有定数。', 'zh-CN', 'male', 'young', '[\"公子\", \"青年\"]', '[\"视频配音\", \"有声书\"]', '[\"儒雅\", \"温柔\"]', '[\"ASMR\"]', 1, 1, 1, 1.0, 0.0, 24000, 'mp3', '9999-12-31 00:00:00', 394, '0', NULL, '0', 'admin', '2026-05-10 23:44:32', 'system', '2026-05-22 23:07:39');
INSERT INTO `aid_ai_voice_library` VALUES (85, 9, 42, 'zh_female_yingyujiaoxue_uranus_bigtts', 'Tina老师 2.0', '/aid/voice/avatar/2026/05/22/Tina老师.jpg', '戴黑框眼镜的年轻女性，棕色卷发，面带微笑，卡通渲染风格，暖色调柔和', '/aid/voice/sample/2026/05/17/b1603ad049d64b32b47338306f589865.mp3', '同学们好，今天我们来学习新知识。', 'zh-CN', 'female', 'adult', '[\"御姐\"]', '[\"教育\", \"对话\"]', '[\"温柔\", \"清澈\"]', '[\"ASMR\"]', 1, 1, 1, 1.0, 0.0, 24000, 'mp3', '9999-12-31 00:00:00', 380, '0', '中英双语', '0', 'admin', '2026-05-10 23:44:32', 'system', '2026-05-22 23:07:39');
INSERT INTO `aid_ai_voice_library` VALUES (87, 9, 42, 'zh_female_xiaoxue_uranus_bigtts', '儿童绘本 2.0', '/aid/voice/avatar/2026/05/22/儿童绘本 2.0.jpg', '年轻女性面带微笑，短卷发自然垂落，肤色白皙，五官清秀，简洁背景，风格清新自然', '/aid/voice/sample/2026/05/17/707028c66389476fad43928cc12c376d.mp3', '很久很久以前，有一座美丽的城堡。', 'zh-CN', 'female', 'young', '[\"少女\"]', '[\"有声书\", \"教育\"]', '[\"温柔\", \"甜美\", \"清澈\"]', '[\"ASMR\"]', 1, 1, 1, 1.0, 0.0, 24000, 'mp3', '9999-12-31 00:00:00', 360, '0', NULL, '0', 'admin', '2026-05-10 23:44:32', 'system', '2026-05-22 23:07:39');
INSERT INTO `aid_ai_voice_library` VALUES (89, 9, 42, 'zh_male_xuanyijieshuo_uranus_bigtts', '悬疑解说 2.0', '/aid/voice/avatar/2026/05/22/悬疑解说 2.0.jpg', '老年男性灰白胡须，表情严肃，眼神深邃，深色背景，写实庄重风格', '/aid/voice/sample/2026/05/17/02b08f290ff74a07ac7ac5c04329b7f5.mp3', '当夜幕降临，秘密才会浮出水面。', 'zh-CN', 'male', 'adult', '[\"大叔\"]', '[\"有声书\", \"旁白\"]', '[\"沉稳\", \"磁性\", \"冷艳\"]', '[\"ASMR\"]', 1, 1, 1, 1.0, 0.0, 24000, 'mp3', '9999-12-31 00:00:00', 358, '0', NULL, '0', 'admin', '2026-05-10 23:44:32', 'system', '2026-05-22 23:07:39');
INSERT INTO `aid_ai_voice_library` VALUES (90, 9, 42, 'zh_female_shaoergushi_uranus_bigtts', '少儿故事 2.0', '/aid/voice/avatar/2026/05/22/少儿故事 2.0.jpg', '年轻女孩直视镜头，面庞清秀，黑发柔顺，眼神清澈。背景简洁，整体风格清新自然', '/aid/voice/sample/2026/05/17/2fd4603bd7fb452ab92f9a3c33f30e74.mp3', '小兔子乖乖，把门儿开开~', 'zh-CN', 'female', 'young', '[\"少女\"]', '[\"有声书\", \"教育\"]', '[\"甜美\", \"温柔\", \"奶气\"]', '[\"ASMR\"]', 1, 1, 1, 1.0, 0.0, 24000, 'mp3', '9999-12-31 00:00:00', 357, '0', NULL, '0', 'admin', '2026-05-10 23:44:32', 'system', '2026-05-22 23:07:39');
INSERT INTO `aid_ai_voice_library` VALUES (94, 9, 42, 'saturn_zh_female_tiaopigongzhu_tob', '调皮公主', '/aid/voice/avatar/2026/05/22/调皮公主.jpg', '年轻女子面带淡妆，眼神清澈。她佩戴金色皇冠与耳坠，发髻精致，背景深色衬托出面部轮廓。整体风格古典优雅', '/aid/voice/sample/2026/05/17/7c3fc521d0b04562bdb20d33cd8b1f38.mp3', '哼！我才不要听你的呢！', 'zh-CN', 'female', 'young', '[\"少女\"]', '[\"角色配音\"]', '[\"活泼\", \"甜美\"]', '[\"ASMR\"]', 1, 1, 1, 1.0, 0.0, 24000, 'mp3', '9999-12-31 00:00:00', 320, '0', '声音复刻2.0 · saturn 前缀 · COT/QA', '0', 'admin', '2026-05-10 23:44:32', 'system', '2026-05-22 23:07:39');
INSERT INTO `aid_ai_voice_library` VALUES (95, 9, 42, 'saturn_zh_female_keainvsheng_tob', '可爱女生', '/aid/voice/avatar/2026/05/22/可爱女生.jpg', '黑发女孩面带微笑，头戴粉色发饰，身穿校服，背景简洁。色彩柔和，风格清新可爱', '/aid/voice/sample/2026/05/17/7a825be4ba3f4460a28484c67e3e6e5d.mp3', '嘿嘿，今天放学去哪儿玩？', 'zh-CN', 'female', 'young', '[\"少女\", \"学生\"]', '[\"角色配音\", \"对话\"]', '[\"甜美\", \"活泼\"]', '[\"ASMR\"]', 1, 1, 1, 1.0, 0.0, 24000, 'mp3', '9999-12-31 00:00:00', 319, '0', '声音复刻2.0 · saturn 前缀 · COT/QA', '0', 'admin', '2026-05-10 23:44:32', 'system', '2026-05-22 23:07:39');
INSERT INTO `aid_ai_voice_library` VALUES (96, 9, 42, 'saturn_zh_male_shuanglangshaonian_tob', '爽朗少年', '/aid/voice/avatar/2026/05/22/爽朗少年.jpg', '年轻男性面带微笑，身穿白色运动服，头戴白色耐克发带。背景为浅蓝色渐变，整体风格简洁清新，色彩明亮柔和', '/aid/voice/sample/2026/05/17/ae6aa5c9491e41eb85fffe7854efef6a.mp3', '爽快！这事就这么定了！', 'zh-CN', 'male', 'teen', '[\"少年\"]', '[\"角色配音\", \"对话\"]', '[\"开朗\", \"直率\"]', '[\"ASMR\"]', 1, 1, 1, 1.0, 0.0, 24000, 'mp3', '9999-12-31 00:00:00', 318, '0', '声音复刻2.0 · saturn 前缀 · COT/QA', '0', 'admin', '2026-05-10 23:44:32', 'system', '2026-05-22 23:07:39');
INSERT INTO `aid_ai_voice_library` VALUES (97, 9, 42, 'saturn_zh_male_tiancaitongzhuo_tob', '天才同桌', '/aid/voice/avatar/2026/05/22/天才同桌.jpg', '年轻男性，戴黑框眼镜，短发，穿浅色衬衫。背景为渐变蓝，神情专注，整体风格简洁清新', '/aid/voice/sample/2026/05/17/8712be534d774d67b2280d48ebecc9cf.mp3', '这道题的解法，其实很简单。', 'zh-CN', 'male', 'teen', '[\"少年\", \"学霸\", \"学生\"]', '[\"角色配音\", \"对话\"]', '[\"儒雅\", \"清澈\"]', '[\"ASMR\"]', 1, 1, 1, 1.0, 0.0, 24000, 'mp3', '9999-12-31 00:00:00', 317, '0', '声音复刻2.0 · saturn 前缀 · COT/QA', '0', 'admin', '2026-05-10 23:44:32', 'system', '2026-05-22 23:07:39');
INSERT INTO `aid_ai_voice_library` VALUES (98, 9, 42, 'saturn_zh_female_cancan_tob', '知性灿灿', '/aid/voice/avatar/2026/05/22/知性灿灿.jpg', '白发少女，面带微笑，眼神明亮。背景为粉色渐变，整体风格清新可爱集中于面部表情', '/aid/voice/sample/2026/05/17/a8b4e99bdeb84b8db6c0b8cd077bb35f.mp3', '世事洞明皆学问，人情练达即文章。', 'zh-CN', 'female', 'young', '[\"御姐\"]', '[\"角色配音\", \"对话\"]', '[\"温柔\", \"磁性\"]', '[\"ASMR\"]', 1, 1, 1, 1.0, 0.0, 24000, 'mp3', '9999-12-31 00:00:00', 316, '0', '声音复刻2.0 · saturn 前缀 · COT/QA', '0', 'admin', '2026-05-10 23:44:32', 'system', '2026-05-22 23:07:39');
INSERT INTO `aid_ai_voice_library` VALUES (99, 9, 42, 'saturn_zh_female_qingyingduoduo_cs_tob', '轻盈朵朵 2.0', '/aid/voice/avatar/2026/05/22/轻盈朵朵 2.0.jpg', '年轻女性，浅棕色卷发，淡妆，面带微笑。背景为浅蓝色渐变，整体风格清新自然', '/aid/voice/sample/2026/05/17/2694a65dd7cc47c38bbfdbb581f97443.mp3', '您请放心，我这就为您查询。', 'zh-CN', 'female', 'young', '[\"客服\"]', '[\"客服\", \"对话\"]', '[\"清澈\", \"甜美\"]', '[]', 0, 1, 1, 1.0, 0.0, 24000, 'mp3', '9999-12-31 00:00:00', 280, '0', 'saturn 前缀 · 指令遵循', '0', 'admin', '2026-05-10 23:44:32', 'system', '2026-05-22 23:07:39');
INSERT INTO `aid_ai_voice_library` VALUES (100, 9, 42, 'saturn_zh_female_wenwanshanshan_cs_tob', '温婉珊珊 2.0', '/aid/voice/avatar/2026/05/22/温婉珊珊 2.0.jpg', '年轻女性面带淡妆，短卷发自然垂落，眼神柔和直视前方。整体色调柔和，风格清新自然', '/aid/voice/sample/2026/05/17/2bad83e9ad654c8d9f19800ae4c359e0.mp3', '感谢您的耐心等待，已经处理好了。', 'zh-CN', 'female', 'adult', '[\"客服\"]', '[\"客服\", \"对话\"]', '[\"温柔\", \"温暖\"]', '[]', 0, 1, 1, 1.0, 0.0, 24000, 'mp3', '9999-12-31 00:00:00', 279, '0', 'saturn 前缀 · 指令遵循', '0', 'admin', '2026-05-10 23:44:32', 'system', '2026-05-22 23:07:39');
INSERT INTO `aid_ai_voice_library` VALUES (101, 9, 42, 'saturn_zh_female_reqingaina_cs_tob', '热情艾娜 2.0', '/aid/voice/avatar/2026/05/22/热情艾娜 2.0.jpg', '年轻女性面带微笑，双马尾发型，穿着浅色上衣。背景简洁，整体风格清新自然', '/aid/voice/sample/2026/05/17/07c76ea5e7e1410aa13d851c248ea3f1.mp3', '您好呀！很高兴为您服务！', 'zh-CN', 'female', 'young', '[\"客服\"]', '[\"客服\", \"对话\"]', '[\"开朗\", \"温暖\"]', '[]', 0, 1, 1, 1.0, 0.0, 24000, 'mp3', '9999-12-31 00:00:00', 278, '0', 'saturn 前缀 · 指令遵循', '0', 'admin', '2026-05-10 23:44:32', 'system', '2026-05-22 23:07:39');
INSERT INTO `aid_ai_voice_library` VALUES (102, 9, 42, 'saturn_zh_male_qingxinmumu_cs_tob', '清新沐沐 2.0', '/aid/voice/avatar/2026/05/22/清新沐沐 2.0.jpg', '年轻男性短黑发，微笑，眼神明亮，白色上衣，浅蓝背景，清新自然', '/aid/voice/sample/2026/05/17/2a88580f318246c7b3e8f59d69666ce7.mp3', '您的问题我已经记录，马上跟进。', 'zh-CN', 'male', 'young', '[\"客服\"]', '[\"客服\", \"对话\"]', '[\"清澈\", \"温柔\"]', '[]', 0, 1, 1, 1.0, 0.0, 24000, 'mp3', '9999-12-31 00:00:00', 277, '0', 'saturn 前缀 · 指令遵循', '0', 'admin', '2026-05-10 23:44:32', 'system', '2026-05-22 23:07:39');

-- ----------------------------
-- Table structure for aid_ai_voice_tag
-- ----------------------------
DROP TABLE IF EXISTS `aid_ai_voice_tag`;
CREATE TABLE `aid_ai_voice_tag`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `tag_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '标签类型：character_type / voice_style / tone',
  `tag_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '标签编码（同一 tag_type 下唯一）',
  `tag_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '标签展示名',
  `sort_order` int(11) NOT NULL DEFAULT 0 COMMENT '排序（越大越靠前）',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '状态：0启用 1停用',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '删除标志：0存在 2删除',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_tag_type_code`(`tag_type`, `tag_code`) USING BTREE,
  INDEX `idx_type_status_del`(`tag_type`, `status`, `del_flag`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 56 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'AI音色标签字典' ROW_FORMAT = Dynamic;

