-- ----------------------------
-- Table structure for aid_audio_asset
-- ----------------------------
DROP TABLE IF EXISTS `aid_audio_asset`;
CREATE TABLE `aid_audio_asset`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint(20) NOT NULL COMMENT '归属用户ID',
  `project_id` bigint(20) NULL DEFAULT NULL COMMENT '项目ID（可空，项目级音频不绑）',
  `episode_id` bigint(20) NULL DEFAULT NULL COMMENT '剧集ID（可空）',
  `storyboard_id` bigint(20) NULL DEFAULT NULL COMMENT '分镜ID（可空）',
  `audio_record_id` bigint(20) NULL DEFAULT NULL COMMENT '来源 aid_audio_record.id（唯一）',
  `media_task_id` bigint(20) NULL DEFAULT NULL COMMENT '来源 aid_media_task.id',
  `audio_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '音频 OSS 相对路径（@MediaUrl 拼域名）',
  `file_size` bigint(20) NULL DEFAULT NULL COMMENT '文件大小（字节）',
  `audio_format` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '音频格式：mp3 / wav / pcm',
  `sample_rate` int(11) NULL DEFAULT NULL COMMENT '采样率（16000/24000/48000）',
  `tts_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '配音文字',
  `voice_library_id` bigint(20) NULL DEFAULT NULL COMMENT '音色库ID（aid_ai_voice_library.id）',
  `voice_model_id` bigint(20) NULL DEFAULT NULL COMMENT '配音模型ID',
  `voice_code` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '厂商音色编码（voice_id）',
  `voice_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '音色展示名',
  `emotion` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '情感（happy / sad ...）',
  `speech_rate` int(11) NULL DEFAULT NULL COMMENT '语速',
  `loudness_rate` int(11) NULL DEFAULT NULL COMMENT '音量',
  `pitch` int(11) NULL DEFAULT NULL COMMENT '音调',
  `audio_source` tinyint(4) NOT NULL DEFAULT 1 COMMENT '来源（1:AI生成 2:用户上传）',
  `asset_title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '资产标题（默认取 tts_text 截断）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '删除标志（0:正常 2:删除）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_audio_task`(`audio_record_id`) USING BTREE,
  INDEX `idx_user_project`(`user_id`, `project_id`, `create_time`) USING BTREE,
  INDEX `idx_user_episode`(`user_id`, `episode_id`, `create_time`) USING BTREE,
  INDEX `idx_storyboard`(`storyboard_id`) USING BTREE,
  INDEX `idx_voice_library`(`voice_library_id`) USING BTREE,
  INDEX `idx_media_task`(`media_task_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '音频资产' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aid_audio_asset
-- ----------------------------

-- ----------------------------
-- Table structure for aid_audio_record
-- ----------------------------
DROP TABLE IF EXISTS `aid_audio_record`;
CREATE TABLE `aid_audio_record`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint(20) NOT NULL COMMENT '所属用户ID',
  `project_id` bigint(20) NULL DEFAULT NULL COMMENT '所属项目ID（与 aid_media_task 对齐）',
  `episode_id` bigint(20) NULL DEFAULT NULL COMMENT '所属剧集ID（电影模式为0）',
  `storyboard_id` bigint(20) NOT NULL COMMENT '所属分镜ID（aid_storyboard.id）',
  `audio_source` tinyint(4) NOT NULL COMMENT '音频来源：1=AI文字配音(TTS)，2=用户上传',
  `tts_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT 'TTS 待合成文本（audio_source=1 时使用）',
  `voice_model_id` bigint(20) NULL DEFAULT NULL COMMENT 'TTS 模型ID（关联 aid_ai_model.id）',
  `voice_library_id` bigint(20) NULL DEFAULT NULL COMMENT '音色库ID（关联 aid_ai_voice_library.id）',
  `timbre_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '厂商侧音色编码',
  `audio_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '配音文件 OSS URL（TTS 成功且 OSS 已就绪后回填，或用户上传后直接落库）',
  `duration_ms` int(11) NULL DEFAULT NULL COMMENT '音频时长（毫秒）',
  `enable_lip_sync` tinyint(4) NULL DEFAULT 0 COMMENT '是否对口型：0=否，1=是',
  `sync_video_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '对口型视频 OSS URL（enable_lip_sync=1 且对口型任务成功后回填）',
  `tts_media_task_id` bigint(20) NULL DEFAULT NULL COMMENT 'TTS 媒体任务ID（关联 aid_media_task.id），audio_source=1 时填充',
  `sync_media_task_id` bigint(20) NULL DEFAULT NULL COMMENT '对口型媒体任务ID（关联 aid_media_task.id），enable_lip_sync=1 时填充',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'PROCESSING' COMMENT '配音状态(PROCESSING处理中 SUCCEEDED成功 FAILED失败, OSS就绪后才置成功)',
  `error_message` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '失败短文案（≤6 字，给用户看）',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志（0=存在 1=已删除）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `compose_batch_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '合成批次号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_storyboard_id`(`storyboard_id`) USING BTREE,
  INDEX `idx_user_project`(`user_id`, `project_id`, `episode_id`) USING BTREE,
  INDEX `idx_tts_task`(`tts_media_task_id`) USING BTREE,
  INDEX `idx_sync_task`(`sync_media_task_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '配音记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aid_audio_record
-- ----------------------------

-- ----------------------------
-- Table structure for aid_balance_log
-- ----------------------------
DROP TABLE IF EXISTS `aid_balance_log`;
CREATE TABLE `aid_balance_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint(20) NOT NULL COMMENT '用户ID',
  `change_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '变动类型 (recharge充值/consume消费/refund退款/freeze冻结/unfreeze解冻)',
  `amount` decimal(12, 2) NOT NULL COMMENT '变动金额 (正数增加, 负数减少)',
  `before_balance` decimal(12, 2) NOT NULL COMMENT '变动前余额',
  `after_balance` decimal(12, 2) NOT NULL COMMENT '变动后余额',
  `related_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '关联业务ID (订单号/充值流水号等)',
  `biz_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '业务类型 (chat对话/create创作/recharge充值/refund退款等)',
  `biz_name` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '业务名称 (对话消耗/创作消耗/余额充值等)',
  `model_code` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '实际使用模型编码，多个用英文逗号分隔',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志（0代表存在 1代表删除）',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '余额变动记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aid_balance_log
-- ----------------------------

-- ----------------------------
-- Table structure for aid_comic_asset
-- ----------------------------
DROP TABLE IF EXISTS `aid_comic_asset`;
CREATE TABLE `aid_comic_asset`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `asset_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '类型: scene场景, character角色, prop道具',
  `asset_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '资产名称',
  `personality_desc` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '性格/特征描述(用于生成约束)',
  `prompt_text` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提示词',
  `image_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '主图',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0',
  `create_time` datetime NULL DEFAULT NULL,
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '',
  `update_time` datetime NULL DEFAULT NULL,
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_asset_type`(`asset_type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 307 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '官方漫画资产表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aid_comic_asset
-- ----------------------------
INSERT INTO `aid_comic_asset` VALUES (1, 'style', '赛博朋克风', NULL, '赛博朋克数字概念插画风格，参考押井守《攻壳机动队》美术设定，2D数字绘画，厚涂笔触，霓虹品红与青蓝为主调，低饱和冷调，冷峻压抑的未来感。', '/aid/style/sample/1-linghu_01.jpg', '0', '2026-03-31 00:20:17', 'system', '2026-07-26 19:19:40', 'system', NULL);
INSERT INTO `aid_comic_asset` VALUES (2, 'style', '水墨国风', NULL, '中国水墨画风格，参考《山水情》水墨动画，宣纸质感，墨分五色浓淡干湿，大量留白，写意飘逸的笔触，清雅疏淡的东方意境。', '/aid/style/sample/1-linghu_02.jpg', '0', '2026-03-31 00:20:17', 'system', '2026-07-26 19:19:40', 'system', NULL);
INSERT INTO `aid_comic_asset` VALUES (3, 'style', '古典油画风', NULL, '古典学院派油画风格，参考伦勃朗与维米尔油画，画布肌理，厚涂笔触与刀痕清晰，暗棕、赭石、暖褐的低明度调色，戏剧性明暗对照，庄重典雅。', '/aid/style/sample/1-linghu_03.jpg', '0', '2026-03-31 00:20:17', 'system', '2026-07-26 19:19:40', 'system', NULL);
INSERT INTO `aid_comic_asset` VALUES (4, 'style', '治愈水彩', NULL, '水彩插画风格，水彩纸纹理，湿画法晕染，边缘柔化，颜料自然流淌与透明叠色，浅淡低饱和的柔和色调，温柔治愈。', '/aid/style/sample/1-linghu_04.jpg', '0', '2026-03-31 00:20:17', 'system', '2026-07-26 19:19:40', 'system', NULL);
INSERT INTO `aid_comic_asset` VALUES (5, 'style', '怀旧像素', NULL, '像素艺术风格，16位复古游戏画面，低分辨率马赛克，硬边方块像素，有限调色板，抖动渐变，复古电子游戏的怀旧感。', '/aid/style/sample/1-linghu_05.jpg', '0', '2026-03-31 00:20:17', 'system', '2026-07-26 19:19:40', 'system', NULL);
INSERT INTO `aid_comic_asset` VALUES (6, 'style', '哥特暗黑风', NULL, '哥特暗黑数字插画风格，参考蒂姆·伯顿视觉美术，2D绘画，锐利尖角线条，繁复装饰纹样，墨黑、暗紫、惨白的低饱和调色，阴郁诡谲。', '/aid/style/sample/1-linghu_06.jpg', '0', '2026-03-31 00:20:17', 'system', '2026-07-26 19:19:40', 'system', NULL);
INSERT INTO `aid_comic_asset` VALUES (7, 'style', '蒸汽朋克风', NULL, '蒸汽朋克数字概念插画风格，维多利亚时代工业美学，2D厚涂绘画，黄铜齿轮与铆钉质感，做旧金属与皮革肌理，棕褐、古铜、暗金的偏暖单色调，复古机械感。', '/aid/style/sample/1-linghu_07.jpg', '0', '2026-03-31 00:20:17', 'system', '2026-07-26 19:19:40', 'system', NULL);
INSERT INTO `aid_comic_asset` VALUES (8, 'style', '极简扁平', NULL, '扁平化矢量插画风格，无描边纯色块拼接，几何化造型，无渐变无阴影，高饱和撞色搭配，干净简洁的现代设计感。', '/aid/style/sample/1-linghu_08.jpg', '0', '2026-03-31 00:20:17', 'system', '2026-07-26 19:19:40', 'system', NULL);
INSERT INTO `aid_comic_asset` VALUES (9, 'style', '传统工笔', NULL, '中国工笔画风格，参考传统工笔重彩，绢本设色，细笔勾线匀细流畅，层层分染罩染，矿物颜料的沉稳色泽，典雅精致。', '/aid/style/sample/1-linghu_09.jpg', '0', '2026-03-31 00:20:17', 'system', '2026-07-26 19:19:40', 'system', NULL);
INSERT INTO `aid_comic_asset` VALUES (10, 'style', '手绘速写', NULL, '铅笔速写风格，纸面素描，无上色，线条松弛奔放，排线塑造明暗，保留起稿辅助线，快速捕捉的手绘草稿感。', '/aid/style/sample/2-linghu_01.jpg', '0', '2026-03-31 00:20:17', 'system', '2026-07-26 19:19:40', 'system', NULL);
INSERT INTO `aid_comic_asset` VALUES (11, 'style', '经典日漫', NULL, '日式2D动画风格，参考90年代TV动画作画，赛璐璐上色，动画截图，线条清晰硬朗，色彩鲜明，色块分明的传统动画质感。', '/aid/style/sample/2-linghu_02.jpg', '0', '2026-03-31 00:20:17', 'system', '2026-07-26 19:19:40', 'system', NULL);
INSERT INTO `aid_comic_asset` VALUES (12, 'style', '经典美漫', NULL, '美式漫画风格，参考漫威与DC经典期刊，2D手绘，粗黑描边，网点半调印刷质感，高饱和原色，强烈的漫画视觉张力。', '/aid/style/sample/2-linghu_03.jpg', '0', '2026-03-31 00:20:17', 'system', '2026-07-26 19:19:40', 'system', NULL);
INSERT INTO `aid_comic_asset` VALUES (13, 'style', '治愈动画', NULL, '参考宫崎骏动画电影作品，吉卜力动画风格，2D动画，动画截图，手绘美术质感，柔和自然光，温润通透的水彩上色，恬静治愈。', '/aid/style/sample/2-linghu_04.jpg', '0', '2026-03-31 00:20:17', 'system', '2026-07-26 19:19:40', 'system', NULL);
INSERT INTO `aid_comic_asset` VALUES (14, 'style', '复古少女', NULL, '90年代少女漫画动画风格，参考《美少女战士》《凡尔赛玫瑰》，2D日式动画，纤细流畅线条，柔和粉彩色调，网点与闪光装饰，浪漫怀旧。', '/aid/style/sample/2-linghu_05.jpg', '0', '2026-03-31 00:20:17', 'system', '2026-07-26 19:19:40', 'system', NULL);
INSERT INTO `aid_comic_asset` VALUES (15, 'style', '唯美韩漫', NULL, '韩式网络条漫风格，参考韩国头部条漫作画，2D数字绘画，干净细腻线条，柔和渐变上色，通透光泽质感，高饱和明亮色调，时尚精致。', '/aid/style/sample/2-linghu_06.jpg', '0', '2026-03-31 00:20:17', 'system', '2026-07-26 19:19:40', 'system', NULL);
INSERT INTO `aid_comic_asset` VALUES (16, 'style', '热血漫画', NULL, '日式少年热血漫画风格，参考《鬼灭之刃》《进击的巨人》动画作画，2D动画，粗重顿挫线条，强烈明暗对比，高饱和浓烈色彩，速度线与冲击特效，紧张激烈。', '/aid/style/sample/2-linghu_07.jpg', '0', '2026-03-31 00:20:17', 'system', '2026-07-26 19:19:40', 'system', NULL);
