INSERT INTO `aid_comic_asset` VALUES (18, 'style', '童趣幻想', NULL, '低龄向童话动画风格，2D卡通，圆润饱满的造型，粗描边，无渐变的明快纯色块，柔和均匀打光，天真烂漫的童趣感。', '/aid/style/sample/2-linghu_09.jpg', '0', '2026-03-31 00:20:17', 'system', '2026-07-26 19:19:40', 'system', NULL);
