INSERT INTO `aid_comic_asset` VALUES (20, 'style', '都市志怪', NULL, '现代都市怪谈动画风格，参考《咒术回战》《夏目友人帐》，2D日式动画，细腻线条，冷调低饱和色彩，朦胧光晕，灵异幽微的氛围感。', '/aid/style/sample/3-linghu_02.jpg', '0', '2026-03-31 00:20:17', 'system', '2026-07-26 19:19:40', 'system', NULL);
