INSERT INTO `aid_comic_asset` VALUES (46, 'style', '写实电影', NULL, '参考院线电影，真人电影风格，影视大片，真实透视比例，真实皮肤质感，自然光影，35mm胶片颗粒，细节清晰不过度锐化。', '/aid/style/sample/6-linghu_01.jpg', '0', '2026-03-31 00:20:17', 'system', '2026-07-26 19:19:40', 'system', NULL);
INSERT INTO `aid_comic_asset` VALUES (47, 'style', '复古胶片', NULL, '70年代复古胶片摄影风格，真人写实摄影，明显胶片颗粒，漏光与暗角，低饱和褪色偏黄的暖调，轻微失焦柔化，怀旧老照片质感。', '/aid/style/sample/6-linghu_02.jpg', '0', '2026-03-31 00:20:17', 'system', '2026-07-26 19:19:40', 'system', NULL);
INSERT INTO `aid_comic_asset` VALUES (48, 'style', '真实古装', NULL, '国产古装剧影像风格，参考《甄嬛传》《大宅门》《庆余年》电视剧质感，真人写实摄影，电影感，非精心打光，低饱和沉稳的东方色调，极致细节，实拍感。', '/aid/style/sample/6-linghu_03.jpg', '0', '2026-03-31 00:20:17', 'system', '2026-07-26 19:19:40', 'system', NULL);
INSERT INTO `aid_comic_asset` VALUES (49, 'style', '复古港片', NULL, '90年代港片影像风格，参考王家卫电影质感，真人写实摄影，电影感，胶片颗粒与轻微拖影，浓郁暖调、暗金、墨绿与霓虹红，暧昧疏离的复古港味。', '/aid/style/sample/6-linghu_04.jpg', '0', '2026-03-31 00:20:17', 'system', '2026-07-26 19:19:40', 'system', NULL);
INSERT INTO `aid_comic_asset` VALUES (50, 'style', '复古武侠', NULL, '港式武侠电影影像风格，真人写实摄影，电影感，画面粗粝写实、江湖气十足、硬朗生猛，青灰、墨绿、土黄的户外环境色调，风沙烟尘的空气感。', '/aid/style/sample/6-linghu_05.jpg', '0', '2026-03-31 00:20:17', 'system', '2026-07-26 19:19:40', 'system', NULL);
INSERT INTO `aid_comic_asset` VALUES (51, 'style', '真实光晕', NULL, '电影感真人写实摄影，变形宽银幕镜头，横向蓝色镜头光斑，逆光漏光与辉光，浅景深虚化，金色时刻的暖调光线，通透梦幻的光晕氛围。', '/aid/style/sample/6-linghu_06.jpg', '0', '2026-03-31 00:20:17', 'system', '2026-07-26 19:19:40', 'system', NULL);
INSERT INTO `aid_comic_asset` VALUES (52, 'reference_scene', '现代居家客厅·日·内景·春·晴·无人', 'cinematic wide shot of a modern cozy living room interior, warm sunlight streaming through large floor-to-ceiling windows casting soft shadows on beige fabric sofa, wooden coffee table with a vase of fresh cherry blossoms, cream walls with abstract art prints, open-plan connected to a bright kitchen, light oak flooring, sheer white curtains gently swaying, spring afternoon atmosphere, photorealistic, 8K --ar 1:1', '现代温馨客厅，春日午后阳光透过落地窗洒在米色布艺沙发上，木茶几上放着插有樱花的玻璃花瓶，奶油色墙面配抽象画，开放式厨房连通，浅橡木地板，白色纱帘轻摆，温暖明亮的居家氛围', '/aid/lib/scene/2026/07/09/现代居家客厅·日·内景·春·晴·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/06/15/现代居家客厅·日·内景·春·晴·无人.png');
INSERT INTO `aid_comic_asset` VALUES (53, 'reference_scene', '现代居家卧室·夜·内景·秋·雨·无人', 'cinematic low-key shot of a modern minimalist bedroom at night, soft warm bedside lamp glow creating intimate shadows, queen bed with grey linen bedding slightly rumpled, raindrops streaking down the window glass reflecting distant city lights, dark wood nightstand with a half-read book, plush wool rug on dark flooring, gentle melancholic autumn night atmosphere, photorealistic, 8K --ar 1:1', '深夜极简现代卧室，床头暖灯投射温柔光影，灰色亚麻床品微皱，雨滴沿窗玻璃滑落映出远方城市灯火，深木床头柜上放着半开的书，柔软羊毛毯铺在深色地板上，秋夜微愁氛围', '/aid/lib/scene/2026/07/09/现代居家卧室·夜·内景·秋·雨·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/06/15/现代居家卧室·夜·内景·秋·雨·无人.png');
INSERT INTO `aid_comic_asset` VALUES (54, 'reference_scene', '居民楼楼道·日·内景·冬·雾·无人', 'cinematic corridor perspective of a residential building hallway, pale white fluorescent ceiling lights, rows of identical grey security doors on both sides, worn terrazzo floor tiles with faint scuff marks, fog visible through the small window at the far end, walls painted light beige with slight peeling, emergency exit sign glowing green, slightly cold and desolate atmosphere, photorealistic, 8K --ar 1:1', '居民楼走廊内景，苍白荧光顶灯照亮两侧灰色防盗门，水磨石地面有淡淡磨损痕迹，尽头小窗外浓雾弥漫，米黄色墙面墙皮微微剥落，绿色应急出口标识发光，清冷寂寥的冬季白日', '/aid/lib/scene/2026/07/09/居民楼楼道·日·内景·冬·雾·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/06/15/居民楼楼道·日·内景·冬·雾·无人.png');
INSERT INTO `aid_comic_asset` VALUES (55, 'reference_scene', '城市马路·日·外景·夏·晴·无人', 'cinematic wide establishing shot of a wide urban asphalt road with white lane markings stretching into the distance, clear blue summer sky with scattered clouds, modern glass skyscrapers lining both sides reflecting sunlight, green-leafed roadside trees, clean sidewalks with street lamps, bright midday sun creating sharp shadows, slight heat-haze effect on the road, photorealistic, 8K --ar 1:1', '宽阔的城市柏油马路向远方延伸，湛蓝夏日天空白云散落，两侧现代玻璃幕墙大厦反射阳光，路边绿树成行，人行道干净整洁，正午烈日投下清晰阴影，路面微微蒸腾热浪', '/aid/lib/scene/2026/07/09/城市马路·日·外景·夏·晴·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/06/15/城市马路·日·外景·夏·晴·无人.png');
INSERT INTO `aid_comic_asset` VALUES (56, 'reference_scene', '城市马路·夜·外景·秋·雨·无人', 'cinematic night street shot of a wet urban road, reflections of neon signs and street lamps glistening on rain-soaked asphalt, yellow taxi light trails stretching across the frame, autumn leaves scattered on wet ground, tall buildings with illuminated windows on both sides, light drizzle creating dreamy bokeh city lights, moody and slightly melancholic atmosphere, photorealistic, 8K --ar 1:1', '深夜湿漉漉的城市道路，霓虹灯与路灯倒影在雨浸的柏油路面上闪烁，黄色车灯拖尾划过画面，秋叶散落湿地，两侧高楼灯光点点，细雨朦胧中城市灯火化为柔焦光斑，忧郁而迷离', '/aid/lib/scene/2026/07/09/城市马路·夜·外景·秋·雨·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/06/15/城市马路·夜·外景·秋·雨·无人.png');
INSERT INTO `aid_comic_asset` VALUES (57, 'reference_scene', '城市公园·日·外景·春·晴·无人', 'cinematic wide shot of a serene urban park pathway bordered by blooming cherry blossom trees in full pink, fresh green grass lawn with scattered white daisies, a wooden bench under a large old tree, small pond in the distance reflecting blue sky and clouds, spring breeze rustling petals onto the path, warm golden afternoon sunlight filtering through leaves, peaceful and hopeful atmosphere, photorealistic, 8K --ar 1:1', '宁静的城市公园小径，两侧樱花树盛放满枝粉色花朵，翠绿草坪上白色雏菊点缀，古老大树下木质长椅，远处小池塘倒映蓝天白云，春风轻拂花瓣飘落小径，温暖金色午后阳光透过枝叶洒下', '/aid/lib/scene/2026/07/09/城市公园·日·外景·春·晴·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/06/15/城市公园·日·外景·春·晴·无人.png');
INSERT INTO `aid_comic_asset` VALUES (58, 'reference_scene', '轿车内·日·内景·夏·晴·无人', 'cinematic POV shot from back seat of a mid-range sedan, view through windshield showing suburban road ahead with blurred trees passing by, summer sunlight streaming through glass creating soft lens flare, black leather seats with detailed stitching, dashboard with glowing digital display, rearview mirror reflecting the road behind, steering wheel in the foreground, photorealistic, 8K --ar 1:1', '中档轿车后座视角，前挡风玻璃外可见郊外公路与模糊掠过的行道树，夏日阳光穿透玻璃形成柔和光晕，黑色皮革座椅缝线细节清晰，仪表盘数字显示屏发光，后视镜映出身后道路，方向盘在前景中', '/aid/lib/scene/2026/07/09/轿车内·日·内景·夏·晴·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/06/15/轿车内·日·内景·夏·晴·无人.png');
INSERT INTO `aid_comic_asset` VALUES (59, 'reference_scene', '轿车内·夜·内景·冬·雪·无人', 'cinematic intimate shot inside a luxury car at night, gentle snowflakes falling and melting on the windshield, soft amber interior ambient lighting, wet snow accumulating on the car hood visible through glass, city street lights casting orange glow through snowy windshield, warm intimate atmosphere contrasting with cold winter outside, photorealistic, 8K --ar 1:1', '深夜豪华车内副驾视角，雪花轻落挡风玻璃缓缓融化，柔和琥珀色氛围灯照亮内饰，湿雪堆积在引擎盖上从玻璃望出，城市街灯在雪夜车窗上投下橙色光晕，车内温暖与外边寒冬形成鲜明对比', '/aid/lib/scene/2026/07/09/轿车内·夜·内景·冬·雪·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/06/16/轿车内·夜·内景·冬·雪·无人.png');
INSERT INTO `aid_comic_asset` VALUES (60, 'reference_scene', '豪华别墅客厅·日·内景·秋·晴·无人', 'cinematic establishing shot of a grand luxury villa living room with soaring double-height ceiling, enormous crystal chandelier cascading down, cream Italian marble flooring with intricate inlay patterns, white Italian leather curved sectional sofa, gold-trimmed classical European furniture, floor-to-ceiling windows overlooking manicured garden with autumn colors, grand piano in the corner, ornate fireplace with gold-framed mirror above, opulent yet tasteful, warm natural daylight flooding the space, photorealistic, 8K --ar 1:1', '挑高豪华别墅客厅，巨型水晶吊灯垂挂，意大利米色大理石地面镶嵌精美花纹，白色真皮弧形组合沙发，欧式古典描金家具，落地窗外可见秋色浓郁的精修花园，角落一架三角钢琴，华丽壁炉上方金色边框大镜', '/aid/lib/scene/2026/07/09/豪华别墅客厅·日·内景·秋·晴·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/06/16/豪华别墅客厅·日·内景·秋·晴·无人.png');
INSERT INTO `aid_comic_asset` VALUES (61, 'reference_scene', '豪华别墅主卧·夜·内景·冬·雨·无人', 'cinematic dramatic shot of a master bedroom in a luxury mansion at night, king-size bed with silk champagne bedding and velvet headboard, elegant nightstands with designer lamps casting warm pools of light, walk-in closet visible through an archway, rain streaming down panoramic windows with blurred city skyline view, dark hardwood floor with plush oversized rug, abstract modern art on walls, luxurious but slightly cold atmosphere, photorealistic, 8K --ar 1:1', '深夜豪宅主卧，特大床铺着香槟色真丝床品与天鹅绒床头，雅致床头柜上设计师台灯投下温暖光圈，拱门内步入式衣帽间隐约可见，冬雨沿全景窗流下，窗外城市天际线模糊，深色硬木地板铺着毛绒地毯', '/aid/lib/scene/2026/07/09/豪华别墅主卧·夜·内景·冬·雨·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/06/16/豪华别墅主卧·夜·内景·冬·雨·无人.png');
INSERT INTO `aid_comic_asset` VALUES (62, 'reference_scene', '豪华别墅泳池·日·外景·夏·晴·无人', 'cinematic aerial shot of a stunning infinity pool at a luxury hillside villa, crystal-clear turquoise water reflecting bright summer sunlight, white marble pool deck with elegant lounge chairs and white umbrellas, panoramic view of the city skyline in the distance, tropical palm trees and manicured hedges framing the scene, gentle ripples on the water surface creating light patterns, golden hour afternoon light, photorealistic, 8K --ar 1:1', '山顶豪宅无边际泳池鸟瞰，清澈碧蓝池水反射夏日骄阳，白色大理石池边排列着优雅躺椅与白伞，远处城市天际线尽收眼底，热带棕榈与修剪整齐的树篱围合空间，金色午后阳光洒满画面', '/aid/lib/scene/2026/07/09/豪华别墅泳池·日·外景·夏·晴·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/06/16/豪华别墅泳池·日·外景·夏·晴·无人.png');
INSERT INTO `aid_comic_asset` VALUES (63, 'reference_scene', '豪车内·夜·内景·秋·雨·无人', 'cinematic close-quarters shot inside an ultra-luxury car at night, rich cream leather seats with diamond quilting, starlight headliner ceiling twinkling above, burl wood trim and polished chrome details, rain softly streaking side window with blurred city neon reflections, ambient interior lighting in warm amber tone, view from rear seat showing partition and driver area, opulent and intimate, photorealistic, 8K --ar 1:1', '深夜超豪华轿车内部，奶白色真皮座椅菱形绗缝工艺，星空顶棚璀璨闪烁，胡桃木饰板与抛光镀铬细节，秋雨轻滑侧窗，窗外城市霓虹化为柔焦色块，氛围灯呈温暖琥珀色调，后排视角可见隔断与驾驶区', '/aid/lib/scene/2026/07/09/豪车内·夜·内景·秋·雨·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/06/16/豪车内·夜·内景·秋·雨·无人.png');
INSERT INTO `aid_comic_asset` VALUES (64, 'reference_scene', '豪门宴会厅·夜·内景·冬·晴·无人', 'cinematic wide master shot of a magnificent mansion ballroom prepared for an elite gala, three-tier crystal chandeliers casting prismatic light across the room, white and gold banquet tables with elaborate floral centerpieces, polished marble floor reflecting lights like a mirror, tall arched windows with heavy velvet burgundy drapes, grand staircase at the far end with ornate gold banister, champagne tower sparkling on a central table, opulent winter evening atmosphere, photorealistic, 8K --ar 1:1', '宏伟宅邸宴会厅为名流晚宴布置妥当，三层水晶吊灯光芒璀璨，白色与金色宴会桌鲜花簇拥，抛光大理石地面如镜面反射灯火，高挑拱窗垂挂酒红色天鹅绒厚帘，尽头金色扶手大楼梯气势恢宏，中央香槟塔晶莹闪烁', '/aid/lib/scene/2026/07/09/豪门宴会厅·夜·内景·冬·晴·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/06/16/豪门宴会厅·夜·内景·冬·晴·无人.png');
INSERT INTO `aid_comic_asset` VALUES (65, 'reference_scene', '开放式办公区·日·内景·春·晴·无人', 'cinematic wide shot of a modern open-plan office interior, rows of sleek white workstations with dual monitors and ergonomic chairs, bright natural daylight from floor-to-ceiling windows showing a spring city skyline, indoor potted plants creating green dividers between desk clusters, glass-walled meeting rooms in the background, modern track lighting in the exposed ceiling, clean minimalist Scandinavian design aesthetic, productive and professional atmosphere, photorealistic, 8K --ar 1:1', '现代开放式办公空间，成排白色工位配备双显示器与人体工学椅，落地窗引入春日自然光映出城市天际线，室内绿植盆栽区隔工作站群，背景中玻璃墙会议室隐约可见，裸露天花板上轨道射灯照明，北欧极简美学', '/aid/lib/scene/2026/07/09/开放式办公区·日·内景·春·晴·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/06/16/开放式办公区·日·内景·春·晴·无人.png');
INSERT INTO `aid_comic_asset` VALUES (66, 'reference_scene', '总裁办公室·日·内景·秋·晴·无人', 'cinematic establishing shot of a corner CEO office on a high floor, expansive floor-to-ceiling windows with panoramic city skyline view, large dark mahogany executive desk with sleek iMac and leather accessories, high-end black leather visitor chairs facing the desk, floor-to-ceiling bookshelf filled with leather-bound books and subtle awards, modern abstract sculpture on a pedestal, warm autumn afternoon light creating long dramatic shadows across marble floor, minimalist but powerful aesthetic conveying authority, photorealistic, 8K --ar 1:1', '高层转角CEO办公室，整面落地窗俯瞰城市全景，深色桃花心木大班台配iMac与皮具文具，对面两把高级黑色皮质访客椅，整面墙书架摆满皮面精装书与低调奖杯，底座上现代抽象雕塑点缀，秋日午后阳光在大理石地面拖出长长阴影', '/aid/lib/scene/2026/07/09/总裁办公室·日·内景·秋·晴·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/06/16/总裁办公室·日·内景·秋·晴·无人.png');
INSERT INTO `aid_comic_asset` VALUES (67, 'reference_scene', '高层会议室·夜·内景·冬·雪·无人', 'cinematic dramatic shot of a premium corporate boardroom at night, long polished ebony conference table with ten high-back leather chairs perfectly aligned, large LED screen on the wall displaying financial charts frozen mid-presentation, snow falling gently beyond the floor-to-ceiling windows showing winter cityscape, modern pendant lights casting cool white glow, glass water carafes and notepads at each seat, tense corporate atmosphere, high contrast shadows, photorealistic, 8K --ar 1:1', '深夜高级企业董事会议室，乌木长会议桌两侧十把高背皮椅整齐排列，墙面大LED屏显示停驻的财务报表，落地窗外冬雪轻落俯瞰城市夜景，现代吊灯投下冷白光线，每席配玻璃水瓶与记事本，高压紧张的商战氛围', '/aid/lib/scene/2026/07/09/高层会议室·夜·内景·冬·雪·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/06/16/高层会议室·夜·内景·冬·雪·无人.png');
INSERT INTO `aid_comic_asset` VALUES (68, 'reference_scene', '公司前台大堂·日·内景·夏·晴·无人', 'cinematic wide establishing shot of a stunning corporate lobby with triple-height ceiling, massive LED wall displaying motion graphics company logo, polished white marble reception desk with sleek minimalist design, modern sculptural seating area with designer armchairs, living green wall spanning three floors, glass elevator shafts with cars moving silently, bright summer sunlight through glass facade creating prismatic light patterns, high-end corporate luxury aesthetic, photorealistic, 8K --ar 1:1', '令人震撼的企业大堂三层挑空，巨型LED动态墙展示公司Logo，流线型白色大理石前台简约极致，现代雕塑感休息区配置设计师款单人沙发，整面三层绿植墙生机盎然，玻璃电梯井中轿厢无声运行，夏日阳光穿过玻璃幕墙形成棱镜光斑', '/aid/lib/scene/2026/07/09/公司前台大堂·日·内景·夏·晴·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/06/16/公司前台大堂·日·内景·夏·晴·无人.png');
INSERT INTO `aid_comic_asset` VALUES (69, 'reference_scene', '消防楼梯间·夜·内景·秋·雾·无人', 'cinematic thriller-style shot of a concrete stairwell in a modern office building at night, industrial grey concrete walls and metal stairs with anti-slip treads, harsh fluorescent emergency lighting creating stark shadows, small window on each landing showing foggy city night outside, metal handrails worn smooth from use, eerie and tense empty atmosphere, security camera in corner with blinking red light, photorealistic, 8K --ar 1:1', '深夜写字楼混凝土消防楼梯间，工业灰墙面与防滑金属楼梯，刺眼荧光应急灯投下锐利阴影，每层转角小窗外秋雾笼罩城市夜色，金属扶手经年使用磨得光滑，空荡回响的紧张氛围，角落监控摄像头红灯闪烁', '/aid/lib/scene/2026/07/09/消防楼梯间·夜·内景·秋·雾·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/06/16/消防楼梯间·夜·内景·秋·雾·无人.png');
INSERT INTO `aid_comic_asset` VALUES (70, 'reference_scene', '街边大排档·夜·外景·夏·晴·无人', 'cinematic street-level shot of a Chinese outdoor food stall at night, red plastic tables and stools neatly arranged under a portable canopy, steaming wok visible in the open kitchen with flames leaping up, strings of warm yellow fairy lights draped overhead, beer crates stacked against the wall, menu board with handwritten Chinese chalk characters, smoke rising gently into warm summer night air, nostalgic and down-to-earth atmosphere, photorealistic, 8K --ar 1:1', '深夜中国街边大排档，红色塑料桌椅在可移动雨棚下整齐排列，开放式厨房铁锅火焰腾跃热气蒸腾，暖黄串灯在头顶交织，墙边堆着啤酒箱，粉笔手写菜单黑板挂在一旁，烟气飘入温暖夏夜空气中', '/aid/lib/scene/2026/07/09/街边大排档·夜·外景·夏·晴·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/06/16/街边大排档·夜·外景·夏·晴·无人.png');
INSERT INTO `aid_comic_asset` VALUES (71, 'reference_scene', '老城区菜市场·日·外景·春·晴·无人', 'cinematic documentary-style shot of a traditional Chinese wet market in an old city district, rows of wooden stalls with red and blue striped awnings, fresh vegetables and fruits artistically arranged in woven baskets, hanging red lanterns above the butchers\' stall, narrow alleyway between stalls with worn cobblestone floor, warm spring morning sunlight filtering through gaps in the awning creating dappled light, vibrant and full of life, photorealistic, 8K --ar 1:1', '中国老城传统菜市场，红蓝条纹遮阳篷下一排排水质摊位整齐排列，编织竹篮中蔬果摆放讲究，肉铺上方红灯笼高挂，摊位间小巷卵石路面被岁月磨光，春日晨光透过篷布缝隙洒下斑驳光影', '/aid/lib/scene/2026/07/09/老城区菜市场·日·外景·春·晴·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/06/16/老城区菜市场·日·外景·春·晴·无人.png');
INSERT INTO `aid_comic_asset` VALUES (72, 'reference_scene', '城中村小巷·夜·外景·夏·雨·无人', 'cinematic urban realism shot of a narrow alley in a Chinese urban village at night, tangled overhead electrical wires silhouetted against dark sky, old apartment buildings with clothes drying on balcony poles, single warm yellow street lamp casting pool of light on wet concrete ground, puddles reflecting the lamp light, faded red brick walls with peeling posters and graffiti, light summer rain creating humid atmosphere, lonely stray cat silhouette, gritty yet cinematic, photorealistic, 8K --ar 1:1', '深夜中国城中村狭小巷道，杂乱电线在夜空剪影般交错，老旧居民楼阳台上晾晒衣物垂挂，一盏暖黄路灯在湿漉漉水泥地面投下光池，水洼倒映灯影，红砖墙贴满剥落海报与涂鸦，夏日细雨营造潮湿氛围，一只流浪猫剪影在垃圾桶旁', '/aid/lib/scene/2026/07/09/城中村小巷·夜·外景·夏·雨·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/06/16/城中村小巷·夜·外景·夏·雨·无人.png');
INSERT INTO `aid_comic_asset` VALUES (73, 'reference_scene', '地铁车厢内·日·内景·冬·晴·无人', 'cinematic interior shot of a modern Chinese subway train car, rows of empty stainless steel seats along both sides, handrails and hanging straps gently swaying, bright LED lighting panels in the ceiling, route map display screen showing stations in Chinese and English, large windows showing dark tunnel walls rushing by, clean and orderly atmosphere, slight motion blur on window views suggesting speed, photorealistic, 8K --ar 1:1', '现代中国地铁车厢内部，两侧不锈钢长椅空空荡荡，扶手与吊环轻轻晃动，天花板LED灯光明亮均匀，路线图显示屏中英文站名清晰可见，大窗外是飞速后退的黑暗隧道壁偶尔闪过灯光，轻微运动模糊暗示车速', '/aid/lib/scene/2026/07/09/地铁车厢内·日·内景·冬·晴·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/06/16/地铁车厢内·日·内景·冬·晴·无人.png');
INSERT INTO `aid_comic_asset` VALUES (74, 'reference_scene', '老旧居民楼天台·夜·外景·秋·雾·无人', 'cinematic atmospheric shot of a rooftop of an old residential building at night, weathered concrete surface with cracks and water stains, rusted metal railings along the edge, clotheslines with forgotten laundry hanging, mismatched satellite dishes pointing at different angles, panoramic view of a foggy cityscape with scattered apartment lights glowing through mist, a single old wooden chair left on the rooftop, lonely and contemplative autumn night atmosphere, photorealistic, 8K --ar 1:1', '深夜老旧居民楼天台，风化混凝土表面布满裂纹水渍，边缘锈迹斑斑的金属栏杆，晾衣绳上挂着遗忘的衣物，各式卫星天线朝向各异，秋雾中的城市全景灯火点点穿透雾气，天台角落孤零零一把旧木椅', '/aid/lib/scene/2026/07/09/老旧居民楼天台·夜·外景·秋·雾·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/06/16/老旧居民楼天台·夜·外景·秋·雾·无人.png');
INSERT INTO `aid_comic_asset` VALUES (75, 'reference_scene', '文艺咖啡厅·日·内景·秋·晴·无人', 'cinematic warm-tone shot of a charming artisanal coffee shop interior, warm afternoon sunlight through large windows with wooden frames, rustic exposed brick accent wall with hanging potted plants, mismatched vintage wooden tables and chairs, espresso machine gleaming on a marble counter, blackboard menu with artistic chalk lettering, bookshelf with novels and board games, soft golden hour light creating cozy atmosphere, photorealistic, 8K --ar 1:1', '迷人手工咖啡店内景，午后暖阳穿过木质窗框洒入，一面裸露砖墙搭配悬挂绿植，复古实木桌椅不成套错落有致，大理石吧台上意式咖啡机锃亮，黑板菜单粉笔字母充满艺术感，书架摆满小说与桌游，金色时光的温暖氛围', '/aid/lib/scene/2026/07/09/文艺咖啡厅·日·内景·秋·晴·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/06/16/文艺咖啡厅·日·内景·秋·晴·无人.png');
INSERT INTO `aid_comic_asset` VALUES (76, 'reference_scene', '高级西餐厅·夜·内景·冬·雪·无人', 'cinematic intimate shot of an upscale fine-dining restaurant interior at night, tables draped in pristine white linen with single rose in crystal vase, candlelight flickering on each table creating intimate ambiance, snow visible through tall arched windows, dark wood paneling and burgundy velvet banquette seating, wine cellar visible through glass wall, chandelier with warm dim lighting, romantic winter evening setting, photorealistic, 8K --ar 1:1', '高端Fine-dining西餐厅内景，每张桌铺洁白亚麻桌布水晶花瓶中单枝玫瑰，烛光摇曳营造私密氛围，高挑拱窗外可见冬雪飘落，深色实木墙裙配酒红色天鹅绒卡座，玻璃酒窖隐约可见，水晶吊灯投下温暖柔光', '/aid/lib/scene/2026/07/09/高级西餐厅·夜·内景·冬·雪·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/06/16/高级西餐厅·夜·内景·冬·雪·无人.png');
INSERT INTO `aid_comic_asset` VALUES (77, 'reference_scene', '电影院影厅内·夜·内景·夏·晴·无人', 'cinematic POV shot from middle row of an empty modern cinema auditorium, rows of plush red velvet seats descending toward large silver screen, the screen glowing with pre-show ambient blue light illuminating front rows, aisle lights casting subtle warm glow on carpeted steps, art deco wall sconces adding vintage charm, sound-absorbing textured wall panels, intimate and anticipatory atmosphere, photorealistic, 8K --ar 1:1', '空旷的现代影院放映厅内景，成排酒红色天鹅绒座椅向银幕倾斜，银幕散发映前环境蓝光照明前几排座椅，过道灯在铺毯台阶上投下柔和暖光，艺术装饰壁灯增添复古韵味，吸音纹理墙板，充满期待感的私密空间', '/aid/lib/scene/2026/07/09/电影院影厅内·夜·内景·夏·晴·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/06/16/电影院影厅内·夜·内景·夏·晴·无人.png');
INSERT INTO `aid_comic_asset` VALUES (78, 'reference_scene', '大型商场中庭·日·内景·夏·晴·无人', 'cinematic establishing shot from upper floor of a grand modern shopping mall atrium, soaring glass ceiling allowing bright summer sunlight to flood the space, multiple levels of white balconies with glass railings, massive suspended kinetic art sculpture in the center, escalators crisscrossing between floors, luxury brand storefronts with illuminated logos, polished white marble floors reflecting natural light, indoor palm trees and modern seating pods, upscale commercial atmosphere, photorealistic, 8K --ar 1:1', '宏伟现代购物中心中庭高层俯拍，玻璃穹顶让夏日阳光倾泻而下，多层白色阳台配玻璃栏杆层层环绕，巨型动态艺术装置悬挂正中，自动扶梯在各层交叉穿梭，奢侈品牌店面Logo发光，白色大理石地面如镜般反射自然光', '/aid/lib/scene/2026/07/09/大型商场中庭·日·内景·夏·晴·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/06/16/大型商场中庭·日·内景·夏·晴·无人.png');
INSERT INTO `aid_comic_asset` VALUES (79, 'reference_scene', '城市天台酒吧·夜·外景·夏·晴·无人', 'cinematic wide shot of a chic rooftop cocktail bar at night, panoramic view of glittering city skyline with skyscraper lights reflecting on a river below, stylish lounge seating with fire pit tables casting warm orange glow, string lights overhead creating magical canopy, sleek bar counter with illuminated glass shelves of bottles, warm summer night breeze suggested by gently swaying plants, infinity edge giving floating sensation, sophisticated and romantic, photorealistic, 8K --ar 1:1', '时尚屋顶露天酒吧夜景，璀璨城市天际线全景，摩天大楼灯光倒映下方河流，时尚躺椅配燃气火炉桌散发暖橙色光，头顶串灯交织如梦似幻，流线型吧台后酒瓶玻璃架被照亮，夏日暖风微拂', '/aid/lib/scene/2026/07/09/城市天台酒吧·夜·外景·夏·晴·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/06/16/城市天台酒吧·夜·外景·夏·晴·无人.png');
INSERT INTO `aid_comic_asset` VALUES (80, 'reference_scene', '金銮殿·日·内景·秋·晴·无人', 'cinematic wide establishing shot of the grand imperial throne hall of an ancient Chinese palace, massive gold-plated dragon throne on a raised platform with nine steps, towering red lacquered columns with intricate golden dragon carvings coiled around them, sunlight streaming through high latticed windows creating beams of light in incense-scented air, gleaming golden floor tiles reflecting the light, imperial yellow silk banners hanging from high ceiling with dragon motifs, solemn and majestic autumn atmosphere, ancient Chinese palatial photorealistic style, 8K --ar 1:1', '中国古代皇宫正殿气势恢宏，九级台阶上巨型鎏金龙椅居中高置，红色巨柱高耸盘绕金色龙纹浮雕，高窗格栅透入的日光在香火氤氲中化为光束，金色地砖如镜反光，明黄绸缎龙纹巨幅从高耸天花垂落', '/aid/lib/scene/2026/07/09/金銮殿·日·内景·秋·晴·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/06/16/金銮殿·日·内景·秋·晴·无人.png');
INSERT INTO `aid_comic_asset` VALUES (81, 'reference_scene', '御花园·日·外景·春·晴·无人', 'cinematic panorama of imperial palace garden in spring, winding paths of white pebbles through blooming peach and plum trees with pink and white petals drifting in breeze, an ornate pavilion with upturned eaves and blue-glazed roof tiles beside a koi pond, stone bridges arching over water reflecting blue sky, carefully manicured bonsai and rock formations, butterflies among flowers, soft golden spring sunlight creating dreamlike atmosphere, peaceful and elegant, ancient Chinese garden photorealistic, 8K --ar 1:1', '皇宫御花园春日盛景，白色鹅卵石蜿蜒小径穿过盛开桃花李花林，粉白花瓣随风飘落，飞檐蓝琉璃瓦凉亭伫立锦鲤池畔，石拱桥跨越水面倒映蓝天，盆景与假山精心布置，蝴蝶飞舞花间', '/aid/lib/scene/2026/07/09/御花园·日·外景·春·晴·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/06/16/御花园·日·外景·春·晴·无人.png');
INSERT INTO `aid_comic_asset` VALUES (82, 'reference_scene', '后宫庭院·夜·外景·秋·雾·无人', 'cinematic atmospheric night scene of an imperial harem courtyard, rows of red palace lanterns casting warm red glow through autumn fog, cobblestone courtyard with fallen golden ginkgo leaves scattered, elegant palace architecture with carved wooden lattice windows showing faint candlelight within, stone lanterns along pathway emitting soft light, a swing hanging from an old locust tree in the corner, misty and melancholic atmosphere, full moon partially visible through fog, ancient Chinese palace photorealistic, 8K --ar 1:1', '深夜后宫庭院，成排红色宫灯在秋雾中投下暖红光影，卵石地面散落金黄银杏落叶，精雕木格窗中透出微弱烛光，石灯笼沿路散发柔和光芒，庭院角落老槐树下秋千静悬，满月半掩于雾中', '/aid/lib/scene/2026/07/09/后宫庭院·夜·外景·秋·雾·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/06/16/后宫庭院·夜·外景·秋·雾·无人.png');
INSERT INTO `aid_comic_asset` VALUES (83, 'reference_scene', '御书房·夜·内景·冬·雪·无人', 'cinematic intimate shot of the emperor\'s private study at night, walls lined with ancient scrolls and books in dark rosewood shelves, large zitan wood desk with inkstone brush holder and half-unrolled memorial scroll, bronze incense burner releasing thin smoke tendrils, single dragon-patterned palace lantern providing warm focused light, snow visible through paper-latticed window accumulating on sill, thick silk carpets on the floor, solemn and scholarly atmosphere with imperial authority, ancient Chinese interior photorealistic, 8K --ar 1:1', '深夜皇帝御书房，深色紫檀书架满墙陈列古籍卷轴，大紫檀书案上摆着砚台笔架和半展的奏折，铜香炉青烟袅袅，一盏龙纹宫灯投下集中暖光，纸格窗外可见积雪覆窗棂，地面铺着厚丝毯', '/aid/lib/scene/2026/07/09/御书房·夜·内景·冬·雪·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/06/16/御书房·夜·内景·冬·雪·无人.png');
INSERT INTO `aid_comic_asset` VALUES (84, 'reference_scene', '王府正厅·日·内景·秋·晴·无人', 'cinematic wide shot of the main hall of a prince\'s mansion, dark nanmu wood furniture with intricate mother-of-pearl inlay, large tiger skin rug on polished stone floor, calligraphy scrolls and landscape paintings mounted on walls, antique porcelain vases on carved display stands, warm autumn sunlight filtering through lattice windows casting geometric shadows, tea set arranged on a side table, wealthy and refined ancient noble atmosphere, dignified but less formal than imperial palace, ancient Chinese interior photorealistic, 8K --ar 1:1', '王府正厅内景，暗色楠木家具镶嵌精美螺钿，虎皮大毯铺于光洁石地，墙面悬挂名家书法与山水立轴，古董瓷瓶陈列于雕花展架，秋日暖阳透过格窗投下几何光影，茶具摆放在侧几上', '/aid/lib/scene/2026/07/09/王府正厅·日·内景·秋·晴·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/06/16/王府正厅·日·内景·秋·晴·无人.png');
INSERT INTO `aid_comic_asset` VALUES (85, 'reference_scene', '王府后花园·夜·外景·夏·雾·无人', 'cinematic atmospheric garden shot of the rear garden of a prince\'s mansion at night, serene lotus pond reflecting full summer moon, fireflies glowing and drifting among weeping willows and bamboo groves, stone pathways winding through rock gardens, small pavilion with silk curtains slightly billowing in warm breeze, ancient pine trees silhouetted against moonlit sky, ground mist hovering over water creating ethereal atmosphere, elegant and mysterious, ancient Chinese garden photorealistic, 8K --ar 1:1', '深夜王府后花园，宁静荷塘倒映盛夏满月，萤火虫在垂柳与竹林间飞舞发光，石径蜿蜒穿过假山石园，凉亭纱帘在暖风中微拂，古松剪影映衬月色，水面薄雾营造空灵意境', '/aid/lib/scene/2026/07/09/王府后花园·夜·外景·夏·雾·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/06/16/王府后花园·夜·外景·夏·雾·无人.png');
INSERT INTO `aid_comic_asset` VALUES (86, 'reference_scene', '王府书房·夜·内景·冬·雪·无人', 'cinematic warm interior shot of a prince\'s private study at night, tall rosewood bookshelves filled with ancient texts and scrolls, large writing desk with fine brush set and unfinished mountain landscape painting, bronze charcoal brazier providing warmth and soft orange light, snow building up on window lattice outside visible through paper panes, ceremonial sword displayed on weapon rack on the wall, thick brocade cushions on carved chairs, scholarly and refined atmosphere with subtle military undertones, ancient Chinese study photorealistic, 8K --ar 1:1', '深夜王爷书房，紫檀书架高耸满载古籍卷轴，大书案上文房四宝齐备未竟山水画铺展，铜炭火盆散发温暖橙色柔光，纸窗外积雪渐厚覆满窗棂，墙上兵器架陈列宝剑，儒雅中暗含将门之气', '/aid/lib/scene/2026/07/09/王府书房·夜·内景·冬·雪·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/06/16/王府书房·夜·内景·冬·雪·无人.png');
INSERT INTO `aid_comic_asset` VALUES (87, 'reference_scene', '古镇街道·日·外景·春·晴·无人', 'cinematic tracking shot of an ancient Chinese town street in spring, centuries-old cobblestone road winding between traditional wooden buildings with grey-tiled roofs and upturned eaves, red silk lanterns hanging from every shopfront gently swaying, wooden signboards with golden calligraphy, cherry blossom petals drifting through air and settling on stone path, small stone bridge arching over clear canal in distance, warm spring sunlight creating dappled patterns, lively and picturesque wuxia atmosphere, ancient Chinese town photorealistic, 8K --ar 1:1', '春日中国古镇街道，数百年卵石路蜿蜒于传统木构建筑之间，灰瓦飞檐连绵，红绸灯笼自每家铺面垂下轻摆，木质招牌金色书法赫然，樱花花瓣飘落石径，远处小石桥拱跨清澈水渠，暖春阳光投下斑驳光影', '/aid/lib/scene/2026/07/09/古镇街道·日·外景·春·晴·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/06/16/古镇街道·日·外景·春·晴·无人.png');
INSERT INTO `aid_comic_asset` VALUES (88, 'reference_scene', '竹林深处·日·外景·秋·雾·无人', 'cinematic low-angle wide shot deep within a vast bamboo forest, towering green bamboo stalks stretching endlessly upward with golden autumn light filtering through canopy, narrow dirt path winding into misty depths, fallen bamboo leaves covering ground in warm brown tones, ground fog swirling around base of bamboo creating otherworldly atmosphere, sunlight creating dramatic beams through mist and leaves, utterly peaceful and meditative, iconic wuxia landscape, photorealistic, 8K --ar 1:1', '莽莽竹林深处仰拍广角，翠绿竹竿冲天而起望不到顶，秋日金光透过密叶洒落，窄土路蜿蜒没入迷雾深处，落叶覆地呈温暖棕色，地面雾气在竹根间缭绕如仙境，阳光穿过雾与叶形成戏剧性光束', '/aid/lib/scene/2026/07/09/竹林深处·日·外景·秋·雾·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/06/16/竹林深处·日·外景·秋·雾·无人.png');
INSERT INTO `aid_comic_asset` VALUES (89, 'reference_scene', '江湖客栈大堂·夜·内景·冬·雪·无人', 'cinematic wide interior shot of the main hall of an ancient Chinese inn at night, wooden tables and benches arranged across ground floor with grand staircase leading to upper rooms, warm lantern light from paper lamps hanging from dark wood beams, large wine jar display behind the counter, snow visible through open doorway with heavy cotton curtain partially drawn, cooking smoke drifting from kitchen area, swords and travel packs leaning against walls suggesting travelers, warm and rustic wuxia atmosphere, ancient Chinese inn photorealistic, 8K --ar 1:1', '深夜古代客栈大堂，木桌条凳遍布一楼大厅，宏大楼梯通向楼上客房，纸灯笼自黑木横梁垂下散发暖光，柜台后巨坛美酒高高陈列，敞开的门口厚棉帘半掀，门外可见落雪，厨房方向飘来炊烟', '/aid/lib/scene/2026/07/09/江湖客栈大堂·夜·内景·冬·雪·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/06/16/江湖客栈大堂·夜·内景·冬·雪·无人.png');
INSERT INTO `aid_comic_asset` VALUES (90, 'reference_scene', '悬崖绝壁·日·外景·秋·雾·无人', 'cinematic extreme wide shot of a dramatic cliff edge in the mountains, lone ancient pine tree growing horizontally from cliff face, swirling mist in vast valley below creating sea of clouds, distant mountain peaks piercing through fog like islands, weathered stone platform at cliff edge with ancient sword marks, golden autumn light from setting sun casting long shadows and painting clouds orange and pink, epic and awe-inspiring wuxia landscape, photorealistic ancient Chinese landscape, 8K --ar 1:1', '群山之巅绝壁极广角画面，一棵孤松自崖壁横向生长，谷底云雾翻涌如海，远山峰顶刺破雾海如孤岛，崖边风化石台残留远古剑痕，秋日夕阳金光拉长阴影将云海染成橙粉', '/aid/lib/scene/2026/07/09/悬崖绝壁·日·外景·秋·雾·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/06/16/悬崖绝壁·日·外景·秋·雾·无人.png');
INSERT INTO `aid_comic_asset` VALUES (91, 'reference_scene', '古代集市·日·外景·春·晴·无人', 'cinematic wide street shot of a vibrant ancient Chinese market, vendors\' stalls with colorful silk canopies lining both sides of dirt road, baskets overflowing with exotic fruits, spices in woven sacks, bolts of colorful silk fabric draped over wooden racks, street food stalls with steam rising from bamboo steamers, terracotta roof tiles on surrounding buildings, temple roof visible in distance, warm spring morning light creating lively atmosphere, rich daily life in ancient China, photorealistic, 8K --ar 1:1', '热闹的中国古代集市街景，各色丝绸华盖摊位沿土路两侧排开，柳条篮中异域水果满溢，麻袋装香料成堆，木架上各色丝绸布匹垂挂，竹蒸笼蒸汽升腾的小吃摊，四周建筑陶瓦屋顶，远方庙宇屋顶隐约可见', '/aid/lib/scene/2026/07/09/古代集市·日·外景·春·晴·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/06/16/古代集市·日·外景·春·晴·无人.png');
INSERT INTO `aid_comic_asset` VALUES (92, 'reference_scene', '古风茶馆·日·内景·秋·雨·无人', 'cinematic intimate interior shot of an elegant traditional Chinese tea house, dark rosewood tables and stools arranged across polished floor, tea master\'s station with full gongfu tea set and copper kettle steaming gently, antique scrolls of calligraphy on walls, bamboo blinds partially lowered over open windows showing autumn rain falling on small courtyard garden, soft daylight filtering through paper lanterns, warm and tranquil atmosphere, ancient Chinese tea house photorealistic, 8K --ar 1:1', '雅致中国传统茶馆内景，深色红木桌椅在光洁地面错落分布，茶艺台上一套功夫茶具配铜壶蒸汽袅袅，墙面悬挂古书法卷轴，竹帘半垂，敞开的窗外可见秋雨洒落小天井花园，纸灯笼滤出柔和日光', '/aid/lib/scene/2026/07/09/古风茶馆·日·内景·秋·雨·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/06/16/古风茶馆·日·内景·秋·雨·无人.png');
INSERT INTO `aid_comic_asset` VALUES (93, 'reference_scene', '运河码头·夜·外景·夏·雾·无人', 'cinematic waterfront shot of an ancient canal dock at night, wooden fishing boats and cargo junks moored along stone embankment with lanterns reflecting in dark water, wooden planks of pier worn smooth by years of use, fog rolling in from water creating mysterious atmosphere, silhouette of three-arch stone bridge in background, wooden warehouses and taverns along waterfront with warm light glowing through windows, humid summer night, atmospheric ancient Chinese noir setting, photorealistic, 8K --ar 1:1', '深夜古运河码头，木渔船与货船沿石堤停泊，船上灯笼倒映幽暗水面，码头木板经年踩踏已磨得光滑，水面雾气弥漫营造神秘氛围，远方三孔石桥剪影朦胧，岸边木造仓库酒馆窗中透出暖光', '/aid/lib/scene/2026/07/09/运河码头·夜·外景·夏·雾·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/06/16/运河码头·夜·外景·夏·雾·无人.png');
INSERT INTO `aid_comic_asset` VALUES (94, 'reference_scene', '仙山云海·日·外景·春·雾·无人', 'cinematic aerial establishing shot of a breathtaking immortal realm mountain peak rising above sea of clouds at sunrise, ancient Taoist temple complex with flying eaves and golden-glazed roof tiles clinging to mountainside, stone steps carved into cliff leading upward through swirling mist, ancient cypress trees with twisting branches, waterfall cascading from higher peak disappearing into cloud sea below, cranes flying in distance, golden and pink dawn light illuminating scene with divine radiance, epic transcendent xianxia atmosphere, Chinese mythology photorealistic style, 8K --ar 1:1', '日出时分仙境山峰破云而出，古道教宫观飞檐金琉璃瓦依附山腰而立，石阶凿入悬崖盘旋向上没入雾中，古柏虬枝苍劲，高处瀑布飞泻坠入云海之下，远方仙鹤翱翔，金粉晨曦照耀万物如同神迹', '/aid/lib/scene/2026/07/09/仙山云海·日·外景·春·雾·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/06/16/仙山云海·日·外景·春·雾·无人.png');
INSERT INTO `aid_comic_asset` VALUES (95, 'reference_scene', '仙门大殿·日·内景·秋·晴·无人', 'cinematic wide interior shot of the grand hall of an immortal sect, towering white jade pillars carved with dragon and phoenix motifs reaching to ceiling painted with constellations, floating crystal throne on central dais radiating soft blue light, spiritual energy visible as floating particles of light throughout the hall, ancient formation patterns glowing faintly on polished white jade floor, incense burners emitting ethereal smoke that forms mystical shapes, open walls revealing mountain peaks and cloud sea beyond, divine and otherworldly autumn atmosphere, photorealistic xianxia style, 8K --ar 1:1', '仙门宗派大殿内景，高耸白玉巨柱雕龙刻凤直达绘满星图的天花板，中央高台水晶王座悬浮散发淡蓝柔光，灵气化为光点漂浮满殿，古阵法纹样在白玉地面上微微发光，香炉飘出袅袅仙烟幻化妙形，开放墙壁外可见仙山云海', '/aid/lib/scene/2026/07/09/仙门大殿·日·内景·秋·晴·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/06/16/仙门大殿·日·内景·秋·晴·无人.png');
INSERT INTO `aid_comic_asset` VALUES (96, 'reference_scene', '魔域暗殿·夜·内景·冬·雪·无人', 'cinematic dramatic shot of a dark throne hall in the demon realm, obsidian pillars carved with writhing demon faces glowing with faint crimson light, massive throne made of black iron and bone on volcanic rock platform, dark purple and red spiritual energy swirling in the air, eerie bioluminescent crystals embedded in walls providing only light, chains hanging from impossibly high ceiling disappearing into darkness, frost forming on stone floor despite hellish aura, oppressive and malevolent winter atmosphere, dark fantasy xianxia style, photorealistic, 8K --ar 1:1', '魔域黑暗王座大殿，黑曜石柱上恶魔面孔浮雕散发微弱猩红光芒，黑铁与骨骸铸就的王座矗立在火山岩台基上，紫黑色灵气在空中翻涌，墙内嵌生物荧光水晶是唯一光源，铁链自不可见之顶垂下没入黑暗，冰霜覆于石地', '/aid/lib/scene/2026/07/09/魔域暗殿·夜·内景·冬·雪·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/06/16/魔域暗殿·夜·内景·冬·雪·无人.png');
INSERT INTO `aid_comic_asset` VALUES (97, 'reference_character', '霸道总裁·男·28-35岁', 'cinematic portrait of a handsome young Chinese CEO, 30 years old, sharp angular jawline, intense deep-set eyes with piercing gaze, well-groomed slicked-back black hair, tall athletic build, wearing a perfectly tailored dark charcoal three-piece suit with white dress shirt slightly unbuttoned at collar, Patek Philippe watch on wrist, standing in front of floor-to-ceiling windows overlooking city skyline, confident powerful posture, slight frown, cold and domineering aura, photorealistic, 8K --ar 1:1', '冷峻凌厉的年轻商界精英，五官深邃棱角分明，剑眉星目，身高185+宽肩窄腰，定制深色西装三件套，白衬衫解开第一颗扣，腕间百达翡丽，短发利落后梳，气场强大微蹙眉头眼神锐利', '/aid/lib/character/2026/07/09/霸道总裁·男·28-35岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/06/16/霸道总裁·男·28-35岁.png');
