INSERT INTO `aid_comic_asset` VALUES (99, 'reference_character', '豪门千金·恶毒女配·女·25-30岁', 'cinematic portrait of a stunning wealthy Chinese socialite, 28 years old, sharp v-shaped face with flawless makeup and dramatic winged eyeliner, seductive foxy eyes, long wavy chestnut brown hair cascading down, curvaceous figure, wearing an elegant figure-hugging red evening gown with a thigh slit, sparkling diamond necklace and drop earrings, designer clutch in hand, glossy red lips curved in a haughty smirk, cold condescending gaze, photorealistic, 8K --ar 1:1', '精致美艳的富家千金，瓜子脸妆容精致，眼线上挑媚眼如丝，波浪大卷长发栗棕色，身材凹凸有致，身穿红色或黑色修身晚礼服，钻石项链与耳坠闪耀，手拿名牌手包，红唇微勾神情高傲带刺', '/aid/lib/character/2026/07/09/豪门千金·恶毒女配·女·25-30岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/06/16/豪门千金·恶毒女配·女·25-30岁.png');
INSERT INTO `aid_comic_asset` VALUES (100, 'reference_character', '温柔男二·医生·男·26-32岁', 'cinematic portrait of a gentle warm-hearted Chinese man, 29 years old, soft handsome features with kind smiling eyes, slightly wavy medium-length brown hair, slender build, wearing a cream-colored cashmere sweater over a light blue collared shirt, delicate thin-rimmed glasses, warm friendly smile, clean well-groomed appearance, standing by a sunlit window in a cozy coffee shop, gentle healing aura, photorealistic, 8K --ar 1:1', '温润如玉的暖男，五官清秀柔和，眼神温暖含笑，蓬松中短发微卷，身高178-183身材修长不壮硕，米色针织衫或浅蓝衬衫配卡其裤，戴细框眼镜，手指修长干净，周身散发着治愈系温暖气质', '/aid/lib/character/2026/07/09/温柔男二·医生·男·26-32岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/06/16/温柔男二·医生·男·26-32岁.png');
INSERT INTO `aid_comic_asset` VALUES (101, 'reference_character', '冷酷保镖·男·28-38岁', 'cinematic portrait of a stoic Chinese bodyguard, 33 years old, chiseled square jaw with hard angular features, piercing hawk-like vigilant eyes, buzz cut military hairstyle, tall muscular build towering at 190cm, wearing a fitted black tactical suit with black turtleneck underneath, concealed earpiece visible, scarred knuckles from training, stern expressionless face, intimidating protective presence, standing alert in a dim corridor, photorealistic, 8K --ar 1:1', '冷硬专业的高级保镖，国字脸线条硬朗如刀削，眼神如鹰隼般锐利警觉，极短寸头，身高188+肌肉结实但不夸张，黑色修身战术西装内搭黑色高领，佩戴隐形耳麦，手上有训练老茧，面无表情气势逼人', '/aid/lib/character/2026/07/09/冷酷保镖·男·28-38岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/06/16/冷酷保镖·男·28-38岁.png');
INSERT INTO `aid_comic_asset` VALUES (102, 'reference_character', '职场OL·秘书·女·24-28岁', 'cinematic portrait of a professional Chinese office lady, 26 years old, neat pleasant features with light professional makeup, medium-length dark hair tied in a low sleek ponytail, well-proportioned figure, wearing a tailored navy blue business suit with pencil skirt and crisp white blouse, simple elegant wristwatch, holding a tablet and documents, black modest heels, focused competent expression, standing in a bright modern office, photorealistic, 8K --ar 1:1', '干练职业的办公室女性，五官端正大方淡妆得体，中长发扎低马尾或盘起，身材匀称，深色修身西装套裙配白衬衫，黑色中跟皮鞋，腕间简约手表，手拿文件夹或平板，专注认真的职业表情', '/aid/lib/character/2026/07/09/职场OL·秘书·女·24-28岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/06/16/职场OL·秘书·女·24-28岁.png');
INSERT INTO `aid_comic_asset` VALUES (103, 'reference_character', '实习小白·职场新人·女·21-24岁', 'cinematic portrait of a fresh young Chinese intern, 22 years old, round youthful face with soft baby fat, large curious nervous eyes, black hair with neat bangs tied in a ponytail, petite small frame, wearing a slightly oversized new navy business suit that still looks a bit stiff, large commuter tote bag on shoulder, clutching a thick stack of files, eager but slightly flustered expression, standing in a modern office lobby, photorealistic, 8K --ar 1:1', '青涩稚嫩的应届毕业生，圆脸带婴儿肥眼睛大而好奇又有些紧张，黑发齐刘海扎马尾，身材娇小，穿着略不合身的新买职业装，背着大号通勤包，手里抱着厚厚的文件夹，努力认真但略带慌张', '/aid/lib/character/2026/07/09/实习小白·职场新人·女·21-24岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/06/16/实习小白·职场新人·女·21-24岁.png');
INSERT INTO `aid_comic_asset` VALUES (104, 'reference_character', '精英女强人·总监·女·30-38岁', 'cinematic portrait of a powerful Chinese executive woman, 34 years old, striking defined features with sharp sophisticated makeup, eyes radiating authority and decisiveness, sleek chin-length bob hairstyle, tall statuesque figure, wearing an expensive tailored white power suit with a silk champagne blouse underneath, Jaeger-LeCoultre watch, stiletto heels, one hand casually in pocket, commanding confident posture, standing in a high-rise corner office, photorealistic, 8K --ar 1:1', '气场强大的职场女王，轮廓分明妆容精致凌厉，眼中透着杀伐决断，短发干练或波浪盘发，身材高挑气场一米八，高级定制白色或灰色西装套装配真丝衬衫，细高跟鞋腕间积家手表，单手插兜姿态自信', '/aid/lib/character/2026/07/09/精英女强人·总监·女·30-38岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/06/16/精英女强人·总监·女·30-38岁.png');
INSERT INTO `aid_comic_asset` VALUES (105, 'reference_character', '中年老板·董事长·男·45-55岁', 'cinematic portrait of a distinguished middle-aged Chinese business magnate, 50 years old, weathered distinguished face with fine lines around wise penetrating eyes, salt-and-pepper hair neatly combed at the temples, well-maintained build with slight middle-age bulk, wearing an elegant tailored dark navy mandarin-collar suit, holding a fine porcelain teacup, calm authoritative presence, sitting in a luxurious leather armchair in a wood-paneled office, photorealistic, 8K --ar 1:1', '沉稳威严的中年企业家，眼角已有细纹但不减锐利，眼神洞悉世事，头发微灰两鬓染霜，身材保持良好微有肚腩，定制深灰或藏蓝中山装立领西装，手持雪茄或茶杯，气场沉稳如山', '/aid/lib/character/2026/07/09/中年老板·董事长·男·45-55岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/06/16/中年老板·董事长·男·45-55岁.png');
INSERT INTO `aid_comic_asset` VALUES (106, 'reference_character', '知性闺蜜·律师·女·26-32岁', 'cinematic portrait of an intellectual Chinese professional woman, 29 years old, elegant intelligent features with tortoiseshell glasses, medium-length soft wavy hair naturally styled, slim graceful figure, wearing a smart tailored grey vest over a silk blouse paired with wide-leg trousers, holding a coffee cup with both hands, warm knowing smile with a hint of playful wisdom, sitting by the window in a stylish cafe, photorealistic, 8K --ar 1:1', '理性又仗义的知性女性，五官知性优雅，戴细框或玳瑁眼镜，中长发微卷自然披散，身材苗条，穿着剪裁利落的西装马甲配阔腿裤或修身连衣裙，手握咖啡杯或文件夹，表情理性中带一丝俏皮', '/aid/lib/character/2026/07/09/知性闺蜜·律师·女·26-32岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/06/16/知性闺蜜·律师·女·26-32岁.png');
INSERT INTO `aid_comic_asset` VALUES (107, 'reference_character', '外卖·快递小哥·男·20-28岁', 'cinematic portrait of a young Chinese delivery rider, 24 years old, healthy sun-kissed wheat complexion, bright energetic eyes full of determination, short neat black hair, lean wiry build, wearing a bright yellow delivery platform uniform jacket with reflective stripes, safety helmet tucked under arm, electric scooter keys clipped to belt, slight sweat on brow but a genuine bright smile, standing beside his scooter on a busy street, photorealistic, 8K --ar 1:1', '朴实阳光的年轻劳动者，皮肤因日晒呈健康小麦色，眼神明亮有干劲，短发清爽，身材精瘦结实，穿着黄色或蓝色外卖平台工服头戴安全头盔，电动车钥匙挂在腰间，汗水浸湿衣领但笑容灿烂', '/aid/lib/character/2026/07/09/外卖·快递小哥·男·20-28岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/06/16/外卖·快递小哥·男·20-28岁.png');
INSERT INTO `aid_comic_asset` VALUES (108, 'reference_character', '夜市摊主·市井大叔·男·35-45岁', 'cinematic portrait of a hearty middle-aged Chinese street food vendor, 40 years old, round ruddy face with deep laugh lines around crinkly warm eyes, stocky strong build with powerful arms from years of wok cooking, wearing a white tank top under a well-worn apron, a white hand towel draped around his neck, holding a well-used metal wok spatula, broad genuine grin, standing in front of his steaming food stall at night, photorealistic, 8K --ar 1:1', '热情豪爽的市井中年，圆脸微胖面色红润，笑起来眼角满是褶子，手臂粗壮有力常年在灶台前忙碌，穿白色背心或宽松T恤外罩围裙，脖子上搭一条白毛巾，手拿炒勺或蒲扇，市井烟火气十足', '/aid/lib/character/2026/07/09/夜市摊主·市井大叔·男·35-45岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/06/16/夜市摊主·市井大叔·男·35-45岁.png');
INSERT INTO `aid_comic_asset` VALUES (109, 'reference_character', '咖啡店老板·文艺青年·男·25-32岁', 'cinematic portrait of an artistic young Chinese cafe owner, 28 years old, lean sensitive face with slightly unkempt charm, warm but slightly distant contemplative eyes, shoulder-length slightly wavy hair loosely tied back, slender artistic build, wearing a rumpled linen shirt under a striped apron, wooden beaded bracelets on wrist, faint coffee stains on fingers, quiet observant expression, leaning against the counter of his cozy book-filled cafe, photorealistic, 8K --ar 1:1', '文艺气息的温暖青年，清瘦面孔略带不羁，眼神温暖又带疏离感，微长卷发随意扎起或披散，身材清瘦，穿着亚麻衬衫或条纹围裙，手腕有几串木质手串，手指有颜料或咖啡渍，安静观察者的气质', '/aid/lib/character/2026/07/09/咖啡店老板·文艺青年·男·25-32岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/06/16/咖啡店老板·文艺青年·男·25-32岁.png');
INSERT INTO `aid_comic_asset` VALUES (110, 'reference_character', '网约车司机·男·30-45岁', 'cinematic portrait of an ordinary middle-aged Chinese ride-share driver, 38 years old, average weary but kind face, observant eyes that have seen countless stories, slightly receding hairline, mild dad-bod build, wearing a comfortable striped polo shirt and casual jacket, phone mounted on dashboard with ride-hailing app visible, thermal flask and mints on the console, half-turned from driver seat looking back with a knowing patient expression, warm interior car lighting, photorealistic, 8K --ar 1:1', '平凡又有人情味的中年司机，普通中年面孔略显疲惫，眼睛通过后视镜观察一切，略秃顶或发际线后退，微胖体型，穿休闲Polo衫或宽松夹克，脖子上挂手机支架，车里仪表台放着保温杯和薄荷糖', '/aid/lib/character/2026/07/09/网约车司机·男·30-45岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/06/16/网约车司机·男·30-45岁.png');
INSERT INTO `aid_comic_asset` VALUES (111, 'reference_character', '老城区大爷·男·60-70岁', 'cinematic portrait of a spirited elderly Chinese man, 65 years old, weathered thin face with deep character lines, shrewd knowing eyes that miss nothing, short grey-white hair, lean slightly stooped frame, wearing a classic worn blue Mao suit jacket over a white undershirt, holding a well-used palm-leaf fan and a small portable radio, black cloth shoes, warm wrinkled smile hiding street-smart wisdom, sitting on a wooden stool in an old alleyway, photorealistic, 8K --ar 1:1', '悠闲又精明的老城区原住民，饱经风霜的瘦削面孔，眼神透着市井智慧，花白短发，身材清瘦微驼，穿着白色老头背心或旧中山装，手拿蒲扇和收音机，脚踩布鞋，笑容可掬实则门清', '/aid/lib/character/2026/07/09/老城区大爷·男·60-70岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/06/16/老城区大爷·男·60-70岁.png');
INSERT INTO `aid_comic_asset` VALUES (112, 'reference_character', '初恋白月光·女·18-24岁', 'cinematic portrait of an ethereal young Chinese woman, 20 years old, flawless porcelain skin glowing softly, extraordinarily clear innocent eyes, long flowing black hair with wispy bangs dancing in breeze, slender delicate figure, wearing a simple white cotton dress that catches the sunlight, white canvas shoes, a subtle luminous halo effect around her, gentle bittersweet smile with a touch of sadness, standing under cherry blossom trees in golden afternoon light, dreamlike nostalgic atmosphere, photorealistic, 8K --ar 1:1', '纯净美好的少女，瓷白肌肤吹弹可破，清澈眼眸不染尘埃，黑色长发飘飘刘海轻盈，身材纤细柔软，白色棉布连衣裙或校服白衬衫，帆布鞋，周身笼罩着淡淡光晕般的美好与易碎感', '/aid/lib/character/2026/07/09/初恋白月光·女·18-24岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/06/16/初恋白月光·女·18-24岁.png');
INSERT INTO `aid_comic_asset` VALUES (113, 'reference_character', '富二代纨绔·男·22-28岁', 'cinematic portrait of a rakish wealthy young Chinese playboy, 25 years old, handsome face with a perpetual mischievous smirk, flirtatious playful eyes, stylishly dyed ash-brown hair swept casually, tall lean build, wearing an expensive designer patterned silk shirt with top buttons undone revealing a silver chain, diamond stud earring, flashy luxury watch, one hand in pocket, cocky self-assured posture, leaning against a sports car at a rooftop bar at night, photorealistic, 8K --ar 1:1', '玩世不恭的富家公子，痞帅面孔带着玩味的笑容，桃花眼多情又漫不经心，染发或挑染潮色，身材高挑衣着张扬，穿各色奢侈品牌潮牌休闲装，大金表钻石耳钉，单手插兜嘴角上扬', '/aid/lib/character/2026/07/09/富二代纨绔·男·22-28岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/06/16/富二代纨绔·男·22-28岁.png');
INSERT INTO `aid_comic_asset` VALUES (114, 'reference_character', '叛逆少女·女·16-20岁', 'cinematic portrait of a rebellious Chinese teenage girl, 17 years old, thin angular face with defiant stubborn expression, slightly smudged self-applied dark eyeliner, dyed black hair with purple streaks, slender still-growing frame, wearing an oversized hoodie over a plaid mini skirt with combat boots, black choker necklace, temporary tattoo stickers on forearm, arms crossed defensively but eyes betraying vulnerability and longing, standing against a graffiti wall in an alley at dusk, photorealistic, 8K --ar 1:1', '倔强敏感的青春期女孩，清瘦面孔带着不服输的倔强，化着不太熟练的烟熏妆，黑发挑染紫色或蓝色，身材纤细未完全发育，穿宽松卫衣配短裙马丁靴戴choker项链，手臂有贴纸纹身，抱臂而立表情防御但眼底渴望温暖', '/aid/lib/character/2026/07/09/叛逆少女·女·16-20岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/06/16/叛逆少女·女·16-20岁.png');
INSERT INTO `aid_comic_asset` VALUES (115, 'reference_character', '温柔母亲·女·35-50岁', 'cinematic portrait of a warm gentle Chinese mother, 45 years old, soft kind face with fine smile lines around tender understanding eyes, black hair streaked with dignified silver threads neatly pinned up, slightly plump comforting build, wearing a cozy cream-colored knit cardigan over a simple blouse with a floral apron tied at the waist, holding a steaming cup of tea, warm maternal smile radiating unconditional love and home, standing in a sunlit cozy kitchen, photorealistic, 8K --ar 1:1', '慈爱包容的中年母亲，面容柔和眼角有细密笑纹，眼神温暖包容，黑发中夹杂几丝银发低盘或短发，身材微丰给人踏实感，穿素色开衫毛衣或棉麻家居服系着围裙，手里常端着一杯热茶或水果盘', '/aid/lib/character/2026/07/09/温柔母亲·女·35-50岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/06/16/温柔母亲·女·35-50岁.png');
INSERT INTO `aid_comic_asset` VALUES (116, 'reference_character', '深情父亲·男·38-50岁', 'cinematic portrait of a stoic loving Chinese father, 43 years old, weathered handsome face with quiet dignity, deep reserved eyes hiding unspoken love and concern, neat short hair with touches of grey at the temples, sturdy solid build, wearing a simple dark polo shirt with a practical jacket, an old but cherished watch on his wrist, rough capable hands that have worked hard, subtle gentle expression beneath the quiet exterior, standing beside his car looking out thoughtfully, photorealistic, 8K --ar 1:1', '沉默但深情的父亲，中年面孔略显沧桑但不失英俊，眼神深沉内敛藏着不表达的关爱，短发整齐微有白发，身材壮实或微胖，穿简约夹克或深色Polo衫，手腕戴旧手表，手掌粗糙有力，不善言辞但行动有力', '/aid/lib/character/2026/07/09/深情父亲·男·38-50岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/06/16/深情父亲·男·38-50岁.png');
INSERT INTO `aid_comic_asset` VALUES (117, 'reference_character', '冷面王爷·男·26-33岁', 'cinematic portrait of a cold commanding ancient Chinese prince, 30 years old, sharp sword-like eyebrows above piercing frost-cold phoenix eyes, angular chiseled features of devastating handsomeness, ink-black hair perfectly bound in a white jade crown, tall imposing figure, wearing a magnificent black brocade robe with subtle dark dragon patterns under a matching cloak with fur trim, jade belt with an ornate sword, powerful hands with prominent knuckles resting on a carved desk, cold unreadable expression radiating authority and danger, photorealistic ancient Chinese noble style, 8K --ar 1:1', '杀伐决断的冷峻王爷，剑眉入鬓冷眸如霜，五官如刀削斧劈般凌厉英俊，墨发以玉冠束起一丝不乱，身高185+，玄色或墨蓝暗纹锦袍外罩同色大氅，腰间玉带佩剑，指节分明的手轻叩桌面，气场令人不敢逼视', '/aid/lib/character/2026/07/09/冷面王爷·男·26-33岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/06/16/冷面王爷·男·26-33岁.png');
INSERT INTO `aid_comic_asset` VALUES (118, 'reference_character', '穿越庶女·王妃·女·18-24岁', 'cinematic portrait of a clever resilient young woman in ancient China, 20 years old, elegant oval face with refreshing natural beauty, lively intelligent eyes gleaming with modern wit and sharp perception, dark hair in simple maiden braids with a delicate silver hairpin, slender figure but with a straight determined posture, wearing a modest gracefully draped pale green ruqun with flowing sleeves, a small handmade charcoal pencil peeking from her sleeve, subtle knowing smile playing at her lips, standing in a moonlit ancient garden, photorealistic ancient Chinese palace style, 8K --ar 1:1', '聪慧机敏的穿越女/庶女，古典鹅蛋脸清丽脱俗，眼睛灵动有现代人的狡黠与清醒，乌发梳垂挂髻配简单银簪，身材纤细但脊背挺直，穿素雅的浅绿或月白色交领襦裙，袖中藏着自制的炭笔小本，唇角微扬心中有数', '/aid/lib/character/2026/07/09/穿越庶女·王妃·女·18-24岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/06/16/穿越庶女·王妃·女·18-24岁.png');
INSERT INTO `aid_comic_asset` VALUES (119, 'reference_character', '腹黑太子·男·22-30岁', 'cinematic portrait of a scheming handsome crown prince of ancient China, 27 years old, face as fine as carved jade with unnervingly perfect features, phoenix eyes curved in a gentle smile that never reaches their calculating depths, ink-black hair crowned with an elaborate gold guan, tall elegant figure, wearing a magnificent golden embroidered robe with five-clawed dragon motifs, holding a white jade ruyi scepter, surface warmth of a spring breeze but eyes cold as a winter lake, standing in a grand imperial hall, photorealistic ancient Chinese imperial style, 8K --ar 1:1', '城府极深的东宫太子，面如冠玉俊美非凡，凤眼含笑却不见底藏着算计，墨发金冠束顶，身材修长风度翩翩，明黄或朱红五爪龙纹蟒袍，手持折扇或玉如意，嘴角始终挂着温润如玉的微笑，眼底却是一片寒潭', '/aid/lib/character/2026/07/09/腹黑太子·男·22-30岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/06/16/腹黑太子·男·22-30岁.png');
INSERT INTO `aid_comic_asset` VALUES (120, 'reference_character', '倾城宠妃·女·18-26岁', 'cinematic portrait of a devastatingly beautiful imperial consort, 23 years old, exquisite heart-shaped face with mesmerizing peach-blossom eyes that captivate with every glance, luminous snow-white skin, elaborate cloud-bun hairstyle adorned with gold hairpins and dangling pearl ornaments, draped in a sumptuous pomegranate-red silk court gown with gold-thread phoenix embroidery and a sweeping train, red-painted fingernails holding an embroidered silk fan half-hiding her face, seductive yet calculating expression, standing in a lavish palace garden, photorealistic ancient Chinese imperial style, 8K --ar 1:1', '容貌倾国倾城的后宫宠妃，绝色瓜子脸桃花眼流转顾盼生辉，肌肤胜雪吹弹可破，青丝梳成华丽的朝云近香髻金步摇满头珠翠，身披华贵的石榴红或玫红织金宫装曳地长裙，指尖涂蔻丹持团扇半遮面，眼底野心与风情交织', '/aid/lib/character/2026/07/09/倾城宠妃·女·18-26岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/06/16/倾城宠妃·女·18-26岁.png');
INSERT INTO `aid_comic_asset` VALUES (121, 'reference_character', '少年剑客·男·16-22岁', 'cinematic portrait of a spirited young Chinese swordsman, 19 years old, handsome youthful face with boyish determination and wide-eyed wonder, clear bright eyes beneath sword-straight brows, long black hair tied in a high ponytail with a simple cloth band, lean agile build poised for action, wearing practical deep blue martial artist robes with fitted sleeves and leather bracers, a three-foot fine steel sword strapped across his back, clothes slightly travel-worn, brave hopeful expression, standing at the edge of a misty bamboo forest, photorealistic wuxia style, 8K --ar 1:1', '意气风发的初出江湖少年，俊朗青涩的面孔带着少年的锐气与好奇，剑眉星目眼神清澈明亮，黑发高马尾束起用布带随意绑着，身材清瘦但灵活有力，身穿青色或灰蓝色劲装短打，背负三尺青锋长剑，衣角微有风尘', '/aid/lib/character/2026/07/09/少年剑客·男·16-22岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/06/16/少年剑客·男·16-22岁.png');
INSERT INTO `aid_comic_asset` VALUES (122, 'reference_character', '江湖侠女·女·18-25岁', 'cinematic portrait of a fierce beautiful Chinese swordswoman, 22 years old, strikingly handsome features with a beauty that rivals any man, autumn-water eyes sharp with lethal grace, long black hair tied in a high warrior ponytail with flowing red ribbons, tall lithe athletic figure, wearing a form-fitting crimson martial arts outfit with a cinched waist and tight sleeves for combat, a flexible sword coiled at her hip, hand resting on the hilt ready to draw, proud fearless expression, standing atop a rocky outcrop with wind whipping her hair and ribbons, photorealistic wuxia style, 8K --ar 1:1', '英姿飒爽的红衣侠女，明艳五官英气逼人不输男儿，眼如秋水又含锋芒，墨发梳高马尾系红丝带随风飘扬，身材修长柔韧，一袭红衣劲装束腰窄袖，腰间缠绕软剑或长鞭，手握剑柄英姿勃发', '/aid/lib/character/2026/07/09/江湖侠女·女·18-25岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/06/16/江湖侠女·女·18-25岁.png');
INSERT INTO `aid_comic_asset` VALUES (123, 'reference_character', '茶馆老板娘·女·25-35岁', 'cinematic portrait of a captivating Chinese teahouse proprietress, 30 years old, mature alluring oval face with knowing phoenix eyes that switch between seductive half-lidded charm and razor-sharp perception, dark hair loosely pinned in an elegant lazy bun with a single jade hairpin, graceful voluptuous figure, wearing a deep purple embroidered fitted qipao-style dress, emerald bangle on her fair wrist, holding an elegant long-spout copper teapot mid-pour, welcoming smile with hidden steel, standing in her atmospheric lantern-lit teahouse, photorealistic ancient Chinese style, 8K --ar 1:1', '风情万种的消息灵通之人，成熟妩媚的鹅蛋脸，丹凤眼微眯时风情无限睁开时锐利洞察，乌发松松挽成慵懒髻斜插一根玉簪，身材丰腴有致，穿深紫或暗红绣花旗袍式改良襦裙，皓腕戴翡翠镯，手持长嘴铜壶斟茶，八面玲珑笑里藏刀', '/aid/lib/character/2026/07/09/茶馆老板娘·女·25-35岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/06/16/茶馆老板娘·女·25-35岁.png');
INSERT INTO `aid_comic_asset` VALUES (124, 'reference_character', '仙门师尊·男·外表30岁', 'cinematic portrait of an ageless transcendent immortal cultivator, appearing 35 years old, refined timeless face unmarked by age, eyes like ancient wells reflecting the cosmos itself, pure white hair half-bound with a simple jade hairpin the rest cascading like a silver waterfall, tall ethereal slender frame, wearing flowing pristine white Taoist robes with subtle cloud and crane embroidery, holding a white horsetail whisk, faint spiritual energy visible as luminescent particles around him, serene omniscient expression, floating above a sea of clouds at dawn, photorealistic xianxia style, 8K --ar 1:1', '仙风道骨的修行大成者，面容清隽看不出年龄痕迹，目如古井深邃有星辰流转，雪白长发以玉簪半束其余垂落如瀑，身材清瘦飘逸，纯白或浅青色广袖道袍绣有流云仙鹤暗纹，手持拂尘或背负古剑，周身淡淡灵气如烟', '/aid/lib/character/2026/07/09/仙门师尊·男·外表30岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/06/16/仙门师尊·男·外表30岁.png');
INSERT INTO `aid_comic_asset` VALUES (125, 'reference_character', '魔界少主·男·外表22-28岁', 'cinematic portrait of a dangerously beautiful demon realm prince, appearing 25 years old, unnervingly exquisite androgynous beauty, blood-red pupils that faintly glow in darkness, wild ink-purple hair cascading freely past his shoulders, pale translucent skin, tall lean body with subtle defined muscles, wearing an elaborate black and crimson brocade robe open at the chest revealing dark demonic markings on his collarbone, dark purple demonic energy swirling around him like smoke, seductive cruel smirk, sitting lazily on a throne of black iron and bone, photorealistic dark xianxia style, 8K --ar 1:1', '亦正亦邪的魔界继承人，极致的邪魅俊美雌雄莫辨，血色瞳孔在黑暗中微微发光，墨紫色长发不束不冠肆意披散，皮肤苍白近乎透明，身材修长肌肉精瘦，暗红与黑色交织的魔纹锦袍大敞领口露出锁骨与黑色魔纹，周身缭绕暗紫魔气', '/aid/lib/character/2026/07/09/魔界少主·男·外表22-28岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/06/16/魔界少主·男·外表22-28岁.png');
INSERT INTO `aid_comic_asset` VALUES (126, 'reference_character', '隐世高僧·老顽童·男·外表60-80岁', 'cinematic portrait of an eccentric enlightened old master, appearing 70 years old, round rosy-cheeked face with chrysanthemum-like laugh wrinkles, eyes usually squinted in mirth but occasionally flashing with profound wisdom, long white eyebrows and a flowing white beard merging into one majestic cascade, short roundish body that moves with surprising lightness, wearing simple patched but clean grey monk robes, a worn gourd of wine tied at his waist, holding a tattered palm-leaf fan, childlike mischievous grin that also holds the compassion of Buddha, sitting cross-legged on a rock amid swirling mountain mist, photorealistic xianxia style, 8K --ar 1:1', '深藏不露的世外高人，红光满面皱纹如菊却童颜鹤发，眼睛眯成一线偶尔精光乍现，雪白长眉垂落与长须白髯融为一体，身材矮小微胖但步伐轻盈，破旧但干净的灰色或黄色僧袍，腰间挂酒葫芦手持破蒲扇，笑容似孩童顽皮又似佛陀慈悲', '/aid/lib/character/2026/07/09/隐世高僧·老顽童·男·外表60-80岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/06/16/隐世高僧·老顽童·男·外表60-80岁.png');
INSERT INTO `aid_comic_asset` VALUES (127, 'reference_prop', '豪车钥匙·金属皮革', 'cinematic close-up product shot of a luxury car key fob, brushed silver metal casing with soft black leather key pouch embossed with subtle logo, placed on a dark polished mahogany desk surface, warm office lamp reflecting off the metal edges, shallow depth of field blurring the opulent background, symbol of wealth and power, photorealistic, 8K --ar 1:1', '顶级豪车品牌钥匙，银色金属外壳配真皮钥匙套，按键带品牌Logo镭射雕刻，放在深色木质桌面或真皮座椅上，低调却昭示身份，关联角色霸道总裁、富二代纨绔', '/aid/lib/prop/2026/06/17/豪车钥匙·金属皮革.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (128, 'reference_prop', '钻戒·珠宝盒·钻石铂金', 'cinematic close-up of an open navy blue velvet ring box, a stunning cushion-cut diamond solitaire ring nestled inside, platinum band with micro-pavé diamonds on the shoulders, brilliant fire and sparkle refracting under warm candlelight, gold-embossed luxury brand logo visible inside the lid, placed on a white linen tablecloth beside a single rose, romantic proposal atmosphere, photorealistic, 8K --ar 1:1', '打开的深蓝色天鹅绒戒指盒，内嵌一枚枕形切割大钻戒，铂金戒托密镶碎钻，盒盖内侧烫金品牌Logo，灯光下火彩璀璨，关联角色豪门千金、霸道总裁', '/aid/lib/prop/2026/06/17/钻戒·珠宝盒·钻石铂金.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (129, 'reference_prop', '名牌手包·皮革金属', 'cinematic product shot of an iconic luxury designer handbag, black quilted lambskin leather with gold-toned chain strap and signature turn-lock clasp, chain strap elegantly draped beside it, resting on a polished white marble surface, soft natural window light highlighting the leather texture and gold hardware, sophisticated and timeless, photorealistic, 8K --ar 1:1', '经典款奢侈品牌链条包，黑色荔枝纹小羊皮配金色五金件，翻盖上标志性菱格Logo扣，金属链条肩带垂落，放在大理石台面上，关联角色豪门千金、精英女强人', '/aid/lib/prop/2026/06/17/名牌手包·皮革金属.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (130, 'reference_prop', '雪茄与雪茄剪·烟草金属木材', 'cinematic close-up of a premium Cuban cigar resting on a Spanish cedar wood case, a stainless steel guillotine cigar cutter beside it, the dark oily wrapper of the cigar showing rich tobacco veins, a wisp of aromatic blue smoke curling upward from the tip, heavy crystal ashtray in the blurred background, warm amber lighting from a desk lamp, old money masculine atmosphere, photorealistic, 8K --ar 1:1', '古巴雪茄置于雪松木盒中，旁边一把断头台式不锈钢雪茄剪，木盒纹理细腻，雪茄深棕色茄衣泛着油光，烟灰缸中一缕青烟袅袅升起，关联角色中年董事长、霸道总裁', '/aid/lib/prop/2026/06/17/雪茄与雪茄剪·烟草金属木材.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (131, 'reference_prop', '笔记本电脑·金属玻璃', 'cinematic desk-level shot of a sleek silver ultrabook laptop, screen glowing with a half-finished presentation slide with colorful charts, keyboard backlit in soft white, a steaming cup of coffee beside it, scattered colorful sticky notes on the clean white desk surface, bright modern office background blurred out, focused productive atmosphere, photorealistic, 8K --ar 1:1', '超薄银色金属笔记本半开状态，屏幕显示未完成的PPT图表，键盘背光微微发光，旁边放着一杯还冒热气的咖啡，现代办公桌上散落几张便签纸，关联角色职场OL、实习小白', '/aid/lib/prop/2026/06/17/笔记本电脑·金属玻璃.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (132, 'reference_prop', '文件夹·合同·纸张皮革', 'cinematic overhead shot of an open dark brown leather portfolio folder, a stack of crisp white A4 contract documents inside with dense legal text and red annotated clauses, a signature half-completed in black fountain pen ink, a Montblanc pen resting diagonally across the page, cool white conference room lighting casting minimal shadows, professional and decisive atmosphere, photorealistic, 8K --ar 1:1', '深棕色皮质文件夹摊开，内夹一叠A4打印合同，纸张边缘整齐，黑色钢笔签名栏部分已签，旁边放着一支万宝龙钢笔，纸面在冷白会议灯光下清晰锐利，关联角色精英女强人、知性律师', '/aid/lib/prop/2026/07/09/文件夹·合同·纸张皮革.png', '0', NULL, '', NULL, '', '/aid/lib/prop/2026/06/17/文件夹·合同·纸张皮革.png');
INSERT INTO `aid_comic_asset` VALUES (133, 'reference_prop', '咖啡杯·陶瓷', 'cinematic close-up of a white ceramic coffee cup on a matching saucer, a perfect latte art rosetta pattern floating on the surface of the coffee, small silver spoon resting on the saucer edge, the cup casting a soft shadow on warm wooden table grain, gentle morning sunlight from a nearby window illuminating the steam, cozy cafe atmosphere, photorealistic, 8K --ar 1:1', '白色陶瓷马克杯配精致杯碟，杯中拉花拿铁图案完整，旁边小银勺搁在碟边，杯身有简约手写体文字或Logo，木桌纹理映衬下温暖舒适，关联角色实习小白、咖啡店老板', '/aid/lib/prop/2026/06/17/咖啡杯·陶瓷.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (134, 'reference_prop', '工牌·门禁卡·塑料金属', 'cinematic close-up of an employee ID badge on a dark blue lanyard, the transparent holder showing a professional headshot photo and corporate logo, a white RFID access card clipped beside it, the lanyard slightly frayed from daily use, hanging against a blurred modern office lobby background with glass turnstiles, everyday corporate life detail, photorealistic, 8K --ar 1:1', '挂在深蓝色挂绳上的员工工牌，透明卡套中露出证件照和公司Logo，旁边夹着一张感应门禁卡，挂绳微旧带着长期使用的痕迹，关联角色实习小白、职场OL', '/aid/lib/prop/2026/06/17/工牌·门禁卡·塑料金属.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (135, 'reference_prop', '外卖保温箱·牛津布铝箔', 'cinematic shot of a bright yellow insulated delivery food carrier box strapped to the back of an electric scooter, reflective safety strips and platform logo printed on the side, slightly dusty and rain-spotted from countless deliveries, several order receipts tucked under the securing bungee cords, parked in a narrow urban alley with warm street lamp glow, hardworking city life symbol, photorealistic, 8K --ar 1:1', '黄色方形外卖保温箱绑在电动车后座，箱体有平台Logo反光条，表面微脏有风雨痕迹，箱盖上用绑带固定着几份外卖小票，关联角色外卖小哥', '/aid/lib/prop/2026/06/17/外卖保温箱·牛津布铝箔.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (136, 'reference_prop', '老式收音机·塑料金属', 'cinematic close-up of a vintage 1980s portable radio, faded red plastic casing with silver metal speaker grille showing slight rust, telescopic antenna fully extended, analog tuning dial with Chinese frequency markings, resting on a weathered wooden stool beside a well-worn palm-leaf fan, soft afternoon light in an old alleyway, nostalgic generational atmosphere, photorealistic, 8K --ar 1:1', '80年代经典便携收音机，红色塑料外壳微有褪色，银色金属网罩上有些许锈迹，伸缩天线拉出，刻度盘手动调频，旁边放着一把蒲扇，关联角色老城区大爷', '/aid/lib/prop/2026/06/17/老式收音机·塑料金属.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (137, 'reference_prop', '保温杯·搪瓷茶缸·不锈钢', 'cinematic close-up of a well-used stainless steel thermal flask with slight scratches and paint chips, lid unscrewed with steam rising from the hot tea inside, next to a vintage enamel mug with faded red slogan lettering and a few chipped spots revealing the metal beneath, resting on a car center console with a phone mount in the blurred background, everyday working-class warmth, photorealistic, 8K --ar 1:1', '不锈钢保温杯杯身微有划痕和掉漆，杯盖拧开冒着热气，旁边一个老式搪瓷茶缸印着红字标语，杯沿搪瓷磕掉几块露出铁底，关联角色网约车司机、夜市摊主', '/aid/lib/prop/2026/06/17/保温杯·搪瓷茶缸·不锈钢.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (138, 'reference_prop', '雨伞·尼龙金属塑料', 'cinematic shot of a transparent long-handled umbrella leaning against a wet wooden bench, raindrops still clinging to the clear plastic canopy catching street lamp reflections, a single droplet about to fall from the metal tip, wet pavement reflecting warm city lights in the background, lonely yet romantic rainy night atmosphere, photorealistic, 8K --ar 1:1', '透明长柄雨伞靠在墙边或长椅旁，伞面水珠晶莹未干，伞骨末端水滴将落未落，地面湿漉漉倒映城市灯火，雨夜孤独又浪漫的氛围，关联角色灰姑娘女主、温柔母亲', '/aid/lib/prop/2026/07/09/雨伞·尼龙金属塑料.png', '0', NULL, '', NULL, '', '/aid/lib/prop/2026/06/17/雨伞·尼龙金属塑料.png');
INSERT INTO `aid_comic_asset` VALUES (139, 'reference_prop', '玫瑰花束·鲜花包装纸', 'cinematic close-up of a beautifully wrapped bouquet of fresh pink and red roses, deep green leaves framing the blooms, wrapped in cream-colored matte paper tied with a satin ribbon bow, tiny water droplets glistening on the velvet petals, resting on a wooden park bench in soft golden afternoon light, romantic and hopeful atmosphere, photorealistic, 8K --ar 1:1', '一束精心包扎的红玫瑰或粉玫瑰，深绿色叶片衬底，外层米色雾面纸包裹系着缎带，花瓣上还带着细小水珠，放在木质长椅或咖啡桌上，关联角色初恋白月光、温柔男二', '/aid/lib/prop/2026/06/17/玫瑰花束·鲜花包装纸.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (140, 'reference_prop', '电影票根·纸', 'cinematic top-down close-up of two torn movie ticket stubs placed side by side, printed with a romantic film title showtime and seat numbers, edges slightly curled and softened from being held, resting on a wooden cafe table next to a coffee cup, soft bokeh lights in the background, nostalgic memory of a shared moment, photorealistic, 8K --ar 1:1', '两张撕过的电影票根并排放置，票面印着片名时间座位号，边缘微微卷起，放在咖啡杯旁或夹在书页中，承载一段共同的回忆，关联角色初恋白月光、温柔男二', '/aid/lib/prop/2026/07/09/电影票根·纸.png', '0', NULL, '', NULL, '', '/aid/lib/prop/2026/06/17/电影票根·纸.png');
INSERT INTO `aid_comic_asset` VALUES (141, 'reference_prop', '红酒与高脚杯·玻璃酒液', 'cinematic close-up of two crystal wine glasses, one filled a third with deep ruby-red wine showing elegant legs on the glass wall, an opened bottle of premium red wine resting beside with the cork placed nearby, candlelight flickering through the glass creating warm amber reflections, white linen tablecloth beneath, intimate fine dining atmosphere, photorealistic, 8K --ar 1:1', '两只水晶高脚杯，一只已斟三分之一深红宝石色酒液，杯壁挂杯痕迹清晰，旁边斜躺一瓶打开的红酒，软木塞搁在一旁，烛光映在杯身光影流转，关联角色精英女强人、富二代纨绔', '/aid/lib/prop/2026/06/17/红酒与高脚杯·玻璃酒液.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (142, 'reference_prop', '老照片·拍立得·相纸', 'cinematic close-up of a slightly yellowed Polaroid photograph, a blurry but warm image of two silhouettes against a sunset background, a handwritten date scribbled in faded ink on the white border, held gently in open palms, edges softly curled from years of being treasured, warm nostalgic lighting, memory and longing atmosphere, photorealistic, 8K --ar 1:1', '一张微微泛黄的拍立得照片，画面是两个模糊人影的合影，照片一角有手写日期，放在手心里或夹在日记本扉页中，边缘微微卷翘带着时光痕迹，关联角色温柔母亲、初恋白月光', '/aid/lib/prop/2026/06/17/老照片·拍立得·相纸.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (143, 'reference_prop', '智能手机·玻璃金属', 'cinematic close-up of a modern smartphone with a slightly cracked screen protector, display glowing with an incoming call screen showing a contact photo, the phone vibrating subtly on a wooden nightstand, charging cable still connected, screen light illuminating the dark bedroom around it, connection and anticipation atmosphere, photorealistic, 8K --ar 1:1', '大屏智能手机屏幕亮着显示来电画面，手机壳微旧有使用痕迹，放在桌面或枕边，充电线还插着，屏幕光在昏暗房间中照亮周围，关联角色全角色通用', '/aid/lib/prop/2026/06/17/智能手机·玻璃金属.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (144, 'reference_prop', '围裙·棉麻', 'cinematic shot of a linen apron hanging on a wooden hook by the kitchen window, cream-colored with thin blue stripes, front pocket slightly frayed at the edges, faint traces of flour dusted on the fabric, soft morning light filtering through the window, warm homely kitchen atmosphere, photorealistic, 8K --ar 1:1', '一条挂在厨房窗边木钩上的米色条纹棉麻半身围裙，口袋边微微磨损，腰间系带自然垂落，布料上有淡淡的面粉印，温暖治愈的家居气息，关联角色温柔母亲', '/aid/lib/prop/2026/06/17/围裙·棉麻.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (145, 'reference_prop', '木质相框·木材玻璃', 'cinematic close-up of a dark walnut wood picture frame standing on a small side table, a warm family portrait visible through the slightly reflective glass, soft table lamp glow creating a gentle highlight on the frame edge, wood grain texture rich and natural, a cup of tea sitting beside it, home and belonging atmosphere, photorealistic, 8K --ar 1:1', '深色胡桃木相框立在小边柜上，框内是一张全家福合影，玻璃面反射柔和灯光，相框做工质朴有木纹，旁边放着一杯茶，关联角色温柔母亲、深情父亲', '/aid/lib/prop/2026/06/17/木质相框·木材玻璃.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (146, 'reference_prop', '医药箱·药瓶·塑料铝箔', 'cinematic overhead shot of an open white plastic home first-aid kit, compartments filled with medicine bottles band-aids and a digital thermometer, a few scattered pills on the lid beside cut aluminum foil blister packs, the warm glow of a bedside lamp casting soft shadows, quiet care and concern atmosphere, photorealistic, 8K --ar 1:1', '打开的家用塑料医药箱，内部分格装着感冒药瓶、创可贴、体温计，旁边散落着几粒药片和剪开的铝箔包装，台灯光线下透着关怀与担忧，关联角色深情父亲、温柔母亲', '/aid/lib/prop/2026/06/17/医药箱·药瓶·塑料铝箔.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (147, 'reference_prop', '团扇·丝绸竹刺绣', 'cinematic close-up of an exquisite ancient Chinese silk round fan, the delicate silk surface embroidered with blooming peonies and butterflies in gold and pink threads, sandalwood handle with a jade tassel and silk cord hanging elegantly, soft palace garden light filtering through the translucent silk, held by a delicate hand with red-painted fingernails just visible, elegant imperial harem atmosphere, photorealistic ancient Chinese style, 8K --ar 1:1', '圆形绢面团扇，扇面绣着精致的牡丹或蝶恋花图案，紫檀或象牙扇柄垂着流苏与玉坠，半掩美人面时扇面轻薄透光，指尖蔻丹隐现，关联角色倾城宠妃、穿越庶女', '/aid/lib/prop/2026/06/17/团扇·丝绸竹刺绣.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (148, 'reference_prop', '圣旨·卷轴·丝绸黄绢玉', 'cinematic close-up of an unrolled imperial edict on a dark zitan wood desk, brilliant yellow silk brocade with white jade rollers at both ends, vermilion ink calligraphy and the imperial crimson jade seal stamp clearly visible, subtle five-clawed dragon patterns woven into the silk shimmering under warm lantern light, solemn imperial authority atmosphere, photorealistic ancient Chinese style, 8K --ar 1:1', '明黄织锦圣旨在紫檀案几上展开，两端镶白玉卷轴，绢面上朱笔御批和玉玺朱印清晰可见，五爪龙纹暗花底纹在光下若隐若现，威严庄重，关联角色腹黑太子、冷面王爷', '/aid/lib/prop/2026/06/17/圣旨·卷轴·丝绸黄绢玉.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (149, 'reference_prop', '玉佩·令牌·玉石金绳结', 'cinematic close-up of a circular carved white jade pendant with intricate dragon relief patterns, warm translucent jade glowing under lantern light, tied with imperial yellow silk cords with elaborate knots, resting on top of a folded secret letter on a dark rosewood desk, a gold command token barely visible in the blurred edge, power and intrigue atmosphere, photorealistic ancient Chinese style, 8K --ar 1:1', '圆形镂雕羊脂白玉佩系着明黄绦带结，玉质温润通透雕龙纹或螭纹，压在紫檀木桌案的一封密信上，旁边或许还有一枚纯金调兵令牌，关联角色冷面王爷、腹黑太子', '/aid/lib/prop/2026/06/17/玉佩·令牌·玉石金绳结.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (150, 'reference_prop', '长剑·钢铁皮革木材', 'cinematic close-up of an ancient Chinese straight sword resting on weathered stone, three feet of fine steel partially drawn from the scabbard revealing a cold gleaming blade with distinctive folded steel wave patterns, the scabbard wrapped in dark rayskin with ornate brass fittings, worn leather grip wrapping showing battle experience, misty bamboo forest in the soft-focus background, wuxia spirit atmosphere, photorealistic, 8K --ar 1:1', '一柄三尺青锋长剑横置于石上或木桌，剑鞘鲨鱼皮包裹铜件錾花，剑柄缠深色防滑绳结，剑身出鞘三寸露出寒光逼人的锻打钢面，刃纹如水波流转，关联角色少年剑客、江湖侠女', '/aid/lib/prop/2026/07/09/长剑·钢铁皮革木材.png', '0', NULL, '', NULL, '', '/aid/lib/prop/2026/06/17/长剑·钢铁皮革木材.png');
INSERT INTO `aid_comic_asset` VALUES (151, 'reference_prop', '酒葫芦·葫芦藤编红绳', 'cinematic close-up of an aged dark brown gourd wine flask, surface polished smooth and glossy from years of handling, partially wrapped in woven rattan netting, red cord tied around the neck with a wooden stopper and tassel, resting on a rough wooden inn table beside a simple ceramic wine bowl, faint crack lines on the gourd telling stories of the road, rustic wuxia atmosphere, photorealistic, 8K --ar 1:1', '深棕色老葫芦外壳光滑油亮，藤编网兜半裹，红绳系着塞子垂下流苏，放在客栈木桌上旁边一只粗瓷酒碗，葫芦身上有细微裂纹记录江湖岁月，关联角色隐世高僧、江湖侠女', '/aid/lib/prop/2026/06/17/酒葫芦·葫芦藤编红绳.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (152, 'reference_prop', '斗笠·竹粽叶麻绳', 'cinematic shot of a wide-brimmed conical bamboo rain hat leaning against the wooden doorframe of an ancient inn, outer layer covered with dried bamboo leaves for waterproofing, inner bamboo strip weave tight and symmetrical, hemp cord ties hanging loosely, slightly yellowed and frayed from sun and rain, warm lantern light from within the inn spilling onto it, wanderer and journey atmosphere, photorealistic ancient Chinese style, 8K --ar 1:1', '宽檐圆锥竹编斗笠，外层覆粽叶防雨，内侧竹篾编纹紧密整齐，麻绳系带垂落，靠在客栈门边或挂在墙上，历经风霜微微泛黄，关联角色少年剑客、茶馆老板娘', '/aid/lib/prop/2026/06/17/斗笠·竹粽叶麻绳.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (153, 'reference_prop', '拂尘·白马尾檀木玉', 'cinematic close-up of a white horsetail whisk resting against a meditation cushion, the handle carved from luminous white jade with flowing Taoist talisman patterns, silver-white horsehair cascading like a waterfall of light, a jade ring and intricate knot at the handle end, faint spiritual energy particles glowing around the hairs, misty immortal realm visible beyond the temple pillars, transcendent xianxia atmosphere, photorealistic, 8K --ar 1:1', '一柄白玉柄白马尾拂尘斜倚在石台或蒲团旁，玉柄温润末端系着太极结，马尾长而银白如雪瀑垂落，手柄刻有道纹符箓在灵光下隐隐发亮，关联角色仙门师尊', '/aid/lib/prop/2026/06/17/拂尘·白马尾檀木玉.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (154, 'reference_prop', '丹药琉璃瓶·琉璃金丹', 'cinematic macro close-up of a small translucent glass bottle, several golden pills with intricate alchemical grain patterns visible inside, the neck sealed with red silk and tied with gold thread, one pill resting on the cork beside the bottle, faint luminescent medicinal vapor swirling around the pills, mysterious cultivation chamber lighting, magical alchemy atmosphere, photorealistic xianxia style, 8K --ar 1:1', '透明琉璃小瓶内装数粒金丹或暗紫色魔丹，丹药表面有细密丹纹，瓶口以红布或黑布封口系金丝绳，瓶身折射微光药气如烟缭绕，关联角色仙门师尊、魔界少主', '/aid/lib/prop/2026/06/17/丹药琉璃瓶·琉璃金丹.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (155, 'reference_prop', '红灯笼·纸竹丝绸', 'cinematic shot of a traditional Chinese red paper lantern hanging from dark wooden eaves, bamboo ribs forming an elegant oval shape, the red lantern surface hand-painted with gold calligraphy and flower motifs, warm candlelight glowing softly through the paper casting a warm amber halo, strings of identical lanterns receding into the background, festive yet nostalgic ancient Chinese atmosphere, photorealistic, 8K --ar 1:1', '传统中国红色纸灯笼，竹骨撑起椭圆或圆形灯体，灯面绘金色福字或花鸟，内置烛光透过红纸晕出温暖柔光，成串悬挂在木质屋檐下，关联角色茶馆老板娘、全古风角色', '/aid/lib/prop/2026/06/17/红灯笼·纸竹丝绸.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (156, 'reference_prop', '紫砂茶具·紫砂陶瓷', 'cinematic close-up of an exquisite Yixing purple clay tea set on a dark lacquered tea tray, a round Xi Shi teapot with a beautiful natural patina from years of use, two matching tiny tea cups beside it, fragrant steam drifting from the spout, a copper kettle simmering on a small charcoal brazier in the soft-focus background, tranquil tea ceremony atmosphere, photorealistic ancient Chinese style, 8K --ar 1:1', '一套宜兴紫砂茶具置于黑漆茶盘上，西施壶壶身圆润包浆莹润，两只紫砂小杯相配，壶嘴飘出缕缕茶香白雾，旁边铜壶在炭炉上咕嘟作响，关联角色茶馆老板娘、隐世高僧', '/aid/lib/prop/2026/06/17/紫砂茶具·紫砂陶瓷.png', '0', NULL, '', NULL, '', NULL);
