INSERT INTO `aid_comic_asset` VALUES (200, 'effect', '灵气流动·光带', 'cinematic shot of flowing ribbons of ethereal cyan and white spiritual energy streaming through the air, translucent luminous bands twisting and curling like silk in water, faint bioluminescent glow along the edges, flowing graceful movement, mystical cultivation atmosphere, pure visual effect no characters, photorealistic, 8K --ar 1:1', '飘逸的青色与白色灵气光带流过空中，半透明发光带如水中丝绸般扭转卷曲，边缘有微弱生物荧光，流动优雅的动态，神秘修炼氛围，纯特效无人物，可叠加日夜和雾', '/aid/lib/vfx/2026/06/17/灵气流动·光带.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (201, 'effect', '暗黑魔气·涌动', 'cinematic shot of swirling dark purple and black demonic energy, thick smoke-like tendrils writhing and coiling with malignant intent, occasional crimson lightning flashes within the darkness, oppressive heavy atmosphere, menacing supernatural presence, pure visual effect no characters, photorealistic, 8K --ar 1:1', '暗紫色与黑色魔气翻涌旋转，浓烟般的触手带着恶意蜿蜒缠绕，黑暗中偶有猩红闪电闪现，沉重压迫的氛围，阴森的超自然存在感，纯特效无人物，可叠加夜和冬和雾', '/aid/lib/vfx/2026/07/09/暗黑魔气·涌动.png', '0', NULL, '', NULL, '', '/aid/lib/vfx/2026/06/17/暗黑魔气·涌动.png');
INSERT INTO `aid_comic_asset` VALUES (202, 'effect', '星辰光点·闪烁', 'cinematic shot of countless tiny star-like light points twinkling against a deep indigo void, some stars pulsing brighter in rhythmic patterns like breathing celestial bodies, subtle nebula-like color gradients in the background, cosmic magical atmosphere, pure visual effect no characters, photorealistic, 8K --ar 1:1', '无数微小星辰般的光点在深邃靛蓝虚空中闪烁，有些星星以呼吸般的节奏渐强搏动，背景有隐约的星云色阶渐变，宇宙魔法氛围，纯特效无人物，可叠加夜和雾', '/aid/lib/vfx/2026/07/09/星辰光点·闪烁.png', '0', NULL, '', NULL, '', '/aid/lib/vfx/2026/06/17/星辰光点·闪烁.png');
INSERT INTO `aid_comic_asset` VALUES (203, 'effect', '传送法阵·光纹', 'cinematic overhead shot of an ancient glowing magic formation array appearing on a stone surface, intricate geometric and runic patterns traced in brilliant golden-white light, concentric rotating rings with floating ancient characters, energy pulsing outward from the center, mystical teleportation atmosphere, pure visual effect no characters, photorealistic, 8K --ar 1:1', '俯拍视角下的古老发光魔法阵在石质地面上浮现，精密的几何纹与符文以灿烂的白金色光芒描绘，同心旋转环上漂浮着古文，能量从阵心向外脉动，神秘传送氛围，纯特效无人物，可叠加夜和雾', '/aid/lib/vfx/2026/07/09/传送法阵·光纹.png', '0', NULL, '', NULL, '', '/aid/lib/vfx/2026/06/17/传送法阵·光纹.png');
INSERT INTO `aid_comic_asset` VALUES (204, 'effect', '结界光幕·屏障', 'cinematic shot of a translucent shimmering energy barrier wall, pale golden or cyan hexagonal grid pattern visible on the semi-transparent surface, rippling wave distortions spreading from an invisible impact point like water surface, faint crackling energy along the edges, protective defensive atmosphere, pure visual effect no characters, photorealistic, 8K --ar 1:1', '半透明闪烁的能量屏障墙，半透明表面可见淡金色或青色六边形网格纹样，波纹似的冲击扩散从隐形撞击点向外荡开如水波，边缘有微弱爆裂能量火花，守护防御氛围，纯特效无人物，可叠加日夜和雾', '/aid/lib/vfx/2026/07/09/结界光幕·屏障.png', '0', NULL, '', NULL, '', '/aid/lib/vfx/2026/06/17/结界光幕·屏障.png');
INSERT INTO `aid_comic_asset` VALUES (205, 'effect', '水墨晕染', 'cinematic shot of black ink slowly dispersing and blooming in clear water, organic smoke-like tendrils spreading outward in elegant curves, varying shades from deep black to pale grey wash, traditional Chinese ink painting aesthetic, artistic meditative atmosphere, pure visual effect no characters, photorealistic, 8K --ar 1:1', '黑色墨汁在清水中慢慢扩散盛放，有机的烟雾状触须以优雅的曲线向外蔓延，从浓黑到浅灰的丰富色阶变化，传统中国水墨画美学，写意冥想氛围，纯特效无人物，可叠加任意', '/aid/lib/vfx/2026/07/09/水墨晕染.png', '0', NULL, '', NULL, '', '/aid/lib/vfx/2026/06/17/水墨晕染.png');
INSERT INTO `aid_comic_asset` VALUES (206, 'effect', '花瓣飘落·唯美', 'cinematic shot of delicate pink peach blossom and white plum petals gently falling through the air, soft breeze carrying the petals in graceful swirling paths, warm golden backlight making the petals glow translucently, romantic ancient Chinese atmosphere, pure visual effect no characters, photorealistic, 8K --ar 1:1', '娇嫩的粉色桃花瓣与白色李花瓣在空中轻轻飘落，柔风将花瓣带入优雅旋转的轨迹，温暖的金色逆光使花瓣透亮发光，浪漫唯美古风氛围，纯特效无人物，可叠加日和春和晴', '/aid/lib/vfx/2026/07/09/花瓣飘落·唯美.png', '0', NULL, '', NULL, '', '/aid/lib/vfx/2026/06/17/花瓣飘落·唯美.png');
INSERT INTO `aid_comic_asset` VALUES (207, 'effect', '剑气纵横·光刃', 'cinematic shot of crescent-shaped sword energy waves slashing through the air, translucent white-blue razor-sharp arcs with trailing particle streaks, impact shockwave visible as concentric ring in the surrounding air, faint metallic gleam along the cutting edge, deadly elegant wuxia atmosphere, pure visual effect no characters, photorealistic, 8K --ar 1:1', '月牙形剑气波在空中劈斩，半透明白蓝色锐利弧光带着拖尾粒子痕迹，冲击激波以同心环状在周围空气中可见，刀刃边缘有微弱的金属光泽，凌厉优雅的武侠氛围，纯特效无人物，可叠加日夜和雾', '/aid/lib/vfx/2026/07/09/剑气纵横·光刃.png', '0', NULL, '', NULL, '', '/aid/lib/vfx/2026/06/17/剑气纵横·光刃.png');
INSERT INTO `aid_comic_asset` VALUES (208, 'effect', '雷电天罚·金色', 'cinematic shot of a massive golden divine lightning strike descending from turbulent storm clouds, the bolt branching into multiple jagged tendrils of pure white-gold energy, ground impact point erupting with crackling electrical arcs, blinding flash illuminating the surroundings, heavenly wrath atmosphere, pure visual effect no characters, photorealistic, 8K --ar 1:1', '巨大的金色天雷从翻滚的暴风云中劈落，雷电分叉成数道纯白金能量的锯齿闪电，地面落点爆发出噼啪作响的电弧，眩目闪光照亮周围，天谴之怒氛围，纯特效无人物，可叠加夜和雨雪', '/aid/lib/vfx/2026/07/09/雷电天罚·金色.png', '0', NULL, '', NULL, '', '/aid/lib/vfx/2026/06/17/雷电天罚·金色.png');
INSERT INTO `aid_comic_asset` VALUES (209, 'effect', '冰霜凝结·蔓延', 'cinematic macro shot of delicate frost crystals forming and spreading across a surface, intricate fern-like ice patterns growing in accelerated time, cold blue-white crystalline structures catching light with diamond-like sparkles, freezing temperature visibly creeping outward, cold supernatural atmosphere, pure visual effect no characters, photorealistic, 8K --ar 1:1', '精致的霜晶在表面上形成和蔓延的微距画面，复杂的蕨类纹样般的冰花以加速时间生长，冰冷的蓝白色结晶结构捕捉光线发出钻石般的闪烁，冻结温度肉眼可见地向外推进，寒冰超自然氛围，纯特效无人物，可叠加冬和雪', '/aid/lib/vfx/2026/07/09/冰霜凝结·蔓延.png', '0', NULL, '', NULL, '', '/aid/lib/vfx/2026/06/17/冰霜凝结·蔓延.png');
INSERT INTO `aid_comic_asset` VALUES (210, 'effect', '云海翻涌·仙境', 'cinematic wide shot of a vast sea of billowing clouds stretching to the horizon, soft cotton-like cloud tops rolling in slow majestic waves, golden sunrise or silver moonlight painting the cloud surface, mountain peaks barely visible piercing through the mist like islands, divine heavenly realm atmosphere, pure visual effect no characters, photorealistic, 8K --ar 1:1', '一望无际的翻涌云海延伸至地平线的广角画面，绵软的棉花般的云顶以缓慢而雄伟的波浪起伏，金色日出或银色月光描绘着云层表面，远山峰顶依稀刺破雾海如岛屿，神域天界氛围，纯特效无人物，可叠加日和雾', '/aid/lib/vfx/2026/07/10/云海翻涌·仙境.png', '0', NULL, '', NULL, '', '/aid/lib/vfx/2026/06/17/云海翻涌·仙境.png');
INSERT INTO `aid_comic_asset` VALUES (211, 'effect', '青烟袅袅·焚香', 'cinematic close-up of fragrant incense smoke drifting upward in a still room, the thin white smoke column rising straight then dissolving into elegant curling wisps, soft warm light catching the smoke making it glow, quiet meditative temple atmosphere, pure visual effect no characters, photorealistic, 8K --ar 1:1', '香炉中袅袅香烟在静室中向上升腾的特写，细细的白烟柱直升而上然后散开变作优雅的卷曲烟缕，柔和暖光捕捉烟雾使其微微发光，静谧禅意寺庙氛围，纯特效无人物，可叠加日夜和雨', '/aid/lib/vfx/2026/06/17/青烟袅袅·焚香.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (212, 'effect', '竹叶飘落·清风', 'cinematic shot of slender green bamboo leaves drifting down through dappled forest light, leaves spinning gently as they fall, warm golden-green sunlight filtering through the dense bamboo canopy creating light beams, peaceful zen wuxia atmosphere, pure visual effect no characters, photorealistic, 8K --ar 1:1', '细长的绿色竹叶穿过斑驳林间光飘落的画面，叶片轻柔旋转着落下，温暖的金绿色阳光穿过密集竹林冠层形成光束，宁静禅意武侠氛围，纯特效无人物，可叠加日和秋和雾', '/aid/lib/vfx/2026/06/17/竹叶飘落·清风.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (213, 'effect', '红绸飘动·古风', 'cinematic shot of flowing red silk ribbons dancing in an unseen wind, the translucent crimson fabric undulating in graceful waves, soft light glowing through the thin silk creating rich layered red tones, elegant sensual ancient Chinese atmosphere, pure visual effect no characters, photorealistic, 8K --ar 1:1', '飘逸的红绸丝带在无形的风中飞舞，半透明的绯红色织物以优雅的波浪形起伏，柔光穿透薄绸营造出丰富的红色层次变化，优雅感性的古风氛围，纯特效无人物，可叠加日夜和春秋', '/aid/lib/vfx/2026/06/17/红绸飘动·古风.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (214, 'effect', '火蝶飞舞·灵异', 'cinematic shot of burning butterfly-shaped embers rising through darkness, each fiery wing leaving a trailing spark path, the flame-butterflies pulsing with orange and crimson glow, some dissolving into ash mid-flight others soaring higher, haunting beautiful supernatural atmosphere, pure visual effect no characters, photorealistic, 8K --ar 1:1', '燃烧的蝴蝶形余烬在黑暗中升起飞舞，每片火焰翅膀都拖着火星尾迹，火蝶随着橙红光芒搏动，有的在半空中化为灰烬有的继续高飞，凄美超自然氛围，纯特效无人物，可叠加夜和雾', '/aid/lib/vfx/2026/07/10/火蝶飞舞·灵异.png', '0', NULL, '', NULL, '', '/aid/lib/vfx/2026/06/17/火蝶飞舞·灵异.png');
INSERT INTO `aid_comic_asset` VALUES (215, 'effect', '佛光普照·金色光晕', 'cinematic shot of warm golden divine light radiating outward in concentric soft halos, gentle rays of Buddha-light streaming from an implied sacred source, subtle lotus petal silhouettes faintly visible in the luminous glow, peaceful blessed transcendent atmosphere, pure visual effect no characters, photorealistic, 8K --ar 1:1', '温暖的金色佛光以同心柔和光晕向外辐射，温柔的光线从虚拟的圣洁源头流淌而出，依稀可见微弱的莲花瓣剪影在光中浮现，祥和超脱的圣境氛围，纯特效无人物，可叠加日和晴雾', '/aid/lib/vfx/2026/06/17/佛光普照·金色光晕.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (216, 'effect', '虚空裂隙·时空扭曲', 'cinematic shot of a reality-tearing portal rift opening in mid-air, jagged crack-like edges glowing with intense purple and blue energy, distorted space visible within the rift showing a different realm, lightning-like energy arcs sparking along the tear edges, dimensional-breaking supernatural atmosphere, pure visual effect no characters, photorealistic, 8K --ar 1:1', '一道撕裂现实的传送门裂隙在半空中打开，锯齿裂纹般的边缘发出强烈的紫蓝能量光芒，裂隙内部可见扭曲的不同次元景象，闪电般的能量弧沿裂缝边缘噼啪作响，维度破碎的超自然氛围，纯特效无人物，可叠加夜和雾雪', '/aid/lib/vfx/2026/07/09/虚空裂隙·时空扭曲.png', '0', NULL, '', NULL, '', '/aid/lib/vfx/2026/06/17/虚空裂隙·时空扭曲.png');
INSERT INTO `aid_comic_asset` VALUES (217, 'expression', '微笑·温柔', 'black and white clean line art, half-body portrait of a featureless bald mannequin head and shoulders, gentle warm smile with softly curved lips closed, eyes slightly narrowed in a kind expression with subtle crow feet lines, relaxed cheeks, serene peaceful aura, pure white minimalist background, no hair, clean precise outlines, manga-style inking, character expression reference sheet, 8K --ar 1:1', '白底黑白线稿半身人像，光头素体人偶温柔微笑，嘴唇闭合微微上翘，眼睛微眯带善意细纹，脸颊放松，宁静祥和，纯白极简背景，无头发遮挡五官，日式墨线风格', '/aid/lib/expression/2026/06/17/微笑·温柔.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (218, 'expression', '开心·大笑', 'black and white clean line art, half-body portrait of a featureless bald mannequin head and shoulders, wide open-mouthed joyful laughter, mouth open showing teeth, cheeks pushed up high, eyes squeezed into happy crescents with laugh lines at corners, head tilted slightly back, pure white minimalist background, no hair, clean precise outlines, manga-style inking, character expression reference sheet, 8K --ar 1:1', '白底黑白线稿半身人像，光头素体人偶开心大笑，嘴巴张开露齿，脸颊挤高，眼睛眯成快乐月牙带笑纹，头微后仰，纯白极简背景，无头发遮挡五官，日式墨线风格', '/aid/lib/expression/2026/06/17/开心·大笑.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (219, 'expression', '害羞·抿嘴', 'black and white clean line art, half-body portrait of a featureless bald mannequin head and shoulders, shy bashful expression with lips pressed together in a tight modest line, eyes looking slightly downward and away, faint blush lines on upper cheeks, eyebrows slightly raised, shoulders slightly hunched inward, pure white minimalist background, no hair, clean precise outlines, manga-style inking, character expression reference sheet, 8K --ar 1:1', '白底黑白线稿半身人像，光头素体人偶害羞表情，嘴唇抿成一线，眼睛向下看避开视线，脸颊上部淡淡红晕线，眉毛微抬，肩膀微向内缩，纯白极简背景，无头发遮挡五官，日式墨线风格', '/aid/lib/expression/2026/06/17/害羞·抿嘴.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (220, 'expression', '感动·含泪', 'black and white clean line art, half-body portrait of a featureless bald mannequin head and shoulders, deeply moved expression with glossy tear-filled eyes, eyebrows raised and drawn together in the center, lips trembling slightly with a quivering smile, single tear line rolling down one cheek, warm vulnerable emotion, pure white minimalist background, no hair, clean precise outlines, manga-style inking, character expression reference sheet, 8K --ar 1:1', '白底黑白线稿半身人像，光头素体人偶感动含泪表情，泪光闪闪的眼眶，眉毛上扬并向中央收拢，嘴唇微颤带颤抖的微笑，一道泪痕滑落脸颊，温暖脆弱情感，纯白极简背景，无头发遮挡五官，日式墨线风格', '/aid/lib/expression/2026/06/17/感动·含泪.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (221, 'expression', '得意·满足', 'black and white clean line art, half-body portrait of a featureless bald mannequin head and shoulders, smug self-satisfied expression, one eyebrow arched higher than the other, lopsided confident smirk with one corner of mouth pulled up, chin slightly lifted, eyes half-lidded with superiority, pure white minimalist background, no hair, clean precise outlines, manga-style inking, character expression reference sheet, 8K --ar 1:1', '白底黑白线稿半身人像，光头素体人偶得意满足表情，一边眉毛挑高，歪嘴自信笑嘴角一扬，下巴微抬，眼睛半垂带优越感，纯白极简背景，无头发遮挡五官，日式墨线风格', '/aid/lib/expression/2026/06/17/得意·满足.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (222, 'expression', '温柔深情·凝视', 'black and white clean line art, half-body portrait of a featureless bald mannequin head and shoulders, tender loving gaze with soft half-lidded eyes, pupils slightly dilated, gentle closed-lip smile, eyebrows relaxed and slightly raised in adoration, head tilted slightly to one side, warm affectionate aura, pure white minimalist background, no hair, clean precise outlines, manga-style inking, character expression reference sheet, 8K --ar 1:1', '白底黑白线稿半身人像，光头素体人偶温柔深情的凝视，半垂眼眸瞳孔微扩，柔和闭唇微笑，眉毛放松微扬充满爱慕，头轻歪向一侧，温暖深情氛围，纯白极简背景，无头发遮挡五官，日式墨线风格', '/aid/lib/expression/2026/06/17/温柔深情·凝视.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (223, 'expression', '陶醉·沉迷', 'black and white clean line art, half-body portrait of a featureless bald mannequin head and shoulders, enchanted intoxicated expression, eyes completely closed with relaxed heavy lids, lips slightly parted in a dreamy sigh, head tilted back gently, serene blissful state, subtle motion lines around the head suggesting floating sensation, pure white minimalist background, no hair, clean precise outlines, manga-style inking, character expression reference sheet, 8K --ar 1:1', '白底黑白线稿半身人像，光头素体人偶陶醉沉迷表情，双眼完全闭合眼皮放松沉重，双唇微启如梦般叹息，头轻向后仰，宁静极乐状态，淡淡漂浮感线条，纯白极简背景，无头发遮挡五官，日式墨线风格', '/aid/lib/expression/2026/06/17/陶醉·沉迷.png', '0', NULL, '', NULL, '', NULL);
