INSERT INTO `aid_comic_asset` VALUES (246, 'expression', '冷漠·无表情', 'black and white clean line art, half-body portrait of a featureless bald mannequin head and shoulders, completely blank expressionless face, eyes half-lidded with no emotion or light reflection, mouth a perfectly straight neutral line, all facial muscles completely relaxed to the point of emptiness, face like a mask revealing nothing, cold distant void, pure white minimalist background, no hair, clean precise outlines, manga-style inking, character expression reference sheet, 8K --ar 1:1', '白底黑白线稿半身人像，光头素体人偶冷漠无表情，眼睛半垂无任何情感无高光反射，嘴巴成完全平直的直线，所有面部肌肉完全放松到空洞的程度，面孔如同面具不透露任何信息，冰冷的遥远空洞，纯白极简背景，无头发遮挡五官，日式墨线风格', '/aid/lib/expression/2026/06/17/冷漠·无表情.png', '0', NULL, '', NULL, '', NULL);
