INSERT INTO `aid_comic_asset` VALUES (248, 'sketch', '现代建筑立面·手绘', 'hand-drawn elevation sketch of a contemporary glass skyscraper facade, precise clean ink lines with geometric grid patterns, subtle grey tone shading on the glass panels, blueprint-meets-artistic style, crisp architectural line weights varying from fine to bold, white paper background, concept art style, 8K --ar 1:1', '现代玻璃幕墙摩天大楼立面手绘线稿，精准干净墨线配几何网格纹样，玻璃面板上淡灰调阴影，蓝图与艺术风格结合，清晰建筑线条粗细变化，白纸背景', '/aid/lib/sketch/2026/06/17/现代建筑立面·手绘.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (249, 'sketch', '咖啡店内景·线稿', 'hand-drawn interior sketch of a cozy cafe, loose gestural ink lines capturing wooden tables chairs and a bar counter, espresso machine silhouetted in simple strokes, hanging pendant lamps suggested with minimal lines, warm grey wash adding depth to corners, sketchbook style with visible construction lines, white paper background, concept art style, 8K --ar 1:1', '温馨咖啡店内景手绘线稿，松散笔触捕捉木桌椅和吧台，意式咖啡机以简单轮廓勾勒，悬挂吊灯以最少线条暗示，暖灰调增加角落深度，速写本风格保留辅助线，白纸背景', '/aid/lib/sketch/2026/06/17/咖啡店内景·线稿.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (250, 'sketch', '人物日常动态·速写', 'hand-drawn gesture sketch of a standing human figure in casual modern clothing, fluid dynamic ink strokes capturing relaxed contrapposto pose, clothing folds suggested with minimal sweeping lines, no facial detail, loose grey wash for shadow masses, figure drawing reference style, white paper background, concept art style, 8K --ar 1:1', '现代休闲装扮站立人物动态速写手绘，流畅动态墨线捕捉放松的对立平衡姿态，衣物褶皱以最少扫掠线条暗示，无面部细节，松散灰调表现阴影体块，人体绘画参考风格，白纸背景', '/aid/lib/sketch/2026/06/17/人物日常动态·速写.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (251, 'sketch', '现代居家一角·素描', 'hand-drawn sketch of a modern living room corner, clean ink lines depicting a sofa side table and floor lamp, a window with flowing curtains suggested in light strokes, potted plant in simple silhouette, soft grey wash creating cozy shadow corners, warm inviting composition, white paper background, concept art style, 8K --ar 1:1', '现代客厅一角手绘素描，干净墨线描绘沙发边几和落地灯，飘窗轻纱以淡线暗示，盆栽简单剪影，柔和灰调营造温馨角落阴影，温暖宜人构图，白纸背景', '/aid/lib/sketch/2026/06/17/现代居家一角·素描.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (252, 'sketch', '办公室场景·线稿', 'hand-drawn interior sketch of a modern open-plan office, rows of desks with monitors and chairs in clean perspective lines, glass partition walls indicated with double line strokes, indoor plants in loose gestural marks, subtle grey wash on the ceiling and window areas, professional workspace atmosphere, white paper background, concept art style, 8K --ar 1:1', '现代开放式办公室内景手绘线稿，成排工位配显示器和椅子以清晰透视线条表现，玻璃隔断墙用双线笔触，室内绿植以松散笔触勾勒，天花板和窗户区域淡灰调，专业工作空间氛围，白纸背景', '/aid/lib/sketch/2026/06/17/办公室场景·线稿.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (253, 'sketch', '城市天际线·手绘', 'hand-drawn panoramic skyline sketch of a modern city, layered silhouette of skyscrapers in varying ink line densities, communication towers and cranes as fine detail accents, light grey wash creating atmospheric depth between near and far buildings, horizon line with hint of sky gradient, white paper background, concept art style, 8K --ar 1:1', '现代城市天际线全景手绘，摩天大楼以不同墨线密度叠加剪影，信号塔和塔吊作细节点缀，淡灰调营造远近建筑间的大气透视深度，地平线上隐约天空渐变，白纸背景', '/aid/lib/sketch/2026/06/17/城市天际线·手绘.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (254, 'sketch', '车内视角·速写', 'hand-drawn sketch of a car interior viewed from the back seat, steering wheel dashboard and windshield in clean perspective lines, rearview mirror and seat contours in simple strokes, view through windshield of a road vanishing into distance, subtle grey shading on the interior shadows, white paper background, concept art style, 8K --ar 1:1', '汽车内部后座视角手绘速写，方向盘仪表盘和挡风玻璃以清晰透视线条表现，后视镜和座椅轮廓简单笔触，挡风玻璃外道路延伸消失于远方，内饰阴影淡灰调，白纸背景', '/aid/lib/sketch/2026/06/17/车内视角·速写.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (255, 'sketch', '公园场景·素描', 'hand-drawn landscape sketch of an urban park, winding path with a wooden bench under a large tree in loose ink strokes, distant pond suggested with horizontal ripple lines, cherry blossom tree branches in delicate gestural marks, soft grey wash for foliage shadows and ground texture, peaceful atmosphere, white paper background, concept art style, 8K --ar 1:1', '城市公园景观手绘素描，蜿蜒小径配大树下木质长椅以松散墨线表现，远处池塘以水平涟漪线暗示，樱花树枝以细腻笔触勾勒，柔和灰调表现树荫和地面质感，宁静氛围，白纸背景', '/aid/lib/sketch/2026/06/17/公园场景·素描.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (256, 'sketch', '街边摊位·速写', 'hand-drawn sketch of a street food stall at night, simple canopy structure with hanging light bulbs as small circles, steam rising from cooking area in curling wispy lines, plastic stools and tables in quick gestural strokes, warm grey wash creating night atmosphere with light pools, lively street energy, white paper background, concept art style, 8K --ar 1:1', '夜间街边小吃摊手绘速写，简易遮阳棚结构配悬挂灯泡以小圆圈表现，烹饪区蒸汽以卷曲线条上升，塑料桌椅以快速笔触勾勒，暖灰调营造夜色和灯光池，生动街头活力，白纸背景', '/aid/lib/sketch/2026/06/17/街边摊位·速写.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (257, 'sketch', '古代宫殿·建筑手绘', 'hand-drawn architectural sketch of an ancient Chinese palace hall, clean ink lines depicting sweeping upturned eaves and tiered roofs, massive red columns in bold vertical strokes, dragon-carved stone steps in fine detail lines, subtle grey wash for roof shadow depth and stone texture, majestic imperial atmosphere, white paper background, concept art style, 8K --ar 1:1', '中国古代宫殿建筑手绘线稿，干净墨线描绘飞扬飞檐和层叠屋顶，粗壮红柱以粗竖线表现，龙纹石阶以精细线条刻画，淡灰调表现屋顶阴影和石材质感，雄伟皇家氛围，白纸背景', '/aid/lib/sketch/2026/06/17/古代宫殿·建筑手绘.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (258, 'sketch', '江湖侠客·招式速写', 'hand-drawn gesture sketch of a martial arts figure in dynamic combat pose, flowing robe and long hair captured in sweeping ink strokes conveying motion, sword extended forward in a bold diagonal line, speed lines and wind effects in quick gestural marks, loose grey wash defining the figure mass, wuxia action reference, white paper background, concept art style, 8K --ar 1:1', '武侠人物动态格斗姿态手绘速写，飘动衣袍和长发以扫掠墨线捕捉运动感，长剑以大胆斜线向前延伸，速度线和风效以快速笔触表现，松散灰调定义人物体块，武侠动作参考，白纸背景', '/aid/lib/sketch/2026/06/17/江湖侠客·招式速写.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (259, 'sketch', '古风庭院·线稿', 'hand-drawn sketch of a traditional Chinese courtyard garden, moon gate framed by bamboo and rock formations in flowing ink lines, a small pavilion with curved eaves in the middle ground, lotus pond suggested with horizontal ripple strokes, stone pathway winding through in perspective, soft grey wash for depth and foliage, white paper background, concept art style, 8K --ar 1:1', '传统中国园林庭院手绘线稿，月门以竹丛和假山石框出以流动墨线表现，中景曲檐小亭，荷塘以水平涟漪笔触暗示，石径以透视蜿蜒穿过，柔和灰调表现深度和叶丛，白纸背景', '/aid/lib/sketch/2026/06/17/古风庭院·线稿.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (260, 'sketch', '古街道·透视手绘', 'hand-drawn perspective sketch of an ancient Chinese town street, wooden shopfronts with hanging red lanterns on both sides receding into distance, cobblestone road texture in varied line weights, overhead tiled roofs with upturned eaves, subtle grey wash creating depth and shadow in doorways, white paper background, concept art style, 8K --ar 1:1', '中国古代小镇街道透视图手绘，两侧木构店铺挂着红灯笼向远处延伸，卵石路面以不同线重表现质感，头顶瓦片屋顶飞檐，淡灰调营造门口处深度和阴影，白纸背景', '/aid/lib/sketch/2026/06/17/古街道·透视手绘.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (261, 'sketch', '传统服饰人物·速写', 'hand-drawn fashion sketch of a figure in flowing traditional Chinese robes, layered garments with wide sleeves in elegant sweeping ink strokes, jade pendant at the waist in a few precise lines, hair in an ancient updo style with a simple hairpin, fabric folds and draping suggested with minimal shading strokes, graceful classical posture, white paper background, concept art style, 8K --ar 1:1', '传统中国宽袍大袖人物服饰手绘速写，层叠衣袍宽袖以优雅扫掠墨线表现，腰间玉佩以几笔精准线条勾勒，发髻配简单发簪，布料褶皱和垂坠以最少阴影笔触暗示，优雅古典姿态，白纸背景', '/aid/lib/sketch/2026/06/17/传统服饰人物·速写.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (262, 'sketch', '山水意境·水墨素描', 'hand-drawn ink wash landscape sketch of mountains and water, distant peaks in pale grey wash with darker ink strokes defining ridges, a lone fishing boat on a misty lake in minimal lines, ancient pine trees on rocky outcrops in expressive brush-like strokes, clouds suggested with negative space and soft wash edges, classical Chinese landscape aesthetic, white paper background, concept art style, 8K --ar 1:1', '中国水墨山水手绘素描，远山以淡灰调渲染深色墨线勾勒山脊，雾湖上一叶孤舟以最少线条表现，古松在岩壁上以表现性笔触勾勒，云雾以留白和柔和渲染边线暗示，古典中国山水美学，白纸背景', '/aid/lib/sketch/2026/06/17/山水意境·水墨素描.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (263, 'sketch', '古桥流水·线稿', 'hand-drawn sketch of a traditional stone arch bridge over a gentle stream, weathered stone texture in varied ink line density, willow trees trailing branches into the water in soft sweeping strokes, water ripples and reflections in delicate horizontal lines, distant pavilion on the shore as a simple silhouette, grey wash for shadow and water depth, white paper background, concept art style, 8K --ar 1:1', '传统石拱桥跨过涓涓溪流手绘线稿，风化岩石质感以不同墨线密度表现，垂柳枝条以柔和扫掠笔触拖入水中，水面涟漪和倒影以细腻水平线描绘，远处岸边凉亭以简单剪影表现，灰调表现阴影和水深，白纸背景', '/aid/lib/sketch/2026/06/17/古桥流水·线稿.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (264, 'sketch', '客栈内景·手绘', 'hand-drawn interior sketch of an ancient Chinese inn, wooden beams and staircase in bold structural lines, tables and benches on the ground floor in perspective, wine jars stacked behind the counter in simple oval forms, paper lanterns hanging from beams as small circles with radiating light lines, warm grey wash creating cozy interior shadows, white paper background, concept art style, 8K --ar 1:1', '中国古代客栈内景手绘线稿，木梁和楼梯以粗结构线条表现，一楼桌椅以透视排列，柜台后酒坛以简单椭圆形状叠加，纸灯笼从横梁悬挂以小圆圈配辐射光线，暖灰调营造室内温馨阴影，白纸背景', '/aid/lib/sketch/2026/06/17/客栈内景·手绘.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (265, 'sketch', '古代器物·白描', 'hand-drawn still life sketch of traditional Chinese objects arranged on a table, a ceramic teapot and cups in clean precise contour lines, an open calligraphy scroll with brush resting beside, an incense burner with curling smoke wisps, subtle grey wash on object shadows, elegant classical still life composition, white paper background, concept art style, 8K --ar 1:1', '传统中国器物静物白描手绘，陶瓷茶壶茶杯以干净精准轮廓线表现，展开的书法卷轴配毛笔搁置一旁，香炉青烟袅袅卷曲线条，淡灰调表现物体阴影，优雅古典静物构图，白纸背景', '/aid/lib/sketch/2026/06/17/古代器物·白描.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (266, 'sketch', '竹林小径·速写', 'hand-drawn sketch of a narrow winding path through a dense bamboo forest, tall bamboo stalks in vertical ink strokes of varying thickness, dappled light effect created by broken lines and small grey wash patches, the path disappearing into misty distance, fallen bamboo leaves on the ground in scattered short strokes, serene zen atmosphere, white paper background, concept art style, 8K --ar 1:1', '茂密竹林间蜿蜒小径手绘速写，高耸竹竿以不同粗细竖线墨线表现，斑驳光影以断续线条和小块灰调渲染，小径消失于迷雾远方，地面竹叶以散落短笔触表现，静谧禅意氛围，白纸背景', '/aid/lib/sketch/2026/06/17/竹林小径·速写.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (267, 'sketch', '仙山云海·线稿', 'hand-drawn fantasy landscape sketch of floating mountain peaks above a sea of clouds, jagged rock formations in bold ink strokes with intricate cliff-face texture lines, ancient temples clinging to the mountainsides in tiny architectural details, swirling cloud patterns in soft circular grey wash strokes, divine light rays breaking through in radiating line groups, ethereal xianxia atmosphere, white paper background, concept art style, 8K --ar 1:1', '仙侠浮空山峰云海之上手绘线稿，锯齿状岩层以粗墨线和精细崖壁纹理线表现，古庙依附山腰以微小建筑细节描绘，旋转云纹以柔和圆形灰调笔触渲染，圣光穿透以辐射线组表现，空灵仙侠氛围，白纸背景', '/aid/lib/sketch/2026/06/17/仙山云海·线稿.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (268, 'sketch', '仙人御剑·速写', 'hand-drawn sketch of an immortal cultivator figure balanced on a flying sword, flowing robes and long hair streaming backward in dynamic wind-swept ink strokes, the sword as a bold horizontal line with speed streaks, clouds rushing past below in quick gestural marks, motion lines conveying rapid flight, grey wash adding form to the figure and depth to clouds, white paper background, concept art style, 8K --ar 1:1', '修仙者御剑飞行手绘速写，飘动衣袍和长发以动态逆风扫掠墨线向后飞扬，飞剑以粗水平线配速度条纹表现，下方云层以快速笔触掠过，运动线传达高速飞行感，灰调赋予人物形体感并加深云层深度，白纸背景', '/aid/lib/sketch/2026/06/17/仙人御剑·速写.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (269, 'sketch', '仙宫建筑·手绘', 'hand-drawn architectural sketch of a celestial palace floating in the clouds, multi-tiered golden roofs with elaborate flying eaves in precise ornate lines, white jade pillars and railings in clean geometric strokes, floating stone steps leading upward, spiritual energy suggested as swirling particle marks around the structure, majestic divine atmosphere, white paper background, concept art style, 8K --ar 1:1', '云中仙宫建筑手绘线稿，多层金顶配精美飞檐以精准华丽线条表现，白玉柱和栏杆以干净几何笔触勾勒，浮空石阶向上延伸，灵气以建筑周围旋转粒子标记暗示，雄伟神圣氛围，白纸背景', '/aid/lib/sketch/2026/06/17/仙宫建筑·手绘.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (270, 'sketch', '灵兽神兽·白描', 'hand-drawn sketch of a mythical Chinese spirit beast in a majestic pose, dragon-like scaled body with flowing mane captured in sinuous ink lines, intricate scale and claw details in fine delicate strokes, mystical flames or clouds curling around its feet, subtle grey wash for muscle definition and volume, powerful yet elegant presence, white paper background, concept art style, 8K --ar 1:1', '中国神话灵兽威严姿态手绘白描，龙形鳞身配飘逸鬃毛以蜿蜒墨线捕捉，精细鳞片和利爪以细腻笔触表现，足下缭绕仙焰或祥云，淡灰调表现肌肉轮廓和体积感，威猛而优雅的存在，白纸背景', '/aid/lib/sketch/2026/06/17/灵兽神兽·白描.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (271, 'sketch', '法宝武器·手绘', 'hand-drawn sketch of a legendary magical sword floating above an ancient stone pedestal, the blade with intricate engraved runes and patterns in fine line detail, spiritual energy radiating from the weapon in wavy concentric line strokes, glowing gemstone in the pommel indicated by highlight lines, grey wash for metallic shading and stone texture, white paper background, concept art style, 8K --ar 1:1', '传奇魔法宝剑悬浮于古石台上手绘线稿，剑身刻有精细符文和纹样以细线细节表现，灵气以波浪同心线从武器辐射而出，剑首宝石发光以高光线标明，灰调表现金属质感和岩石纹理，白纸背景', '/aid/lib/sketch/2026/06/17/法宝武器·手绘.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (272, 'sketch', '仙瀑飞流·速写', 'hand-drawn sketch of a massive waterfall cascading from a floating immortal mountain, vertical falling water in parallel flowing ink strokes of varying density, mist and spray at the base in soft circular grey wash marks, rainbow light refraction suggested by radiating line groups, ancient pine trees clinging to the cliff edge, magical realm atmosphere, white paper background, concept art style, 8K --ar 1:1', '巨瀑从浮空仙山倾泻而下手绘速写，垂直落水以不同密度的平行流动墨线表现，底部水雾和飞沫以柔和圆形灰调笔触渲染，彩虹折射以辐射线组暗示，崖边古松虬枝，仙境氛围，白纸背景', '/aid/lib/sketch/2026/06/17/仙瀑飞流·速写.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (273, 'sketch', '仙草灵植·线稿', 'hand-drawn botanical sketch of magical spirit plants and herbs, a luminous spiritual ginseng root with humanoid form in delicate line work, glowing spirit flowers with elaborate petal patterns, floating luminescent particles around the plants as tiny circles, roots extending into detailed tendril networks, scientific illustration meets fantasy art, white paper background, concept art style, 8K --ar 1:1', '神奇灵草仙植植物学手绘线稿，发光人形灵参以细腻线条勾勒，发光灵花配精美花瓣纹样，植物周围漂浮发光粒子以小圆圈表现，根系延伸成精细藤蔓网络，科学插画与奇幻艺术结合，白纸背景', '/aid/lib/sketch/2026/06/17/仙草灵植·线稿.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (274, 'sketch', '法阵符箓·白描', 'hand-drawn geometric sketch of a complex magical formation circle, concentric rings with intricate ancient rune characters in precise ink lines, trigram and hexagram symbols in the outer ring, energy flow lines connecting nodes in radiating patterns, subtle grey wash creating a glowing center effect, mystical technical blueprint aesthetic, white paper background, concept art style, 8K --ar 1:1', '复杂魔法阵符箓几何手绘白描，同心环配精细古文符箓以精准墨线表现，外环八卦和六爻符号，能量流线以辐射纹样连接节点，淡灰调营造中央发光效果，神秘术法蓝图美学，白纸背景', '/aid/lib/sketch/2026/06/17/法阵符箓·白描.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (275, 'sketch', '天劫雷云·手绘', 'hand-drawn dramatic sketch of apocalyptic tribulation clouds swirling above a lone peak, dark rolling cloud masses in dense overlapping ink strokes, multiple lightning bolts striking downward in jagged branching lines, a small figure silhouette on the mountain summit for scale, turbulent wind effects in sweeping gestural marks, oppressive yet awe-inspiring atmosphere, white paper background, concept art style, 8K --ar 1:1', '末世天劫雷云在孤峰上空翻涌手绘线稿，暗色翻滚云团以密集叠加墨线表现，多道闪电以锯齿分叉线劈落，山顶一小人形剪影作尺度参照，狂风效果以扫掠笔触表现，压迫而敬畏的氛围，白纸背景', '/aid/lib/sketch/2026/06/17/天劫雷云·手绘.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (276, 'sketch', '魔域虚空·速写', 'hand-drawn dark fantasy sketch of a void realm with floating shattered landmasses, jagged obsidian rock formations in bold angular ink strokes, purple and dark energy rifts as torn paper-like gashes in the darkness, skeletal dead trees clinging to the floating rocks, chains descending from unseen heights into the abyss, eerie oppressive atmosphere, white paper background, concept art style, 8K --ar 1:1', '暗黑魔域虚空漂浮碎陆手绘速写，锯齿状黑曜石岩层以粗角状墨线表现，暗紫能量裂隙如撕裂纸痕在黑暗中，枯骨死树附着浮石上，锁链自不可见高度垂入深渊，诡异压迫氛围，白纸背景', '/aid/lib/sketch/2026/06/17/魔域虚空·速写.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (277, 'reference_character', '日系帅气学长·2D·校园', '2D anime style character design, a handsome male high school student, sharp jawline with gentle brown eyes, slightly messy dark brown hair with side-swept bangs, tall lean build, wearing a crisp white shirt with rolled-up sleeves and black school trousers, one hand in pocket casual pose, warm golden hour backlight, soft cel-shaded coloring with crisp ink outlines, anime key visual quality, white background, 8K --ar 1:1', '2D动漫风格校园帅气男生，下颌线条分明配温柔棕眼，微乱深棕发偏分刘海，高挑清瘦，白色衬衫卷袖配黑色校裤，单手插兜随性姿态，金色逆光，柔和cel-shaded上色清晰墨线描边', '/aid/lib/character/2026/07/10/日系帅气学长·2D·校园.png', '0', '2026-07-10 13:29:48', '', '2026-07-10 13:29:48', '', NULL);
INSERT INTO `aid_comic_asset` VALUES (278, 'reference_character', '甜美学妹·2D·萌系', '2D anime style character design, a cute female student with large sparkling purple eyes and long twin-tails pink hair with ribbon bows, petite figure, wearing a sailor-style school uniform with pleated skirt, holding a stack of books against her chest, soft blush on cheeks, moe art style with soft shading and delicate linework, pastel color palette, white background, 8K --ar 1:1', '2D动漫萌系甜美女生，大眼闪亮紫色双马尾配蝴蝶结丝带，娇小身材，水手领校服配百褶裙，抱书在胸前，脸颊微红，萌系画风柔和阴影精致线条，粉彩色调', '/aid/lib/character/2026/07/10/甜美学妹·2D·萌系.png', '0', '2026-07-10 13:29:48', '', '2026-07-10 13:29:48', '', NULL);
INSERT INTO `aid_comic_asset` VALUES (279, 'reference_character', '高冷女教师·2D·御姐', '2D anime style character design, a cool mature woman teacher, sharp narrow red eyes behind thin-rimmed glasses, long straight black hair tied in a low sleek ponytail, tall elegant figure, wearing a form-fitting charcoal grey business suit with pencil skirt, holding a textbook under one arm, cold intimidating aura, semi-realistic anime shading with bold lines, white background, 8K --ar 1:1', '2D动漫御姐风高冷女教师，锐利红眸配细框眼镜，黑色直长发低马尾，高挑优雅，深灰修身西装套裙，臂下夹教科书，冰冷慑人气场，半写实动漫阴影粗线风格', '/aid/lib/character/2026/07/10/高冷女教师·2D·御姐.png', '0', '2026-07-10 13:29:48', '', '2026-07-10 13:29:48', '', NULL);
INSERT INTO `aid_comic_asset` VALUES (280, 'reference_character', '热血少年·2D·少年漫', '2D anime style character design, a passionate young male fighter, spiky bright red hair shooting upward, intense determined green eyes, athletic muscular build, wearing a sleeveless hoodie and baggy cargo pants, fists clenched in a fighting-ready pose, dynamic speed lines radiating from the body, classic shounen manga style with bold ink lines and vibrant flat colors, white background, 8K --ar 1:1', '2D少年漫风格热血少年战士，冲天刺猬亮红发，坚定绿眸，运动员肌肉身材，无袖连帽衫配宽松工装裤，双拳紧握备战姿态，身体周围动态速度线辐射，经典少年漫粗墨线鲜艳平涂', '/aid/lib/character/2026/07/10/热血少年·2D·少年漫.png', '0', '2026-07-10 13:29:48', '', '2026-07-10 13:29:48', '', NULL);
INSERT INTO `aid_comic_asset` VALUES (281, 'reference_character', '温柔大姐姐·2D·治愈系', '2D anime style character design, a gentle warm-hearted young woman with soft amber eyes and a kind smile, long wavy light brown hair cascading past shoulders, soft curvy figure, wearing a cozy oversized cream knit sweater, hands clasped gently in front, warm healing aura with soft glowing light particles around her, iyashikei art style with watercolor-soft shading, white background, 8K --ar 1:1', '2D治愈系动漫温柔年轻女性，柔和琥珀色眼眸亲切微笑，长卷浅棕发垂过肩，柔软曲线身材，奶油色宽松大针织衫，双手轻握身前，温暖治愈光环柔和光粒围绕，水彩般柔和的治愈系画风', '/aid/lib/character/2026/07/10/温柔大姐姐·2D·治愈系.png', '0', '2026-07-10 13:29:48', '', '2026-07-10 13:29:48', '', NULL);
INSERT INTO `aid_comic_asset` VALUES (282, 'reference_character', '冷酷杀手·2D·暗黑系', '2D anime style character design, a cold-blooded assassin, pale skin with one visible piercing ice-blue eye hidden under swept silver-white hair, the other eye covered by an eyepatch, lean muscular build, wearing a high-collared black leather coat with silver buckles, holding a sleek pistol at the side, dark gritty seinen manga style with heavy black shadows and stark contrast, white background, 8K --ar 1:1', '2D暗黑青年漫风格冷血杀手，苍白皮肤一只冰蓝眼眸可见隐于银白扫掠发下另一眼戴眼罩，精瘦肌肉身材，黑色高领皮大衣配银扣，手持手枪垂于身侧，暗黑粗粝青年漫风格重黑影强烈对比', '/aid/lib/character/2026/07/10/冷酷杀手·2D·暗黑系.png', '0', '2026-07-10 13:29:48', '', '2026-07-10 13:29:48', '', NULL);
INSERT INTO `aid_comic_asset` VALUES (283, 'reference_character', '元气少女·2D·活力风', '2D anime style character design, a cheerful energetic teenage girl with bright orange twin-tails bouncing upward, large sparkling golden eyes, athletic petite figure mid-jump pose, wearing a colorful track jacket over a crop top and shorts, both arms raised in a victory V-sign, motion lines and star sparkles around her, vibrant pop anime style with bold saturated colors, white background, 8K --ar 1:1', '2D动漫活力风元气少女，亮橘色双马尾向上飞扬，大眼闪亮金色，运动娇小身材跃起姿态，彩色运动夹克内搭短上衣配短裤，双臂高举V字胜利手势，动态线和星星闪光围绕，鲜艳饱和的流行动漫风', '/aid/lib/character/2026/07/10/元气少女·2D·活力风.png', '0', '2026-07-10 13:29:48', '', '2026-07-10 13:29:48', '', NULL);
INSERT INTO `aid_comic_asset` VALUES (284, 'reference_character', '成熟大叔·2D·写实漫', '2D anime style character design, a rugged middle-aged man with a stubbled square jaw and tired wise grey eyes, slicked-back salt-and-pepper hair, broad burly build, wearing a rumpled trench coat over a dark shirt, cigarette tucked behind one ear, one hand holding a coffee cup, world-weary cynical aura, gekiga realistic manga style with fine cross-hatching and muted earth tones, white background, 8K --ar 1:1', '2D剧画写实漫风粗犷中年男子，胡茬方下颌配疲惫睿智灰眼，花白短发向后梳，宽阔魁梧身材，皱巴巴风衣内搭深色衬衫，一支香烟夹在耳后一手端咖啡，饱经沧桑的颓废气场，剧画风格细密交叉线和大地色调', '/aid/lib/character/2026/07/10/成熟大叔·2D·写实漫.png', '0', '2026-07-10 13:29:48', '', '2026-07-10 13:29:48', '', NULL);
INSERT INTO `aid_comic_asset` VALUES (285, 'reference_character', '白发仙尊·2D·古风美型', '2D anime style character design, an ancient immortal cultivator with ethereal beauty, flowing pure white hair reaching the waist with a single jade hairpin, piercing pale golden eyes, tall slender figure, wearing layered white and silver flowing hanfu robes with cloud embroidery, a floating sword beside him, serene transcendent aura, Chinese donghua style with ink-brush textures and watercolor wash, white background, 8K --ar 1:1', '2D国漫风格修仙者空灵之美，纯白长发及腰仅一枚玉簪束发，浅金色眼眸锐利，高挑清瘦，层叠白与银白流云纹汉服宽袍，身旁悬浮宝剑，超然仙气，国漫水墨笔触水彩渲染风格', '/aid/lib/character/2026/07/10/白发仙尊·2D·古风美型.png', '0', '2026-07-10 13:29:48', '', '2026-07-10 13:29:48', '', NULL);
INSERT INTO `aid_comic_asset` VALUES (286, 'reference_character', '黑长直剑仙·2D·唯美', '2D anime style character design, a beautiful female sword immortal, waist-length straight jet-black hair flowing in an unseen wind, cold sharp blue eyes, slender graceful figure, wearing elegant layered blue and white hanfu with billowing sleeves, holding a translucent jade sword in a ready stance, floating cherry blossom petals around her, refined bishoujo anime style with soft gradient shading, white background, 8K --ar 1:1', '2D唯美动漫女剑仙，及腰黑长直发无风自动，冰冷锐利蓝眸，纤秀优雅身材，层叠蓝白汉服广袖飘飞，手持半透明玉剑蓄势待发，樱花花瓣飘绕身周，细腻少女漫风格柔和渐变阴影', '/aid/lib/character/2026/07/10/黑长直剑仙·2D·唯美.png', '0', '2026-07-10 13:29:48', '', '2026-07-10 13:29:48', '', NULL);
INSERT INTO `aid_comic_asset` VALUES (287, 'reference_character', '邪魅魔君·2D·耽美风', '2D anime style character design, a dangerously charming demon lord, long wild dark purple hair cascading over one shoulder, seductive crimson eyes with slit pupils, pale luminous skin, tall lean figure, wearing an elaborate black and red robe open at the chest revealing dark markings, a wicked smirk, ornate gold crown resting on his brow, BL-style bishounen with sharp angular features and dramatic shading, white background, 8K --ar 1:1', '2D耽美风邪魅魔王，长乱深紫发披散一侧肩头，魅惑猩红竖瞳眼眸，苍白发光肌肤，高挑清瘦，华丽黑红色敞胸袍服露锁骨暗纹，邪笑，华丽金冠戴于眉上，耽美风格俊美少年尖削面庞戏剧性阴影', '/aid/lib/character/2026/07/10/邪魅魔君·2D·耽美风.png', '0', '2026-07-10 13:29:48', '', '2026-07-10 13:29:48', '', NULL);
INSERT INTO `aid_comic_asset` VALUES (288, 'reference_character', '红妆侠女·2D·飒爽', '2D anime style character design, a fierce swordswoman in red martial arts attire, high ponytail of black hair tied with flowing red ribbons, sharp determined eyes, athletic lithe figure in a dynamic combat pose, red and gold fitted hanfu with tight sleeves and a red sash, a flexible sword coiled at her waist, wind whipping her hair and clothes, action-oriented anime style with motion effects, white background, 8K --ar 1:1', '2D动漫飒爽红衣女侠，黑发高马尾系飘飞红丝带，锐利坚定眼眸，运动员般柔韧身材动态格斗姿势，红金配色修身汉服窄袖配红腰带，腰间缠绕软剑，风卷发衣飘动，动作动漫风格动态特效', '/aid/lib/character/2026/07/10/红妆侠女·2D·飒爽.png', '0', '2026-07-10 13:29:48', '', '2026-07-10 13:29:48', '', NULL);
INSERT INTO `aid_comic_asset` VALUES (289, 'reference_character', '正太狐妖·2D·可爱', '2D anime style character design, an adorable young fox spirit boy, fluffy fox ears poking from messy silver-white hair, a large fluffy tail curling behind him, big innocent golden eyes, small cute build, wearing a festive orange and white kimono-style robe with bell accessories, holding a glowing spirit orb in both hands, mischievous playful smile, chibi-adjacent cute anime style with soft rounded shapes, white background, 8K --ar 1:1', '2D可爱风少年狐妖，毛茸茸狐耳从凌乱银白短发中探出，蓬松大尾巴卷在身后，天真金色大眼，小巧可爱身材，橘白相间和风袍服配铃铛饰物，双手捧发光灵球，调皮顽皮笑容，Q版软萌风格柔和圆润造型', '/aid/lib/character/2026/07/10/正太狐妖·2D·可爱.png', '0', '2026-07-10 13:29:48', '', '2026-07-10 13:29:48', '', NULL);
INSERT INTO `aid_comic_asset` VALUES (290, 'reference_character', '女王帝君·2D·华丽', '2D anime style character design, a regal empress with commanding presence, elaborate updo hairstyle with a phoenix crown of gold hairpins and dangling jewels, sharp phoenix eyes with winged eyeliner in crimson, tall statuesque figure, wearing an opulent red and gold imperial court gown with phoenix embroidery and a dramatic long train, holding an ornate jade scepter, luxurious CLAMP-style shoujo art with intricate detail, white background, 8K --ar 1:1', '2D华丽少女漫风霸气女帝，繁复发髻凤凰金冠金钗垂珠，锐利丹凤眼绯红飞翘眼线，高挑威严身材，华美红金宫廷凤袍长拖尾，手持精美玉笏，CLAMP风华丽少女漫精细繁复细节', '/aid/lib/character/2026/07/10/女王帝君·2D·华丽.png', '0', '2026-07-10 13:29:48', '', '2026-07-10 13:29:48', '', NULL);
INSERT INTO `aid_comic_asset` VALUES (291, 'reference_character', '双子剑客·2D·少年漫', '2D anime style character design, twin young swordsmen standing back-to-back, one with short white hair and blue eyes the other with short black hair and red eyes, identical lean athletic builds, both wearing coordinated blue and black martial arts uniforms, each holding an identical sword in a mirrored pose, complementary yin-yang color scheme, dynamic twin energy, shounen anime style with clean lines and energetic composition, white background, 8K --ar 1:1', '2D少年漫风双子剑客背对背而立，一白短发明亮蓝眼一黑短发锐利红眼，同等精瘦运动身材，同款蓝黑配色武服，各持相同长剑成镜像姿态，互补阴阳配色，双子动态能量，少年漫清爽线条动感构图', '/aid/lib/character/2026/07/10/双子剑客·2D·少年漫.png', '0', '2026-07-10 13:29:48', '', '2026-07-10 13:29:48', '', NULL);
INSERT INTO `aid_comic_asset` VALUES (292, 'reference_character', '校园少女·3D·Cel-Shading', '3D anime cel-shaded character render, a cheerful high school girl with shoulder-length brown hair in soft layers, large expressive green eyes, slim build, wearing a classic Japanese school uniform with sailor collar and ribbon, standing in a casual relaxed pose, toon-shaded rendering with crisp shadow edges and flat color passes, Genshin Impact style 3D anime aesthetic, white background, 8K --ar 1:1', '3D动漫cel-shading渲染高中女生，及肩棕发柔顺层次，大而有表现力的绿眸，苗条身材，经典水手领日式校服配丝带蝴蝶结，随意放松站姿，卡通渲染清晰阴影边缘平面色块，原神风3D动漫美学', '/aid/lib/character/2026/07/10/校园少女·3D·Cel-Shading.png', '0', '2026-07-10 13:29:48', '', '2026-07-10 13:29:48', '', NULL);
INSERT INTO `aid_comic_asset` VALUES (293, 'reference_character', '都市青年·3D·PBR', '3D anime-style character render with PBR materials, a stylish young man in his twenties, short well-groomed black hair with a modern undercut, sharp intelligent eyes, athletic slim build, wearing a designer bomber jacket over a graphic tee and slim-fit jeans, urban streetwear aesthetic, semi-realistic 3D anime with physically-based fabric and skin rendering, Arcane-inspired art style, white background, 8K --ar 1:1', '3D动漫PBR材质渲染时尚青年，整齐短黑发现代undercut发型，锐利聪慧眼眸，运动精瘦身材，设计师款飞行员夹克内搭印花T恤配修身牛仔裤，都市街头风，半写实3D动漫PBR布料与皮肤渲染，Arcane灵感风格', '/aid/lib/character/2026/07/10/都市青年·3D·PBR.png', '0', '2026-07-10 13:29:48', '', '2026-07-10 13:29:48', '', NULL);
INSERT INTO `aid_comic_asset` VALUES (294, 'reference_character', '运动少年·3D·三渲二', '3D anime NPR character render, a sporty teenage boy with short spiky navy-blue hair, bright determined orange eyes, toned athletic build in a dynamic sprinting pose, wearing a white and blue basketball jersey with number 7, non-photorealistic rendering with anime-style outlines and flat shading, Honkai Star Rail 3D anime aesthetic, white background, 8K --ar 1:1', '3D动漫NPR三渲二运动少年，海军蓝短发根根竖起，明亮坚定橙眸，精壮运动身材冲刺姿态，蓝白7号篮球背心，非真实感渲染动漫风描边平面阴影，崩坏星穹铁道3D动漫美学', '/aid/lib/character/2026/07/10/运动少年·3D·三渲二.png', '0', '2026-07-10 13:29:48', '', '2026-07-10 13:29:48', '', NULL);
INSERT INTO `aid_comic_asset` VALUES (295, 'reference_character', '黑帮大哥·3D·写实卡通', '3D stylized realistic character render, a muscular middle-aged gangster with a shaved head, a deep scar across one eye, thick gold chain around his neck, broad imposing build, wearing a black suit with the jacket open and a white shirt straining at the buttons, arms crossed in an intimidating pose, stylized realism with exaggerated proportions, ZBrush character concept aesthetic, white background, 8K --ar 1:1', '3D风格化写实渲染光头中年黑帮大哥，一眼深疤，粗金链挂颈，宽厚威猛身材，黑西装敞开白衬衫紧绷扣子，双臂交叉威慑姿态，夸张比例的风格化写实，ZBrush角色概念美学', '/aid/lib/character/2026/07/10/黑帮大哥·3D·写实卡通.png', '0', '2026-07-10 13:29:48', '', '2026-07-10 13:29:48', '', NULL);
INSERT INTO `aid_comic_asset` VALUES (296, 'reference_character', '邻家女孩·3D·迪士尼', '3D Disney-inspired character render, a sweet freckled young woman with big curious brown eyes and a warm smile, curly auburn hair tied in a loose side braid, soft rounded figure, wearing a simple floral sundress, holding a small potted plant, gentle approachable charm, Pixar-Disney 3D animation style with smooth subsurface scattering and stylized proportions, white background, 8K --ar 1:1', '3D迪士尼风甜蜜雀斑年轻女子，好奇棕大眼温暖微笑，红褐色卷发松编侧辫，柔和圆润身材，简约碎花太阳裙，手捧小盆栽，温柔亲切魅力，皮克斯迪士尼3D动画风柔和次表面散射风格化比例', '/aid/lib/character/2026/07/10/邻家女孩·3D·迪士尼.png', '0', '2026-07-10 13:29:48', '', '2026-07-10 13:29:48', '', NULL);
INSERT INTO `aid_comic_asset` VALUES (297, 'reference_character', '特工大叔·3D·半写实', '3D semi-realistic character render, a grizzled middle-aged secret agent with a weathered face and sharp grey eyes, short salt-and-pepper hair, sturdy muscular build, wearing a tactical black turtleneck and shoulder holster, one hand adjusting an earpiece, focused intense expression, cinematic stylized realism with detailed skin textures, Metal Gear Solid-inspired art direction, white background, 8K --ar 1:1', '3D半写实中年特工大叔，饱经风霜面孔锐利灰眼，花白短发，敦实肌肉身材，黑色战术高领毛衣配肩部枪套，一手调整耳麦，专注紧张表情，电影化风格写实精细皮肤纹理，合金装备风', '/aid/lib/character/2026/07/10/特工大叔·3D·半写实.png', '0', '2026-07-10 13:29:48', '', '2026-07-10 13:29:48', '', NULL);
INSERT INTO `aid_comic_asset` VALUES (298, 'reference_character', '偶像少女·3D·韩系卡通', '3D Korean-style character render, a glamorous young female idol with long wavy honey-blonde hair, starry blue eyes with glittery makeup, slim tall figure, wearing a sparkling stage costume with a sequin mini dress and platform heels, posing with a heart hand gesture, glossy skin rendering with rim lights, Korean webtoon 3D aesthetic, white background, 8K --ar 1:1', '3D韩系风格年轻偶像少女，金色长卷发闪亮妆容星眸蓝眼，纤细高挑，闪烁亮片舞台迷你裙配高跟靴，双手比心手势，光泽皮肤渲染加轮廓光，韩国网漫3D美学', '/aid/lib/character/2026/07/10/偶像少女·3D·韩系卡通.png', '0', '2026-07-10 13:29:48', '', '2026-07-10 13:29:48', '', NULL);
INSERT INTO `aid_comic_asset` VALUES (299, 'reference_character', '街头少年·3D·美式卡通', '3D American cartoon-style character render, a lanky teenage boy with wild messy orange hair, freckles and a mischievous grin, exaggerated thin build, wearing an oversized graffiti-print hoodie and ripped jeans, one hand spinning a basketball on his finger, dynamic energetic pose, stylized Western animation 3D with bold shapes and saturated colors, Into the Spider-Verse inspired, white background, 8K --ar 1:1', '3D美式卡通风街头少年，杂乱橘发雀斑顽皮咧嘴笑，夸张瘦长身材，大号涂鸦印花连帽衫配破洞牛仔裤，单手转篮球手指尖，活力动态姿态，风格化西方3D动画大胆形状高饱和色彩，蜘蛛侠平行宇宙风', '/aid/lib/character/2026/07/10/街头少年·3D·美式卡通.png', '0', '2026-07-10 13:29:48', '', '2026-07-10 13:29:48', '', NULL);
INSERT INTO `aid_comic_asset` VALUES (300, 'reference_character', '仙侠女侠·3D·国风卡通', '3D Chinese aesthetic cartoon character render, a graceful xianxia heroine with flowing ink-black hair in an ancient updo with a jade hairpin, luminous phoenix eyes, slender elegant build, wearing flowing layered aqua and white hanfu with billowing sleeves and a jade pendant, floating mid-air with spiritual energy swirls, Chinese donghua 3D style with ink-painting textures, white background, 8K --ar 1:1', '3D国风卡通仙侠女主角，墨黑长发古风发髻配玉簪，明亮凤眼，纤秀优雅身材，层叠浅绿与白色汉服广袖飘飞腰坠玉佩，悬浮空中灵气漩涡环绕，国漫3D水墨纹理风格', '/aid/lib/character/2026/07/10/仙侠女侠·3D·国风卡通.png', '0', '2026-07-10 13:29:48', '', '2026-07-10 13:29:48', '', NULL);
INSERT INTO `aid_comic_asset` VALUES (301, 'reference_character', '上古神兽·3D·Q版', '3D chibi character render, an adorable Q-version mythical Chinese dragon spirit, oversized round head with tiny horns and big sparkly eyes, small rounded chubby body with tiny wings, scales rendered in soft pearlescent jade green, sitting cutely with tail wrapped around, floating on a small cloud puff, super-deformed cute 3D style with soft clay-like textures, white background, 8K --ar 1:1', '3D Q版中国龙形神兽，超大圆头小角大闪亮眼，小小圆胖身体配迷你翅膀，鳞片呈柔和珠光玉绿色，可爱坐姿尾巴缠绕，坐于小云朵上，超Q可爱3D风柔和黏土质感', '/aid/lib/character/2026/07/10/上古神兽·3D·Q版.png', '0', '2026-07-10 13:29:48', '', '2026-07-10 13:29:48', '', NULL);
INSERT INTO `aid_comic_asset` VALUES (302, 'reference_character', '王朝将军·3D·三渲二', '3D anime NPR character render, a proud ancient Chinese general with a stern handsome face and a small beard, long black hair tied in a warrior topknot, broad armored build, wearing elaborate gold and red ancient Chinese armor with a flowing crimson cape, a massive guandao polearm held at his side, non-photorealistic cel-shaded 3D with bold outlines, Dynasty Warriors-inspired aesthetic, white background, 8K --ar 1:1', '3D动漫NPR渲染中国古代将军，威严英俊面孔配短髭，黑长发束武士髻，宽厚铠甲身材，华丽金红中国古铠甲配飘舞深红披风，身旁拄青龙偃月刀，非真实感卡通渲染加粗描边，真三国无双风', '/aid/lib/character/2026/07/10/王朝将军·3D·三渲二.png', '0', '2026-07-10 13:29:48', '', '2026-07-10 13:29:48', '', NULL);
INSERT INTO `aid_comic_asset` VALUES (303, 'reference_character', '灵族精灵·3D·梦幻', '3D fantasy character render, an ethereal nature spirit with luminous pale lavender skin, long flowing translucent pastel rainbow hair, pointed elf-like ears, delicate slender build, wearing a dress made of living flower petals and glowing vines, butterfly-like translucent wings behind her, floating in a graceful pose, dreamy magical 3D style with particle effects and soft bloom lighting, white background, 8K --ar 1:1', '3D奇幻自然精灵，淡紫发光肌肤，长飘半透明彩虹色秀发，精灵尖耳，纤秀精致身材，活花瓣与发光藤蔓编织的裙装，身后蝴蝶般半透明翅膀，优雅漂浮姿态，梦幻魔法3D粒子特效柔光渲染', '/aid/lib/character/2026/07/10/灵族精灵·3D·梦幻.png', '0', '2026-07-10 13:29:48', '', '2026-07-10 13:29:48', '', NULL);
INSERT INTO `aid_comic_asset` VALUES (304, 'reference_character', '天界神女·3D·半写实', '3D semi-realistic divine character render, a celestial goddess with flawless luminous skin, long flowing platinum-silver hair that seems to float in zero gravity, piercing heavenly golden eyes, graceful statuesque figure, wearing flowing ethereal white and gold silk robes that defy gravity, a glowing divine halo behind her head, serene omniscient expression, Final Fantasy cinematic 3D aesthetic, white background, 8K --ar 1:1', '3D半写实天界女神，无瑕发光肌肤，长飘铂金银发如零重力漂浮，锐利天堂金色眼眸，优雅庄严身材，飘动空灵白金丝绸长袍无视重力，脑后神圣光环，宁静全知表情，最终幻想电影级3D美学', '/aid/lib/character/2026/07/10/天界神女·3D·半写实.png', '0', '2026-07-10 13:29:48', '', '2026-07-10 13:29:48', '', NULL);
INSERT INTO `aid_comic_asset` VALUES (305, 'reference_character', '冥界死神·3D·暗黑卡通', '3D dark fantasy character render, a menacing skeletal reaper figure shrouded in tattered black robes, a bleached animal skull mask with glowing purple eye sockets, bony hands gripping an ornate obsidian scythe, wisps of dark purple smoke curling around the figure, eerie floating pose, stylized gothic 3D with sharp angular designs, Dark Souls boss aesthetic but stylized, white background, 8K --ar 1:1', '3D暗黑奇幻骷髅死神，破旧黑袍包裹，漂白骨制动物头骨面具紫光眼洞，骨爪握住华丽黑曜石镰刀，暗紫烟雾缭绕身周，诡异悬浮姿态，哥特风3D锐利棱角设计，黑魂Boss美学风格化', '/aid/lib/character/2026/07/10/冥界死神·3D·暗黑卡通.png', '0', '2026-07-10 13:29:48', '', '2026-07-10 13:29:48', '', NULL);
INSERT INTO `aid_comic_asset` VALUES (306, 'reference_character', '仙童道童·3D·黏土风', '3D clay-style character render, an adorable young Taoist apprentice child with a round face and rosy cheeks, hair in two small topknot buns, small chubby build, wearing an oversized blue Taoist robe with sleeves too long, holding a wooden training sword bigger than himself, innocent curious expression, stop-motion claymation 3D aesthetic with texture details and soft matte finish, white background, 8K --ar 1:1', '3D黏土风格仙童小道童，圆脸红颊，两个小丸子头，小小胖墩身材，过大的蓝色道袍袖子太长，手持比自己还大的木剑，天真好奇表情，定格动画黏土3D质感细节柔和哑光表面', '/aid/lib/character/2026/07/10/仙童道童·3D·黏土风.png', '0', '2026-07-10 13:29:48', '', '2026-07-10 13:29:48', '', NULL);

-- ----------------------------
-- Table structure for aid_comic_audit_record
-- ----------------------------
DROP TABLE IF EXISTS `aid_comic_audit_record`;
CREATE TABLE `aid_comic_audit_record`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `target_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '审核对象类型(project项目 episode剧集)',
  `target_id` bigint(20) NOT NULL COMMENT '审核对象ID(项目ID或剧集ID)',
  `owner_user_id` bigint(20) NULL DEFAULT NULL COMMENT '作品所属用户ID',
  `action` tinyint(4) NOT NULL COMMENT '审核动作(1提交审核 2审核通过 3审核驳回)',
  `before_status` tinyint(4) NULL DEFAULT NULL COMMENT '变更前状态',
  `after_status` tinyint(4) NULL DEFAULT NULL COMMENT '变更后状态',
  `audit_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核意见/驳回原因',
  `operator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人(C端为用户标识, 后台为管理员账号)',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志(0存在 1删除)',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_target`(`target_type`, `target_id`) USING BTREE,
  INDEX `idx_owner`(`owner_user_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '作品审核记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aid_comic_audit_record
-- ----------------------------

-- ----------------------------
-- Table structure for aid_comic_episode
-- ----------------------------
DROP TABLE IF EXISTS `aid_comic_episode`;
CREATE TABLE `aid_comic_episode`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `project_id` bigint(20) NOT NULL COMMENT '所属项目ID',
  `episode_no` bigint(11) NOT NULL COMMENT '第几集',
  `user_id` bigint(11) NULL DEFAULT NULL COMMENT '用户ID',
  `comic_title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单集标题',
  `pending_comic_title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '待审核单集标题',
  `comic_desc` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单集描述',
  `pending_comic_desc` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '待审核单集描述',
  `comic_cover_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单集封面图',
  `pending_comic_cover_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '待审核单集封面',
  `gen_mode` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '生成模式(economy, performance)',
  `creation_mode` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创作模式(i2v, multi)',
  `current_step` tinyint(4) NOT NULL DEFAULT 1 COMMENT '当前步骤(1项目配置 2剧本创作 3素材准备 4分镜设计 5视频生成 6音画同步 7成品预览)',
  `status` tinyint(4) NULL DEFAULT 0 COMMENT '状态(0草稿 1制作中 2完成未审核 3审核中 4审核通过 5审核失败)',
  `status_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '状态原因',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志',
  `create_time` datetime NULL DEFAULT NULL,
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '',
  `update_time` datetime NULL DEFAULT NULL,
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_project_id`(`project_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '剧集信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aid_comic_episode
-- ----------------------------

-- ----------------------------
-- Table structure for aid_comic_project
-- ----------------------------
DROP TABLE IF EXISTS `aid_comic_project`;
CREATE TABLE `aid_comic_project`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint(20) NOT NULL COMMENT '所属用户ID',
  `project_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '项目名称',
  `pending_project_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '待审核项目名称',
  `project_desc` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '项目描述',
  `pending_project_desc` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '待审核项目描述',
  `project_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '类型: series剧集, movie电影',
  `cover_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '封面图',
  `pending_cover_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '待审核项目封面',
  `aspect_ratio` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '画面比例(16:9, 9:16等)',
  `script_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '剧本类型(剧情演绎, 真人解说)',
  `video_style_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '视频风格来源',
  `video_style_value` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '视频风格值',
  `default_gen_mode` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '默认生成模式(economy经济, performance性能)',
  `default_creation_mode` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '默认创作模式(i2v图生视频, multi多参生视频)',
  `current_step` tinyint(4) NOT NULL DEFAULT -1 COMMENT '当前步骤(1项目配置 2剧本创作 3素材准备 4分镜设计 5视频生成 6音画同步 7成品预览, 剧集固定-1)',
  `status` tinyint(4) NULL DEFAULT 0 COMMENT '状态(0草稿 1制作中  2完成未提交 3审核中 4审核通过 5审核失败)',
  `status_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '状态原因',
  `is_public` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '是否公开',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志（0代表存在 1代表删除）',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `publish_time` datetime NULL DEFAULT NULL COMMENT '最近一次公开发布时间（关闭公开不清空，重新发布覆盖）',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '漫剧项目主表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aid_comic_project
-- ----------------------------

-- ----------------------------
-- Table structure for aid_comic_script
-- ----------------------------
DROP TABLE IF EXISTS `aid_comic_script`;
CREATE TABLE `aid_comic_script`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `project_id` bigint(20) NOT NULL,
  `episode_id` bigint(20) NULL DEFAULT 0 COMMENT '集数ID(电影为0)',
  `user_id` bigint(11) NULL DEFAULT NULL COMMENT '用户ID',
  `original_text` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '用户上传的原版剧本',
  `simplified_text` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT 'AI简化版剧本(保留人物性格等信息用于提取)',
  `is_extracted` tinyint(4) NULL DEFAULT 0 COMMENT '是否已执行资产提取(0否 1是)',
  `comic_version` int(4) NULL DEFAULT 1 COMMENT '剧集版本',
  `status` tinyint(4) NULL DEFAULT 0 COMMENT '状态(0草稿 1使用 2历史版本)',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0',
  `create_time` datetime NULL DEFAULT NULL,
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '',
  `update_time` datetime NULL DEFAULT NULL,
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '剧本原文与简化版表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aid_comic_script
-- ----------------------------

-- ----------------------------
-- Table structure for aid_config
-- ----------------------------
DROP TABLE IF EXISTS `aid_config`;
CREATE TABLE `aid_config`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `category` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '配置类型',
  `config_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '配置名称',
  `config_value` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '配置值',
  `config_dict` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '说明',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志（0代表存在 1代表删除）',
  `order_num` int(3) NULL DEFAULT NULL COMMENT '排序（越小排在前面）',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `version` int(11) NULL DEFAULT NULL COMMENT '版本',
  `update_ip` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新IP',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户Id',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `unique_category_key`(`category`, `config_name`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 399 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '配置信息表' ROW_FORMAT = Dynamic;

