INSERT INTO `aid_config` VALUES (374, 'wxLogin', 'wxLoginSubscribeReply', '🎉 欢迎关注视觉AID！\n【AID  开源的 AI 漫画与视频创作平台】小说一键成片，从此人人都是导演\n\n✨ 你可以用 AID 做什么：\n📖 导入小说/脚本，AI 自动拆解剧情、生成分镜\n🎨 角色/道具/场景一致性生图，多厂商模型任选\n🎬 分镜图一键生成视频，自动配音、对口型\n🧩 全流程可视化编辑，支持导出成片\n\n💎 我们是完全开源的程序，代码透明、可自行部署：\n开源仓库：gitee.com/gzxx-2025/aid-server\n官网直达：\n\n无论你是网文作者、漫画爱好者，还是想把故事变成视频的创作者，欢迎多用、多吐槽，你的反馈会让 AID 持续进化！\n\n✨ 视觉AID，让每个故事都被看见 ✨', '关注后自动回复内容', '0', 6, '2026-07-22 00:09:56', 'admin', 'admin', '2026-07-22 01:38:11', '用户关注公众号后自动回复的文本内容，留空不回复', NULL, NULL, 0);
