-- ----------------------------
-- Table structure for aid_episode_editor
-- ----------------------------
DROP TABLE IF EXISTS `aid_episode_editor`;
CREATE TABLE `aid_episode_editor`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `project_id` bigint(20) NOT NULL COMMENT '所属项目ID (关联 aid_comic_project.id)',
  `episode_id` bigint(20) NOT NULL COMMENT '所属剧集ID (关联 aid_comic_episode.id)',
  `user_id` bigint(20) NOT NULL COMMENT '最后修改该记录的用户ID',
  `timeline_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '剪辑器工程配置JSON(轨道/素材/特效等)',
  `final_video_url` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '成片OSS地址(导出成功后回填)',
  `pending_video_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '待审核成片地址(过审后转正到final_video_url)',
  `cover_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '最新成片的预览封面图OSS地址',
  `export_status` tinyint(4) NOT NULL DEFAULT 0 COMMENT '导出状态(0未导出 1合成中 2成功 3失败)',
  `export_progress` tinyint(4) NULL DEFAULT 0 COMMENT '导出进度百分比(0-100)',
  `export_task_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '导出任务ID(防重复合成)',
  `error_msg` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '导出失败原因',
  `export_fingerprint` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '最近一次导出的素材指纹(SHA-256)，同素材重复导出直接复用成片',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志 (0正常 1删除)',
  `create_time` datetime NULL DEFAULT NULL COMMENT '首次进入编辑器初始化的时间',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '最后一次保存草稿或状态变更的时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_project_episode`(`project_id`, `episode_id`) USING BTREE COMMENT '强约束：同一项目的同一剧集(电影为episode_id=0)只有一条剪辑记录'
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '剧集剪辑' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aid_episode_editor
-- ----------------------------

-- ----------------------------
-- Table structure for aid_error_log
-- ----------------------------
DROP TABLE IF EXISTS `aid_error_log`;
CREATE TABLE `aid_error_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键 ID',
  `task_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '关联任务 ID',
  `provider_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '厂商编码',
  `model_code` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '模型编码',
  `http_status` int(11) NULL DEFAULT NULL COMMENT 'HTTP 状态码',
  `raw_message` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '上游原始错误体（截断 2KB）',
  `matched_rule_id` bigint(20) NULL DEFAULT NULL COMMENT '命中规则 ID（NULL 表示未识别）',
  `matched_error_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '最终归一化的错误码',
  `occurrence_count` int(11) NULL DEFAULT 1 COMMENT '相同 hash 累计次数',
  `sample_hash` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'raw_message 归一化 MD5',
  `first_seen` datetime NULL DEFAULT NULL COMMENT '首次出现时间',
  `last_seen` datetime NULL DEFAULT NULL COMMENT '最近出现时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_provider_hash`(`provider_code`, `sample_hash`) USING BTREE,
  INDEX `idx_unmatched`(`matched_rule_id`, `last_seen`) USING BTREE,
  INDEX `idx_last_seen`(`last_seen`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '错误日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aid_error_log
-- ----------------------------

-- ----------------------------
-- Table structure for aid_extract_task
-- ----------------------------
DROP TABLE IF EXISTS `aid_extract_task`;
CREATE TABLE `aid_extract_task`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `project_id` bigint(20) NOT NULL COMMENT '项目ID',
  `episode_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '剧集ID(电影为0)',
  `user_id` bigint(20) NOT NULL COMMENT '用户ID',
  `task_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'asset_extract' COMMENT '任务类型',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'PENDING' COMMENT '状态: PENDING/PROCESSING/SUCCEEDED/FAILED',
  `input_snapshot` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '输入快照JSON',
  `result_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '结果数据JSON',
  `error_message` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '错误信息',
  `total_count` int(11) NULL DEFAULT 0 COMMENT '提取资产总数',
  `model_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'AI模型名称（必填，需在aid_ai_model中存在）',
  `model_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'AI模型编码（必填，对应aid_ai_model.model_code）',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志(0存在 1删除)',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `billing_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'INIT' COMMENT '计费状态: INIT/FROZEN/SUCCESS/FAILED',
  `frozen_amount` decimal(10, 2) NULL DEFAULT NULL COMMENT '预冻结金额（元）',
  `billing_trace_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '计费追踪ID（幂等）',
  `billing_snapshot_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '计费快照JSON（SKU定价+token估值，用于差额结算）',
  `actual_cost` decimal(12, 6) NULL DEFAULT NULL COMMENT '实际扣费金额（结算后更新）',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_project_user`(`project_id`, `user_id`) USING BTREE,
  INDEX `idx_reclaim_scan`(`del_flag`, `status`, `task_type`) USING BTREE,
  INDEX `idx_create_model`(`create_time`, `model_code`) USING BTREE,
  INDEX `idx_billing_scan`(`billing_status`, `update_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '资产提取任务表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aid_extract_task
-- ----------------------------

-- ----------------------------
-- Table structure for aid_extract_task_billing_snapshot
-- ----------------------------
DROP TABLE IF EXISTS `aid_extract_task_billing_snapshot`;
CREATE TABLE `aid_extract_task_billing_snapshot`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `task_id` bigint(20) NOT NULL COMMENT '提取任务ID',
  `project_id` bigint(20) NULL DEFAULT NULL COMMENT '项目ID',
  `episode_id` bigint(20) NULL DEFAULT 0 COMMENT '剧集ID',
  `user_id` bigint(20) NOT NULL COMMENT '用户ID',
  `task_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '任务类型',
  `snapshot_stage` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '快照阶段：FROZEN/SETTLED',
  `snapshot_json` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '计费快照JSON',
  `snapshot_size` int(11) NULL DEFAULT NULL COMMENT '快照字符长度',
  `snapshot_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '快照SHA256',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '删除标志（0存在 1删除）',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_task_stage`(`task_id`, `snapshot_stage`) USING BTREE,
  INDEX `idx_task_id`(`task_id`) USING BTREE,
  INDEX `idx_user_project`(`user_id`, `project_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '提取任务计费快照表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aid_extract_task_billing_snapshot
-- ----------------------------

-- ----------------------------
-- Table structure for aid_faq
-- ----------------------------
DROP TABLE IF EXISTS `aid_faq`;
CREATE TABLE `aid_faq`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '问题标题',
  `category` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '分类（如：账号、充值、生成、其他）',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '问题完整内容（答案明细，富文本/长文本）',
  `sort_order` int(11) NOT NULL DEFAULT 0 COMMENT '排序（值越小越靠前）',
  `view_count` bigint(20) NOT NULL DEFAULT 0 COMMENT '浏览次数',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '状态（0显示 1隐藏）',
  `publish_time` datetime NULL DEFAULT NULL COMMENT '发布时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '删除标志（0存在 1删除）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_status_sort`(`status`, `sort_order`) USING BTREE,
  INDEX `idx_category`(`category`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '常见问题' ROW_FORMAT = Dynamic;

