-- ----------------------------
-- Table structure for aid_gen_record
-- ----------------------------
DROP TABLE IF EXISTS `aid_gen_record`;
CREATE TABLE `aid_gen_record`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) NOT NULL,
  `project_id` bigint(20) NULL DEFAULT NULL COMMENT '项目ID(冗余)',
  `episode_id` bigint(20) NULL DEFAULT NULL COMMENT '剧集ID(电影为0, 冗余)',
  `storyboard_id` bigint(20) NOT NULL,
  `gen_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '生成类型(image单图 grid宫格 i2v图生 multi多参 edge首尾 upload_video上传 compose合成)',
  `file_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '生成的URL',
  `task_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '大模型异步任务ID(用于回调接口匹配)',
  `status` tinyint(4) NULL DEFAULT 0 COMMENT '生成状态(0处理中, 1成功, 2失败)',
  `gen_params` json NULL COMMENT '生成参数JSON(无参场景为空)',
  `biz_seq` bigint(20) NULL DEFAULT NULL COMMENT '业务序号(父任务ID*1000000+槽位, 分镜出图/出片幂等键)',
  `prompt_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '最终生成提示词',
  `model_id` bigint(20) NULL DEFAULT NULL COMMENT '关联的aid_ai_model（用户上传等无模型场景为空）',
  `user_input_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '用户自己输入的补充文本',
  `base_image_id` bigint(20) NULL DEFAULT NULL COMMENT '图生视频依赖的底图',
  `first_image_id` bigint(20) NULL DEFAULT NULL COMMENT '首尾帧视频依赖的首图',
  `last_image_id` bigint(20) NULL DEFAULT NULL COMMENT '首尾帧视频依赖的尾图',
  `video_duration` int(11) NULL DEFAULT NULL COMMENT '视频时长',
  `sound_desc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '音效描述',
  `cost_credits` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '消耗积分',
  `is_selected` tinyint(4) NULL DEFAULT 0 COMMENT '是否被选为最终分镜(0否 1是)',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0',
  `create_time` datetime NULL DEFAULT NULL,
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '',
  `update_time` datetime NULL DEFAULT NULL,
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_gen_record_biz_seq`(`biz_seq`) USING BTREE,
  INDEX `idx_storyboard`(`storyboard_id`) USING BTREE,
  INDEX `idx_task_id`(`task_id`) USING BTREE,
  INDEX `idx_proj_ep_user_type`(`project_id`, `episode_id`, `user_id`, `gen_type`, `del_flag`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '生成记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aid_gen_record
-- ----------------------------

-- ----------------------------
-- Table structure for aid_home_banner
-- ----------------------------
DROP TABLE IF EXISTS `aid_home_banner`;
CREATE TABLE `aid_home_banner`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `title` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '标题',
  `summary` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '简述',
  `banner_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'image' COMMENT '资源类型（image图片 video视频 gif动图）',
  `resource_url` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '资源地址(相对路径)',
  `cover_url` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '封面地址(相对路径, 视频/动图为首帧海报图)',
  `link_url` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '外链/跳转地址',
  `link_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'none' COMMENT '跳转类型（none无跳转 external外部链接 internal内部页面）',
  `sort_order` int(11) NOT NULL DEFAULT 0 COMMENT '排序（值越小越靠前）',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '状态（0显示 1隐藏）',
  `start_time` datetime NULL DEFAULT NULL COMMENT '生效开始时间（为空不限制）',
  `end_time` datetime NULL DEFAULT NULL COMMENT '生效结束时间（为空不限制）',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '删除标志（0存在 1删除）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_status_sort`(`status`, `sort_order`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '首页Banner配置' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aid_home_banner
-- ----------------------------
