-- ----------------------------
-- Table structure for aid_image_moderation_log
-- ----------------------------
DROP TABLE IF EXISTS `aid_image_moderation_log`;
CREATE TABLE `aid_image_moderation_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint(20) NULL DEFAULT NULL COMMENT '上传用户ID',
  `biz_source` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '业务来源(如storyboard_upload/common_upload)',
  `file_url` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '被审图片URL',
  `file_md5` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'IMS 回传 FileMD5',
  `suggestion` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'IMS 建议(Pass/Review/Block)',
  `label` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '命中标签',
  `sub_label` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '命中子标签',
  `score` int(11) NULL DEFAULT NULL COMMENT '命中分值',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '决策状态(PASS/BLOCK/REVIEW/ERROR)',
  `request_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'IMS RequestId',
  `error_message` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'ERROR 时的错误信息',
  `elapsed_ms` bigint(20) NULL DEFAULT NULL COMMENT '审查耗时(毫秒)',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_time`(`user_id`, `create_time`) USING BTREE,
  INDEX `idx_status_time`(`status`, `create_time`) USING BTREE,
  INDEX `idx_md5`(`file_md5`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '图片内容安全审查日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aid_image_moderation_log
-- ----------------------------

-- ----------------------------
-- Table structure for aid_invite_code
-- ----------------------------
DROP TABLE IF EXISTS `aid_invite_code`;
CREATE TABLE `aid_invite_code`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint(20) NOT NULL COMMENT '用户ID (关联sys_user.user_id)',
  `invite_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '邀请码（大写字母+数字，去除易混淆字符，全局唯一）',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '删除标志（0存在 1删除）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_user_id`(`user_id`) USING BTREE,
  UNIQUE INDEX `uk_invite_code`(`invite_code`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户邀请码' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aid_invite_code
-- ----------------------------

-- ----------------------------
-- Table structure for aid_invite_rebate_record
-- ----------------------------
DROP TABLE IF EXISTS `aid_invite_rebate_record`;
CREATE TABLE `aid_invite_rebate_record`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `inviter_user_id` bigint(20) NOT NULL COMMENT '邀请人用户ID（返佣接收方）',
  `invitee_user_id` bigint(20) NOT NULL COMMENT '被邀请人用户ID（充值方）',
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '充值订单号（全局唯一，返佣幂等键）',
  `order_credits` decimal(12, 2) NULL DEFAULT NULL COMMENT '订单到账积分（返佣计算基数）',
  `pay_price` decimal(12, 2) NULL DEFAULT NULL COMMENT '订单实付金额(元)（审计快照）',
  `rebate_ratio` decimal(8, 4) NULL DEFAULT NULL COMMENT '返佣比例(%)（发放时快照，防止改配置后无法追溯）',
  `rebate_amount` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '实际返佣积分',
  `status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'granted' COMMENT '状态（granted已发放 revoked已撤回-订单退款扣回）',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '删除标志（0存在 1删除）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间（返佣发放时间）',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_order_no`(`order_no`) USING BTREE,
  INDEX `idx_inviter`(`inviter_user_id`) USING BTREE,
  INDEX `idx_invitee`(`invitee_user_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '邀请充值返佣记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aid_invite_rebate_record
-- ----------------------------

-- ----------------------------
-- Table structure for aid_invite_relation
-- ----------------------------
DROP TABLE IF EXISTS `aid_invite_relation`;
CREATE TABLE `aid_invite_relation`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `inviter_user_id` bigint(20) NOT NULL COMMENT '邀请人用户ID (关联sys_user.user_id)',
  `invitee_user_id` bigint(20) NOT NULL COMMENT '被邀请人用户ID（全局唯一，一个用户只能被邀请一次）',
  `invite_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '注册时使用的邀请码（快照）',
  `register_channel` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '被邀请人注册渠道（sms手机号/email邮箱/wechat微信）',
  `register_ip` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '被邀请人注册IP（风控审计）',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '关系状态（0正常 1禁用；禁用后该关系不再产生返佣）',
  `total_rebate` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '该关系累计返佣积分（冗余统计，退款扣回时同步扣减）',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '删除标志（0存在 1删除）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间（即被邀请人注册时间）',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_invitee`(`invitee_user_id`) USING BTREE,
  INDEX `idx_inviter`(`inviter_user_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '邀请关系' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aid_invite_relation
-- ----------------------------

-- ----------------------------
-- Table structure for aid_media_result
-- ----------------------------
DROP TABLE IF EXISTS `aid_media_result`;
CREATE TABLE `aid_media_result`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `task_id` bigint(20) NOT NULL COMMENT '关联任务ID',
  `media_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '媒体类型：IMAGE/VIDEO',
  `origin_url` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '上游原始URL',
  `oss_url` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '持久化URL',
  `mime_type` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '文件类型',
  `file_size` bigint(20) NULL DEFAULT NULL COMMENT '文件大小（Byte）',
  `duration_seconds` int(11) NULL DEFAULT NULL COMMENT '视频时长（秒）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_task_id`(`task_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '媒体结果表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aid_media_result
-- ----------------------------

-- ----------------------------
-- Table structure for aid_media_task
-- ----------------------------
DROP TABLE IF EXISTS `aid_media_task`;
CREATE TABLE `aid_media_task`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint(20) NULL DEFAULT NULL COMMENT '发起用户ID',
  `media_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '媒体类型：IMAGE / VIDEO / TEXT',
  `protocol` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '协议标识',
  `model_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '模型名称',
  `prompt` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '提示词',
  `request_hash` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '请求幂等哈希',
  `request_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '请求快照',
  `response_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '响应快照',
  `provider_task_id` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '上游任务ID',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '状态：PENDING/PROCESSING/SUCCEEDED/FAILED',
  `billing_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'INIT' COMMENT '计费状态：INIT/SUCCESS/FAILED',
  `billing_trace_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '计费链路ID',
  `origin_url` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '上游原始URL',
  `oss_url` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '持久化URL',
  `oss_pending` tinyint(1) GENERATED ALWAYS AS ((case when ((`status` = 'SUCCEEDED') and (`origin_url` is not null) and (`origin_url` <> '') and isnull(`oss_url`)) then 1 else 0 end)) VIRTUAL COMMENT 'OSS补偿候选：1待持久化，0无需处理' NULL,
  `result_text` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '文本生成结果（助手输出全文）',
  `error_message` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '错误信息',
  `retry_count` int(11) NULL DEFAULT 0 COMMENT '轮询重试次数',
  `callback_record_id` bigint(20) NULL DEFAULT NULL COMMENT '回填业务记录主键（aid_comic_asset / aid_gen_record）',
  `callback_category` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '回填目标：asset / gen_record',
  `batch_id` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '批次ID（批量生成时共享UUID，单任务为空）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `biz_task_id` bigint(20) NULL DEFAULT NULL COMMENT '业务任务ID(如aid_extract_task.id)',
  `biz_task_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '业务任务类型（如 extract），与 biz_task_id 配合定位具体业务表',
  `parent_task_id` bigint(20) NULL DEFAULT NULL COMMENT '编排父任务ID（aid_extract_task.id），用于续租与重启对账',
  `frozen_amount` decimal(10, 2) NULL DEFAULT NULL COMMENT '预冻结金额（元）',
  `billing_snapshot_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '计费快照(命中SKU+价格+规则版本)',
  `actual_cost` decimal(10, 4) NULL DEFAULT NULL COMMENT '实际扣费金额(元)',
  `billing_param_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '计费参数(参与匹配的参数值)',
  `text_settle_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'INIT' COMMENT '文本差额结算状态: INIT=未开始, PROCESSING=处理中, DONE=已完成',
  `dispatch_mode` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '调度模式: DIRECT/CALLBACK_FIRST/POLL_ONLY',
  `next_poll_time` datetime NULL DEFAULT NULL COMMENT '下次轮询时间',
  `callback_deadline` datetime NULL DEFAULT NULL COMMENT '回调等待截止时间',
  `schedule_snapshot_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '调度策略快照',
  `upstream_accept_time` datetime NULL DEFAULT NULL COMMENT '上游受理时刻：最大存活的起算点',
  `last_progress_time` datetime NULL DEFAULT NULL COMMENT '最近一次观测到上游推进的时刻：无进展超时的起算点',
  `project_id` bigint(20) NULL DEFAULT NULL COMMENT '项目ID',
  `episode_id` bigint(20) NULL DEFAULT NULL COMMENT '剧集ID（电影模式为0）',
  `compose_batch_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '合成批次号',
  `output_duration_seconds` bigint(20) NULL DEFAULT NULL COMMENT '成片时长(秒)',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_provider_task_id`(`provider_task_id`) USING BTREE,
  INDEX `idx_status_update_time`(`status`, `update_time`) USING BTREE,
  INDEX `idx_request_hash`(`request_hash`) USING BTREE,
  INDEX `idx_batch_id`(`batch_id`) USING BTREE,
  INDEX `idx_media_parent_status`(`parent_task_id`, `status`, `id`) USING BTREE,
  INDEX `idx_dispatch_poll`(`status`, `next_poll_time`) USING BTREE,
  INDEX `idx_media_task_project`(`user_id`, `project_id`, `episode_id`) USING BTREE,
  INDEX `idx_billing_scan`(`billing_status`, `update_time`) USING BTREE,
  INDEX `idx_media_task_liveness_accept`(`status`, `upstream_accept_time`, `id`) USING BTREE,
  INDEX `idx_media_task_liveness_progress`(`status`, `last_progress_time`, `id`) USING BTREE,
  INDEX `idx_media_task_liveness_legacy`(`status`, `create_time`, `id`) USING BTREE,
  INDEX `idx_oss_compensate`(`oss_pending`, `update_time`, `id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '媒体任务表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aid_media_task
-- ----------------------------

-- ----------------------------
-- Table structure for aid_model_health_stat
-- ----------------------------
DROP TABLE IF EXISTS `aid_model_health_stat`;
CREATE TABLE `aid_model_health_stat`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `bucket_time` datetime NOT NULL COMMENT '统计时间桶起点(按30分钟对齐,如 18:00:00 / 18:30:00)',
  `provider_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '服务商编码(aid_ai_provider.provider_code,冗余便于按供应商聚合)',
  `model_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '模型编码(aid_ai_model.model_code)',
  `media_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '媒体类型(TEXT/IMAGE/VIDEO/AUDIO)',
  `success_count` int(11) NOT NULL DEFAULT 0 COMMENT '成功次数(上游正常返回结果)',
  `fail_count` int(11) NOT NULL DEFAULT 0 COMMENT '失败次数(仅上游返回错误:提交被拒/生成失败/超时无响应)',
  `total_latency_ms` bigint(20) NOT NULL DEFAULT 0 COMMENT '成功任务总耗时毫秒(平均耗时=total_latency_ms/success_count)',
  `last_error_message` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '本桶最近一次上游错误信息(截断,供后台排查)',
  `last_error_time` datetime NULL DEFAULT NULL COMMENT '本桶最近一次上游错误时间',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_bucket_model`(`bucket_time`, `model_code`) USING BTREE,
  INDEX `idx_bucket_time`(`bucket_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'AI模型健康统计表(按时间桶聚合)' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aid_model_health_stat
-- ----------------------------

-- ----------------------------
-- Table structure for aid_notice
-- ----------------------------
DROP TABLE IF EXISTS `aid_notice`;
CREATE TABLE `aid_notice`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `title` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '公告标题',
  `description` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '公告描述（摘要/副标题）',
  `image_url` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '图片地址(相对路径, 视频公告时为封面图)',
  `is_video` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '是否视频公告（0否 1是）',
  `video_url` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '视频地址(相对路径, 仅is_video=1时有值)',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '公告完整内容（富文本）',
  `notice_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'system' COMMENT '公告类型（system系统公告 activity活动公告 update更新公告）',
  `is_top` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '是否置顶（0否 1是）',
  `sort_order` int(11) NOT NULL DEFAULT 0 COMMENT '排序（值越小越靠前）',
  `view_count` bigint(20) NOT NULL DEFAULT 0 COMMENT '浏览次数',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '状态（0显示 1隐藏）',
  `publish_time` datetime NULL DEFAULT NULL COMMENT '发布时间',
  `start_time` datetime NULL DEFAULT NULL COMMENT '生效开始时间（为空不限制）',
  `end_time` datetime NULL DEFAULT NULL COMMENT '生效结束时间（为空不限制）',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '删除标志（0存在 1删除）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_status_top_sort`(`status`, `is_top`, `sort_order`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'C端公告' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aid_notice
-- ----------------------------

-- ----------------------------
-- Table structure for aid_onboarding_tour_config
-- ----------------------------
DROP TABLE IF EXISTS `aid_onboarding_tour_config`;
CREATE TABLE `aid_onboarding_tour_config`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `tour_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'Tour 标识',
  `tour_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'Tour 名称',
  `tour_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'Tour 类型：overview=概览向导 / highlight=页面高亮',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Tour 说明',
  `is_enabled` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否启用：0否 1是',
  `sort_order` int(11) NOT NULL DEFAULT 0 COMMENT '排序',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_tour_id`(`tour_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 16 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '引导配置' ROW_FORMAT = Dynamic;

