-- ----------------------------
-- Table structure for aid_pay_order
-- ----------------------------
DROP TABLE IF EXISTS `aid_pay_order`;
CREATE TABLE `aid_pay_order`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商户订单号',
  `trade_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '第三方交易号(支付宝/微信)',
  `user_id` bigint(20) NOT NULL COMMENT '用户ID',
  `package_id` bigint(20) NULL DEFAULT NULL COMMENT '套餐ID',
  `product_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品名称',
  `credits` decimal(10, 2) NOT NULL COMMENT '获得积分',
  `original_price` decimal(10, 2) NOT NULL COMMENT '原价(元)',
  `discount` decimal(3, 2) NULL DEFAULT 1.00 COMMENT '折扣',
  `pay_price` decimal(10, 2) NOT NULL COMMENT '实付金额(元)',
  `pay_channel` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '支付渠道(alipay支付宝/wxpay微信)',
  `pay_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'pending' COMMENT '支付状态(pending待支付/paid已支付/failed失败/closed已关闭/refunded已退款)',
  `pay_time` datetime NULL DEFAULT NULL COMMENT '支付时间',
  `expire_time` datetime NULL DEFAULT NULL COMMENT '订单过期时间',
  `client_ip` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '客户端IP',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志(0存在 1删除)',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '支付订单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aid_pay_order
-- ----------------------------

-- ----------------------------
-- Table structure for aid_project_gen_config
-- ----------------------------
DROP TABLE IF EXISTS `aid_project_gen_config`;
CREATE TABLE `aid_project_gen_config`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `project_id` bigint(20) NOT NULL COMMENT '所属项目ID (aid_comic_project.id)',
  `user_id` bigint(20) NOT NULL COMMENT '所属用户ID (aid_comic_project.user_id)',
  `scene_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '生成场景编码(如main_character_extract)',
  `agent_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '智能体编码 (aid_agent.agent_code)',
  `model_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '模型编码 (aid_ai_model.model_code)',
  `resolution` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '清晰度档位(如1K/2K/4K, 仅图片场景生效)',
  `aspect_ratio` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '图片比例(如16:9, 仅分镜生图场景生效)',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志(0存在 1删除)',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_proj_user_scene`(`project_id`, `user_id`, `scene_code`) USING BTREE,
  INDEX `idx_project_user`(`project_id`, `user_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '项目级生成配置' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aid_project_gen_config
-- ----------------------------

-- ----------------------------
-- Table structure for aid_prompt_lib
-- ----------------------------
DROP TABLE IF EXISTS `aid_prompt_lib`;
CREATE TABLE `aid_prompt_lib`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint(20) NULL DEFAULT 0 COMMENT '所属用户ID (0表示官方预设，非0表示用户自定义私有)',
  `prompt_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '提示词分类(如shot_size景别/camera_angle机位/lighting灯光等)',
  `prompt_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '提示词名称(如赛博朋克风)',
  `prompt_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '提示词具体内容',
  `prompt_content_en` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '提示词具体内容-英文',
  `version` int(5) NULL DEFAULT NULL COMMENT '版本',
  `cover_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '效果预览图URL',
  `sort_order` int(11) NULL DEFAULT 0 COMMENT '展示排序 (数值越小越靠前，主要用于官方提示词排序)',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '状态 (0正常 1停用，用于官方下架某个提示词)',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志 (0代表存在 1代表删除)',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注(可写一些关于这个提示词的最佳实践说明)',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_type`(`user_id`, `prompt_type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 301 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '提示词库' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aid_prompt_lib
-- ----------------------------
INSERT INTO `aid_prompt_lib` VALUES (77, 0, 'composition', '三分构图', '三分法构图，主体置于三分线交点，画面均衡，视觉重心自然。', NULL, NULL, '/aid/storyboard/img/2026/06/07/2_05三分法.jpg', 1, '0', '0', '2026-03-31 22:17:30', 'system', '2026-07-26 21:28:24', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (78, 0, 'composition', '对称构图', '对称构图，画面以中轴线左右完全对称，两侧元素一一对应，秩序感强。', NULL, NULL, '/aid/storyboard/img/2026/06/07/3_01对称.jpg', 2, '0', '0', '2026-03-31 22:17:30', 'system', '2026-07-26 20:56:46', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (79, 0, 'composition', '中心构图', '中心构图，主体绝对居中位于垂直中轴线上，四周元素向中心收拢。', NULL, NULL, '/aid/storyboard/img/2026/06/07/2_06中心构图.jpg', 3, '0', '0', '2026-03-31 22:17:30', 'system', '2026-07-26 20:56:46', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (80, 0, 'composition', '引导线法', '引导线构图，画面中的线条元素自边角向纵深延伸，视线沿线条被牵引至主体。', NULL, NULL, '/aid/storyboard/img/2026/06/07/2_08引导线.jpg', 4, '0', '0', '2026-03-31 22:17:30', 'system', '2026-07-26 20:56:46', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (81, 0, 'composition', '框架构图', '框架构图，前景元素在四周围合成天然画框并虚化，主体位于框内明亮处。', NULL, NULL, '/aid/storyboard/img/2026/06/07/2_09框架构图.jpg', 5, '0', '0', '2026-03-31 22:17:30', 'system', '2026-07-26 20:56:46', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (82, 0, 'composition', '前景层', '前景层构图，画面分前中后三层，前景大幅虚化形成柔纱，中景主体清晰，后景虚化。', NULL, NULL, '/aid/storyboard/img/2026/06/07/3_04 前景层.jpg', 6, '0', '0', '2026-03-31 22:17:30', 'system', '2026-07-26 20:56:46', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (83, 0, 'composition', '对角构图', '对角线构图，主要元素沿画面对角线倾斜排布，形成强烈的方向动势。', NULL, NULL, '/aid/storyboard/img/2026/06/07/2_07对角线.jpg', 7, '0', '0', '2026-03-31 22:17:30', 'system', '2026-07-26 20:56:46', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (84, 0, 'composition', '三角构图', '三角构图，画面主要元素构成稳定的三角形分布，底边宽阔顶点收拢，视觉重心低而沉稳。', NULL, NULL, '', 8, '0', '0', '2026-03-31 22:17:30', 'system', '2026-07-26 21:28:25', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (85, 0, 'shot_size', '远景', '远景，主体全身占画面高度约三分之一，环境占据大部分画面，交代主体与空间的关系。', NULL, NULL, '/aid/storyboard/img/2026/06/07/远景.png', 1, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:47', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (86, 0, 'shot_size', '全景', '全景，主体全身刚好填满画框，头顶与脚下留少量余量，完整呈现主体形态。', NULL, NULL, '/aid/storyboard/img/2026/06/07/全景.png', 2, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:47', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (87, 0, 'shot_size', '中景', '中景，取景至主体腰部以上，兼顾主体动作与局部环境。', NULL, NULL, '/aid/storyboard/img/2026/06/07/中景.png', 3, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:47', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (88, 0, 'shot_size', '中近景', '中近景，取景至主体胸口以上，突出上半身与神态。', NULL, NULL, '/aid/storyboard/img/2026/06/07/中近景.png', 4, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:47', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (89, 0, 'shot_size', '近景', '近景，取景至主体肩部以上，主体细节成为画面重点。', NULL, NULL, '/aid/storyboard/img/2026/06/07/近景.png', 5, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:47', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (91, 0, 'shot_size', '大特写', '大特写，取景仅保留主体最关键的局部并填满整个画面，细节被极致放大。', NULL, NULL, '/aid/storyboard/img/2026/06/07/大特写.png', 7, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:47', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (93, 0, 'camera_angle', '平视', '平视机位，相机与主体视平线等高，视角客观中立，无俯仰透视变形。', NULL, NULL, '/aid/storyboard/img/2026/06/07/1_03平角度 : 眼平.jpg', 1, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:45', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (96, 0, 'camera_angle', '鸟瞰', '鸟瞰机位，相机自正上方垂直向下俯拍，主体与环境呈平面化排布，投影被压缩至脚下。', NULL, NULL, '/aid/storyboard/img/2026/06/07/1_01鸟瞰.jpg', 4, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:45', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (97, 0, 'camera_angle', '虫视角', '虫视机位，相机贴近地面极端仰拍，前景元素被极度放大，天空占据画面主体，透视变形强烈。', NULL, NULL, '/aid/storyboard/img/2026/06/07/1_05 虫视.jpg', 5, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:45', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (99, 0, 'camera_angle', '第一人称视角', '第一人称主观机位，模拟观看者视线，带轻微自然晃动，主体正对镜头形成直接对视。', NULL, NULL, '/aid/storyboard/img/2026/06/07/1_07主观视角 : 第一人称.jpg', 7, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:45', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (100, 0, 'camera_angle', '荷兰角', '荷兰角机位，画面水平轴倾斜约十五度，地平线呈倾斜对角线，制造失衡与不安感。', NULL, NULL, '/aid/storyboard/img/2026/06/07/1_08 荷兰角 : 斜角.jpg', 8, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:45', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (101, 0, 'camera_angle', '侧面视角', '正侧面机位，相机与主体朝向呈九十度，只呈现完整的侧面轮廓线。', NULL, NULL, '/aid/storyboard/img/2026/06/07/2_02侧面 : 剪影.jpg', 9, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:45', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (103, 0, 'focal_length', '14mm 超广角', '十四毫米超广角，视野极宽，透视变形强烈，近大远小被极度夸张。', NULL, NULL, '/aid/storyboard/img/2026/06/07/14mm 超广角.png', 2, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 21:28:25', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (104, 0, 'focal_length', '24mm 广角', '二十四毫米广角，视野开阔，透视有明显夸张，纵深感强。', NULL, NULL, '/aid/storyboard/img/2026/06/07/8_05 广角.jpg', 3, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 21:28:25', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (105, 0, 'focal_length', '35mm 小广角', '三十五毫米小广角，视野略宽于人眼，透视自然，纪实感强。', NULL, NULL, '/aid/storyboard/img/2026/06/07/35mm 小广角.png', 4, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 21:28:25', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (106, 0, 'focal_length', '50mm 标准', '五十毫米标准，透视最接近人眼，无明显变形，最中性的镜头语言。', NULL, NULL, '/aid/storyboard/img/2026/06/07/8_06 标准.jpg', 5, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 21:28:25', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (107, 0, 'focal_length', '85mm 人像', '八十五毫米中长焦，主体比例最讨喜，背景虚化柔和，主体与背景分离干净。', NULL, NULL, '/aid/storyboard/img/2026/06/07/85mm 人像.png', 6, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 21:28:25', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (108, 0, 'focal_length', '105mm 中长焦', '一百零五毫米中长焦，透视轻度压缩，散景细腻，细节表现力强。', NULL, NULL, '/aid/storyboard/img/2026/06/07/8_07 中长焦.jpg', 7, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 21:28:25', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (109, 0, 'focal_length', '135mm 长焦', '一百三十五毫米长焦，空间压缩明显，背景奶油化。', NULL, NULL, '/aid/storyboard/img/2026/06/07/135mm 长焦.png', 8, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 21:28:25', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (110, 0, 'focal_length', '200mm 远摄', '二百毫米远摄，空间被极度压缩近乎平面，主体与环境彻底剥离。', NULL, NULL, '/aid/storyboard/img/2026/06/07/8_08 长焦.jpg', 9, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 21:28:25', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (111, 0, 'color_tone', '暖色调', '暖色调，整体色温偏暖约三千五百开尔文，橙黄金杏为主导色相，冷色被压低。', NULL, NULL, '/aid/storyboard/img/2026/06/07/6_08 暖调.jpg', 1, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:45', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (112, 0, 'color_tone', '冷色调', '冷色调，整体色温偏冷约八千开尔文，蓝青紫银为主导色相，暖色被压低。', NULL, NULL, '/aid/storyboard/img/2026/06/07/6_09 冷调.jpg', 2, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:45', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (113, 0, 'color_tone', '高饱和度', '高饱和，色彩饱和度整体提升约百分之四十，色相浓烈鲜明，对比强烈。', NULL, NULL, '/aid/storyboard/img/2026/06/07/7_03 高饱和.jpg', 3, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:45', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (114, 0, 'color_tone', '去饱和', '低饱和，色彩饱和度整体降低约百分之七十，接近褪色，仅保留微弱色相。', NULL, NULL, '/aid/storyboard/img/2026/06/07/7_02 去饱和.jpg', 4, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:45', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (122, 0, 'lighting', '逆光', '逆光，主光自主体正后方射入，边缘被勾出一圈轮廓光，正面转入柔和剪影。', NULL, NULL, '/aid/storyboard/img/2026/06/07/4_07逆光 : 轮廓光.jpg', 2, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:46', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (123, 0, 'lighting', '侧光', '侧光，主光自正侧方九十度射入，明暗被精确分为两半，立体感与戏剧性最强。', NULL, NULL, '/aid/storyboard/img/2026/06/07/5_02 侧光.jpg', 3, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:46', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (124, 0, 'lighting', '顶光', '顶光，主光自正上方垂直射下，凹陷处形成阴影，上表面被照亮。', NULL, NULL, '/aid/storyboard/img/2026/06/07/4_09 顶光.jpg', 4, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:46', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (125, 0, 'lighting', '底光', '底光，主光自下方射入，光影关系倒置，下方被照亮上方偏暗，非常规的奇幻感。', NULL, NULL, '/aid/storyboard/img/2026/06/07/5_01底光.jpg', 5, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:46', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (128, 0, 'lighting', '环境光', '环境光，无明确主光源方向，仅靠天空散射与周围反射，整体曝光均匀偏低。', NULL, NULL, '/aid/storyboard/img/2026/06/07/5_04 环境光.jpg', 8, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:46', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (129, 0, 'lighting', '黄金时刻', '黄金时刻，日落前约一小时的低角度暖金光线，色温偏暖，投影被拉长。', NULL, NULL, '/aid/storyboard/img/2026/06/07/5_09 黄金时刻.jpg', 9, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:46', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (130, 0, 'lighting', '蓝调时刻', '蓝调时刻，日落后约二十分钟的深蓝暮光，色温偏冷，地平线残留一线暖橙。', NULL, NULL, '/aid/storyboard/img/2026/06/07/6_01 蓝色时刻.jpg', 10, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:46', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (131, 0, 'lighting', '硬光', '硬光，强烈直射无漫射，阴影边缘锐利清晰，光比约六比一，对比强烈。', NULL, NULL, '/aid/storyboard/img/2026/06/07/4_02 硬光.jpg', 11, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:46', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (132, 0, 'lighting', '柔光', '柔光，经漫射的柔和光线，阴影边缘过渡平滑，光比约二比一，无硬阴影。', NULL, NULL, '/aid/storyboard/img/2026/06/07/4_03 软光.jpg', 12, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:46', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (133, 0, 'exposure_blur', '长曝光', '长曝光，运动轨迹拖曳成连续光带，流动介质被抹平，静止部分保持清晰。', NULL, NULL, '/aid/storyboard/img/2026/06/07/长曝光.png', 1, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 21:28:25', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (134, 0, 'exposure_blur', '浅景深虚化', '浅景深虚化，背景强烈散景，主体从环境中被干净剥离。', NULL, NULL, NULL, 2, '1', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 21:28:24', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (135, 0, 'exposure_blur', '深景深', '深景深，前后景全部合焦，由近及远细节一致锐利。', NULL, NULL, NULL, 3, '1', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 21:28:24', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (136, 0, 'exposure_blur', '微距摄影', '微距，极近对焦距离，微小对象被高倍放大，景深极浅。', NULL, NULL, NULL, 4, '1', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 21:28:24', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (137, 0, 'exposure_blur', '移轴效果', '移轴，焦平面被倾斜，仅一条窄带合焦，真实尺度场景呈现微缩模型质感。', NULL, NULL, NULL, 5, '1', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 21:28:24', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (138, 0, 'exposure_blur', '双重曝光', '双重曝光，两层影像叠加融合，形成半透明的复合画面。', NULL, NULL, '/aid/storyboard/img/2026/06/07/双重曝光.png', 3, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 21:28:25', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (139, 0, 'exposure_blur', '运动模糊', '运动模糊，运动部分沿轨迹拖出模糊带，静止部分保持清晰，速度感强烈。', NULL, NULL, '/aid/storyboard/img/2026/06/07/运动模糊.png', 2, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 21:28:25', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (140, 0, 'exposure_blur', '光斑散景', '散景，失焦光源化为柔和圆形光斑，背景呈梦幻光点质感。', NULL, NULL, '/aid/storyboard/img/2026/06/07/光斑散景.png', 6, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 21:28:25', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (141, 0, 'camera_movement', '固定机位', '固定机位，相机全程静止不动，构图不变，仅主体与环境自身发生变化。', 'static camera, locked-off shot, no camera movement, stable composition', NULL, '/aid/storyboard/img/2026/06/07/固定机位.mp4', 1, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:45', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (142, 0, 'camera_movement', '跟拍', '跟拍，相机保持在主体后方或侧方与主体同速移动，主体在画面中的位置相对稳定。', 'tracking shot, camera follows subject movement, smooth lateral follow', NULL, '/aid/storyboard/img/2026/06/07/跟拍.mp4', 2, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:45', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (143, 0, 'camera_movement', '环绕', '环绕运镜，相机以主体为圆心做平滑弧线运动，机位与主体的距离全程保持不变。', 'orbit shot, camera circles around subject, 360 degree rotation', NULL, '/aid/storyboard/img/2026/06/07/环绕.mp4', 3, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:45', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (144, 0, 'camera_movement', '变焦拉近', '推镜，相机匀速向前推进，取景范围由大变小，主体在画面中逐渐放大。', 'zoom in, push in, gradually closer to subject, increasing intimacy', NULL, '/aid/storyboard/img/2026/06/07/变焦拉近.mp4', 4, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:45', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (145, 0, 'camera_movement', '变焦拉远', '拉镜，相机匀速向后退出，取景范围由小变大，逐步展开环境全貌。', 'zoom out, pull back, gradually wider view, revealing environment', NULL, '/aid/storyboard/img/2026/06/07/变焦拉远.mp4', 5, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:45', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (146, 0, 'camera_movement', '镜头左摇', '左摇，机位固定，镜头绕垂直轴向左平缓转动，画面内容自右向左推移。', 'pan left, horizontal camera rotation to the left, scanning scene', NULL, '/aid/storyboard/img/2026/06/07/镜头左摇.mp4', 6, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:45', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (147, 0, 'camera_movement', '镜头右摇', '右摇，机位固定，镜头绕垂直轴向右平缓转动，画面内容自左向右推移。', 'pan right, horizontal camera rotation to the right, scanning scene', NULL, '/aid/storyboard/img/2026/06/07/镜头右摇.mp4', 7, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:45', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (148, 0, 'camera_movement', '镜头上仰', '上摇，机位固定，镜头绕水平轴向上转动，视点由低处抬向高处。', 'tilt up, vertical camera rotation upward, revealing height', NULL, '/aid/storyboard/img/2026/06/07/镜头上仰.mp4', 8, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:45', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (149, 0, 'camera_movement', '镜头下俯', '下摇，机位固定，镜头绕水平轴向下转动，视点由高处落向低处。', 'tilt down, vertical camera rotation downward, descending view', NULL, '/aid/storyboard/img/2026/06/07/镜头下俯.mp4', 9, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:45', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (150, 0, 'camera_movement', '前移', '前移，相机整体沿光轴向前平移靠近主体，透视关系随距离改变。', 'dolly in, camera physically moves forward toward subject, depth change', NULL, '/aid/storyboard/img/2026/06/07/镜头前移.mp4', 10, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:45', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (151, 0, 'camera_movement', '后移', '后移，相机整体沿光轴向后平移远离主体，透视关系随距离改变。', 'dolly out, camera physically moves backward from subject, retreating', NULL, '/aid/storyboard/img/2026/06/07/镜头后移.mp4', 11, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:45', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (152, 0, 'camera_movement', '左移', '左移，相机整体水平向左平移，机位不旋转，主体相对画面向右偏移。', 'truck left, camera slides laterally to the left, parallel movement', NULL, '/aid/storyboard/img/2026/06/07/镜头左移.mp4', 12, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:45', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (153, 0, 'camera_movement', '右移', '右移，相机整体水平向右平移，机位不旋转，主体相对画面向左偏移。', 'truck right, camera slides laterally to the right, parallel movement', NULL, '/aid/storyboard/img/2026/06/07/镜头右移.mp4', 13, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:45', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (154, 0, 'camera_movement', '摆臂上升', '摇臂上升，相机由低机位平滑升起并转为俯视，视点自地面抬升至高处。', 'crane up, jib arm rising, ascending camera movement, elevating view', NULL, '/aid/storyboard/img/2026/06/07/摇臂上升.mp4', 14, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:45', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (155, 0, 'camera_movement', '摆臂下降', '摇臂下降，相机由高机位平滑降落并转为仰视，视点自高处沉向地面。', 'crane down, jib arm lowering, descending camera movement, lowering view', NULL, '/aid/storyboard/img/2026/06/07/摇臂下降.mp4', 15, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:45', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (156, 0, 'camera_movement', '无人机航拍', '航拍运镜，相机在高空大范围移动，兼具升降与横移，展现宏观空间关系。', 'aerial drone shot, bird eye view, flying high above, smooth cinematic aerial tracking', NULL, '/aid/storyboard/img/2026/06/07/无人机航拍.mp4', 16, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:45', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (158, 0, 'camera_movement', '360度环绕', '三百六十度旋转，相机绕光轴自转一周，地平线完整翻转后回正，机位与朝向不变。', '360-degree orbit shot, camera circling seamlessly around the subject, dynamic background shift', NULL, '/aid/storyboard/img/2026/06/07/360° 横滚.mp4', 18, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:45', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (159, 0, 'shooting_technique', '希区柯克变焦', '希区柯克变焦，相机后退的同时镜头推近，主体大小不变而背景透视被剧烈压缩，产生眩晕感。', 'dolly zoom, vertigo effect, background compressing while subject size remains constant, spatial distortion', NULL, '/aid/storyboard/video/2026/06/10/希区柯克变焦.mp4', 1, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:47', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (162, 0, 'shooting_technique', '延时摄影', '延时摄影，长时间流逝被压缩播放，缓慢变化被加速，主体保持相对静止。', 'time-lapse photography, fast forward motion, clouds moving quickly, light and shadows shifting rapidly', NULL, '/aid/storyboard/video/2026/06/10/延时摄影.mp4', 2, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:47', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (165, 0, 'shooting_technique', '子弹时间', '子弹时间，相机绕主体高速环绕而主体动作被极度放慢，形成时间凝滞的环视效果。', 'bullet time effect, extreme slow motion with camera quickly panning around the frozen subject, Matrix style', NULL, '/aid/storyboard/video/2026/06/10/子弹时间.mp4', 3, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:47', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (170, 0, 'shooting_technique', '极速甩镜', '甩镜，相机以极快速度横向或纵向摆动，画面拉出强烈动态模糊，用于场景切换。', 'whip pan, swish pan, rapid blur transition, sudden high-speed horizontal camera rotation', NULL, '/aid/storyboard/video/2026/06/10/快速甩镜.mp4', 4, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:47', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (189, 0, 'quality_base', '通用极高画质', '高清，画面精致，极致细节，大师级构图，杰作', NULL, NULL, NULL, 1, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:47', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (190, 0, 'quality_base', '3D/渲染引擎画质', '3D渲染，虚幻引擎渲染，光线追踪，全局光照，极致光影，超精细建模', NULL, NULL, NULL, 2, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:47', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (191, 0, 'quality_base', '电影级光影保底', '电影感光影，戏剧性布光，体积光，宏大构图，超高清', NULL, NULL, NULL, 3, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:47', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (192, 0, 'negative_base', '通用防崩坏负面词', '低质量，模糊，低分辨率，噪点杂乱，水印，文字，签名，logo，构图残缺，主体畸形', NULL, NULL, NULL, 1, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:47', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (193, 0, 'negative_base', '人体防崩坏负面词', '人体结构错误，比例失调，手部畸形，手指缺失，手指多余，肢体多余，关节反折，五官崩坏，脸部扭曲', NULL, NULL, NULL, 2, '0', '0', '2026-03-31 22:27:28', 'system', '2026-07-26 20:56:47', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (233, 0, 'camera_angle', '高角度', '高角度俯拍，相机高于主体约四十五度向下，主体显得内收，环境铺展开来。', NULL, NULL, '/aid/storyboard/img/2026/06/07/1_02高角度.jpg', 11, '0', '0', '2026-06-07 17:00:22', '', '2026-07-26 20:56:45', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (234, 0, 'camera_angle', '低角度', '低角度仰拍，相机低于主体约三十度向上，主体形体被拉长，存在感增强。', NULL, NULL, '/aid/storyboard/img/2026/06/07/1_04低角度.jpg', 12, '0', '0', '2026-06-07 17:00:22', '', '2026-07-26 20:56:45', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (235, 0, 'camera_angle', '过肩', '过肩机位，前景为另一主体的肩背形成天然景框，中景为被摄主体，建立对话关系。', NULL, NULL, '/aid/storyboard/img/2026/06/07/1_06 过肩.jpg', 13, '0', '0', '2026-06-07 17:00:22', '', '2026-07-26 20:56:45', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (236, 0, 'camera_angle', '正面', '正面机位，相机与主体完全正对，左右对称，视线直接朝向镜头。', NULL, NULL, '/aid/storyboard/img/2026/06/07/1_09 正面.jpg', 14, '0', '0', '2026-06-07 17:00:22', '', '2026-07-26 20:56:45', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (237, 0, 'camera_angle', '四分之三正面', '四分之三正面机位，主体与相机呈约四十五度，露出四分之三正面，明暗自然分层。', NULL, NULL, '/aid/storyboard/img/2026/06/07/2_01四分之三正面.jpg', 15, '0', '0', '2026-06-07 17:00:22', '', '2026-07-26 20:56:45', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (238, 0, 'camera_angle', '四分之三背面', '四分之三背面机位，主体背对相机微转，露出约四分之一侧面，留有回望的悬念。', NULL, NULL, '/aid/storyboard/img/2026/06/07/2_03四分之三背面.jpg', 16, '0', '0', '2026-06-07 17:00:22', '', '2026-07-26 20:56:45', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (239, 0, 'camera_angle', '背面', '背面机位，主体完全背对相机，不呈现正面信息，以背影与环境构成留白。', NULL, NULL, '/aid/storyboard/img/2026/06/07/2_04背面.jpg', 17, '0', '0', '2026-06-07 17:00:22', '', '2026-07-26 20:56:45', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (240, 0, 'composition', '黄金比例', '黄金比例构图，画面元素按约一比一点六一八的黄金螺旋排布，主体位于螺旋终点。', NULL, NULL, '/aid/storyboard/img/2026/06/07/3_02 黄金比例.jpg', 9, '0', '0', '2026-06-07 17:20:51', '', '2026-07-26 20:56:46', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (241, 0, 'composition', '负空间', '负空间构图，大面积留白占画面七成以上，主体极小并偏置一角，空间被极致放大。', NULL, NULL, '/aid/storyboard/img/2026/06/07/3_03 负空间.jpg', 10, '0', '0', '2026-06-07 17:20:51', '', '2026-07-26 20:56:46', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (242, 0, 'composition', '霸总站位', '仰角中心构图，主体居中且位于画面高处，机位低于主体，形成被仰望的支配感。', NULL, NULL, '/aid/storyboard/img/2026/06/07/3_05 霸总站位.jpg', 11, '0', '0', '2026-06-07 17:20:51', '', '2026-07-26 20:56:46', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (243, 0, 'composition', '双人并置', '双主体并置构图，两个主体平行并列，朝向一致而彼此微转，形成对等的交流关系。', NULL, NULL, '/aid/storyboard/img/2026/06/07/3_06 双人并置.jpg', 12, '0', '0', '2026-06-07 17:20:51', '', '2026-07-26 20:56:46', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (244, 0, 'composition', '镜面反射', '镜面反射构图，以反射面中的倒影为画面主体，焦点落在倒影上，实体退为次要。', NULL, NULL, '/aid/storyboard/img/2026/06/07/3_07 镜面反射.jpg', 13, '0', '0', '2026-06-07 17:20:51', '', '2026-07-26 20:56:46', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (245, 0, 'composition', '缝隙窥视', '缝隙窥视构图，透过前景狭窄缝隙拍摄，缝隙虚化成暗色边框，主体在框内明亮处。', NULL, NULL, '/aid/storyboard/img/2026/06/07/3_08 缝隙窥视.jpg', 14, '0', '0', '2026-06-07 17:20:51', '', '2026-07-26 20:56:46', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (246, 0, 'composition', '台阶站位', '高低差构图，主体位于高处，机位在低处仰角约二十度，前景向下层层延伸。', NULL, NULL, '/aid/storyboard/img/2026/06/07/3_09 台阶站位（高低差）.jpg', 15, '0', '0', '2026-06-07 17:20:51', '', '2026-07-26 20:56:46', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (247, 0, 'composition', '俯仰呼应', '多视角呼应构图，前景仰视、中景平视、背景俯视并置于同一画面，用广角压缩空间。', NULL, NULL, '/aid/storyboard/img/2026/06/07/4_01俯仰呼应.jpg', 16, '0', '0', '2026-06-07 17:20:51', '', '2026-07-26 20:56:46', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (248, 0, 'shot_size', '大远景', '大远景，主体占画面不足百分之五，以宏观环境为主，主体仅作点缀。', NULL, NULL, '/aid/storyboard/img/2026/06/07/大远景.png', 9, '0', '0', '2026-06-07 17:30:03', '', '2026-07-26 20:56:47', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (249, 0, 'shot_size', '中全景/膝上景', '膝上景，取景至主体膝盖以上，保留大部分肢体动作与部分环境。', NULL, NULL, '/aid/storyboard/img/2026/06/07/中全景 : 膝上景.png', 10, '0', '0', '2026-06-07 17:30:03', '', '2026-07-26 20:56:47', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (250, 0, 'shot_size', '极特写', '极特写，单一细部占画面七成以上，超越常规特写的极限放大。', NULL, NULL, '/aid/storyboard/img/2026/06/07/极特写.png', 11, '0', '0', '2026-06-07 17:30:03', '', '2026-07-26 20:56:47', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (251, 0, 'shot_size', '细节镜头', '细节镜头，聚焦于局部细部或微小对象，脱离整体独立成画。', NULL, NULL, '/aid/storyboard/img/2026/06/07/细节特写.png', 12, '0', '0', '2026-06-07 17:30:03', '', '2026-07-26 20:56:47', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (252, 0, 'lighting', '漫射光', '漫射光，光线自各方向均匀散射，几乎无方向性与阴影，接近无影状态。', NULL, NULL, '/aid/storyboard/img/2026/06/07/4_04 漫射光.jpg', 13, '0', '0', '2026-06-07 17:40:12', '', '2026-07-26 20:56:46', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (253, 0, 'lighting', '主光', '主光，画面中最主要的塑形光源，决定整体光影结构与主要投影方向。', NULL, NULL, '/aid/storyboard/img/2026/06/07/4_05 主光.jpg', 14, '0', '0', '2026-06-07 17:40:12', '', '2026-07-26 20:56:46', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (254, 0, 'lighting', '辅光', '辅光，用于填充主光形成的阴影，提亮暗部降低光比，不产生新的投影。', NULL, NULL, '/aid/storyboard/img/2026/06/07/4_06 辅光.jpg', 15, '0', '0', '2026-06-07 17:40:12', '', '2026-07-26 20:56:46', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (255, 0, 'lighting', '背景光', '背景光，独立照亮主体之后的背景层，把主体从背景中分离出来。', NULL, NULL, '/aid/storyboard/img/2026/06/07/4_08 背景光.jpg', 16, '0', '0', '2026-06-07 17:40:12', '', '2026-07-26 20:56:46', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (256, 0, 'lighting', '眼神光', '眼神光，一盏正面低强度补光，专门在眼球高光位打出明亮反光点，不改变整体曝光。', NULL, NULL, '/aid/storyboard/img/2026/06/07/5_03 眼神光.jpg', 17, '0', '0', '2026-06-07 17:40:12', '', '2026-07-26 20:56:46', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (257, 0, 'lighting', '高调', '高调，光比约一比一至一点五比一，几乎无阴影，整体明亮通透，高光接近纯白。', NULL, NULL, '/aid/storyboard/img/2026/06/07/5_05 高调.jpg', 18, '0', '0', '2026-06-07 17:40:12', '', '2026-07-26 20:56:47', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (258, 0, 'lighting', '低调', '低调，光比约六比一至八比一，大面积暗部主导，仅少量窄光照亮关键部位。', NULL, NULL, '/aid/storyboard/img/2026/06/07/5_06 低调.jpg', 19, '0', '0', '2026-06-07 17:40:12', '', '2026-07-26 20:56:47', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (259, 0, 'lighting', '中间调', '中间调，光比约二比一至三比一，明暗过渡自然，层次最丰富。', NULL, NULL, '/aid/storyboard/img/2026/06/07/5_07 中间调.jpg', 20, '0', '0', '2026-06-07 17:40:12', '', '2026-07-26 20:56:47', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (260, 0, 'lighting', '剪影', '剪影，强逆光且无辅光，主体完全黑化只留轮廓线条，被明亮背景勾勒。', NULL, NULL, '/aid/storyboard/img/2026/06/07/5_08 剪影.jpg', 21, '0', '0', '2026-06-07 17:40:12', '', '2026-07-26 20:56:47', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (261, 0, 'lighting', '月光', '月光，冷蓝色柔光自高处射入，整体曝光偏低，阴影深但边缘柔和。', NULL, NULL, '/aid/storyboard/img/2026/06/07/6_02 月光.jpg', 22, '0', '0', '2026-06-07 17:40:12', '', '2026-07-26 20:56:47', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (262, 0, 'lighting', '烛光', '烛光，暖橙色点光源自低处近距离照射，色温约两千开尔文，光照范围小且带跳动感。', NULL, NULL, '/aid/storyboard/img/2026/06/07/6_03 烛光.jpg', 23, '0', '0', '2026-06-07 17:40:12', '', '2026-07-26 20:56:47', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (263, 0, 'lighting', '霓虹', '霓虹光，冷调彩色点光源与环境暖光冲突，主体被两种色温分割。', NULL, NULL, '/aid/storyboard/img/2026/06/07/6_04 霓虹.jpg', 24, '0', '0', '2026-06-07 17:40:12', '', '2026-07-26 20:56:47', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (264, 0, 'lighting', '实用光源', '实用光源，光源本身出现在画面内并可见，光照关系由画内光源解释。', NULL, NULL, '/aid/storyboard/img/2026/06/07/6_05 实用光源.jpg', 25, '0', '0', '2026-06-07 17:40:12', '', '2026-07-26 20:56:47', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (265, 0, 'lighting', '窗户光', '窗户光，单侧柔光自开口射入形成一束光柱，只照亮局部其余落入阴影。', NULL, NULL, '/aid/storyboard/img/2026/06/07/6_06 窗户光.jpg', 26, '0', '0', '2026-06-07 17:40:12', '', '2026-07-26 20:56:47', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (266, 0, 'lighting', '频闪', '频闪，极短促的冷白硬光瞬间照亮，动作被冻结，与环境光形成强烈反差。', NULL, NULL, '/aid/storyboard/img/2026/06/07/6_07 频闪.jpg', 27, '0', '0', '2026-06-07 17:40:12', '', '2026-07-26 20:56:47', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (267, 0, 'color_tone', '中性调', '中性调，色温约五千五百开尔文，还原自然白平衡，不做任何色彩倾向处理。', NULL, NULL, '/aid/storyboard/img/2026/06/07/7_01 中性调.jpg', 11, '0', '0', '2026-06-07 17:48:47', '', '2026-07-26 20:56:45', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (268, 0, 'color_tone', '茶色/怀旧', '茶色调，全画面覆盖棕黄滤镜，色彩统一退化为棕黄色系的明度层次，四角加暗角。', NULL, NULL, '/aid/storyboard/img/2026/06/07/7_04 茶色:怀旧.jpg', 12, '0', '0', '2026-06-07 17:48:47', '', '2026-07-26 20:56:45', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (269, 0, 'color_tone', '蓝橙对比', '蓝橙对比，暖部推向橙色系冷部推向青蓝系，形成补色强对比。', NULL, NULL, '/aid/storyboard/img/2026/06/07/7_05 蓝橙对比.jpg', 13, '0', '0', '2026-06-07 17:48:47', '', '2026-07-26 20:56:46', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (270, 0, 'color_tone', '红色调', '红色调，强化红通道，红与洋红饱和度单独提高，其余色相相对收敛。', NULL, NULL, '/aid/storyboard/img/2026/06/07/7_06 红色调.jpg', 14, '0', '0', '2026-06-07 17:48:47', '', '2026-07-26 20:56:46', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (271, 0, 'color_tone', '蓝色调', '蓝色调，强化蓝通道，全画面笼罩一层透明蓝色薄纱，暖色被中和。', NULL, NULL, '/aid/storyboard/img/2026/06/07/7_07 蓝色调.jpg', 15, '0', '0', '2026-06-07 17:48:47', '', '2026-07-26 20:56:46', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (272, 0, 'color_tone', '绿色调', '绿色调，强化绿通道，绿色层次被放大，黄绿至墨绿的过渡丰富。', NULL, NULL, '/aid/storyboard/img/2026/06/07/7_08 绿色调.jpg', 16, '0', '0', '2026-06-07 17:48:47', '', '2026-07-26 20:56:46', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (273, 0, 'color_tone', '金色调', '金色调，高光被染成香槟金，亮部偏金属金，暗部保持温暖棕，整体如浸金。', NULL, NULL, '/aid/storyboard/img/2026/06/07/7_09 金色调.jpg', 17, '0', '0', '2026-06-07 17:48:47', '', '2026-07-26 20:56:46', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (274, 0, 'color_tone', '紫色调', '紫色调，叠加淡紫滤镜，蓝色向薰衣草紫偏移，紫与洋红被突显。', NULL, NULL, '/aid/storyboard/img/2026/06/07/8_01 紫色调.jpg', 18, '0', '0', '2026-06-07 17:48:47', '', '2026-07-26 20:56:46', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (275, 0, 'color_tone', '白色调', '高调白，整体提亮并去饱和推向白色，高光接近纯白，色彩降至最低。', NULL, NULL, '/aid/storyboard/img/2026/06/07/8_02 白色调.jpg', 19, '0', '0', '2026-06-07 17:48:47', '', '2026-07-26 20:56:46', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (276, 0, 'color_tone', '黑色调', '低调黑，整体压暗并强化暗部，深色占主导，四角暗角极重，仅保留少量亮部。', NULL, NULL, '/aid/storyboard/img/2026/06/07/8_03 黑色调.jpg', 20, '0', '0', '2026-06-07 17:48:47', '', '2026-07-26 20:56:46', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (277, 0, 'color_tone', '粉色调', '粉色调，叠加淡粉滤镜，粉与暖白被突显，高光边缘带粉色光晕。', NULL, NULL, '/aid/storyboard/img/2026/06/07/8_04 粉色调.jpg', 21, '0', '0', '2026-06-07 17:48:47', '', '2026-07-26 20:56:46', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (278, 0, 'lens_type', '广角', '二十四毫米广角，透视夸张，近处元素被放大远处被压缩，空间显得开阔纵深。', NULL, NULL, '/aid/storyboard/img/2026/06/07/8_05 广角.jpg', 1, '1', '0', '2026-06-07 17:55:47', '', '2026-07-26 21:28:24', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (279, 0, 'lens_type', '标准', '五十毫米标准，透视与人眼一致，远近比例关系最自然，不加修饰。', NULL, NULL, '/aid/storyboard/img/2026/06/07/8_06 标准.jpg', 2, '1', '0', '2026-06-07 17:55:47', '', '2026-07-26 21:28:24', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (280, 0, 'lens_type', '中长焦', '八十五毫米中长焦，主体比例最佳，背景明显虚化，主体与背景完全分离。', NULL, NULL, '/aid/storyboard/img/2026/06/07/8_07 中长焦.jpg', 3, '1', '0', '2026-06-07 17:55:47', '', '2026-07-26 21:28:24', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (281, 0, 'lens_type', '长焦', '二百毫米长焦，空间极度压缩，前后层次被压到同一平面，背景虚化成纯色。', NULL, NULL, '/aid/storyboard/img/2026/06/07/8_08 长焦.jpg', 4, '1', '0', '2026-06-07 17:55:47', '', '2026-07-26 21:28:24', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (282, 0, 'focal_length', '鱼眼', '十毫米鱼眼，严重桶形畸变，中央凸出四周向角落弯曲，直线全部变为弧线。', NULL, NULL, '/aid/storyboard/img/2026/06/07/8_09 鱼眼.jpg', 1, '0', '0', '2026-06-07 17:55:47', '', '2026-07-26 21:28:24', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (283, 0, 'exposure_blur', '微距', '一百毫米微距，最近对焦距离极短，微小结构被高倍放大，清晰范围仅数毫米。', NULL, NULL, '/aid/storyboard/img/2026/06/07/9_01 微距.jpg', 11, '0', '0', '2026-06-07 17:55:47', '', '2026-07-26 21:28:25', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (284, 0, 'exposure_blur', '移轴', '移轴，焦平面被倾斜，只有一条窄带合焦，真实尺度场景呈现微缩模型质感。', NULL, NULL, '/aid/storyboard/img/2026/06/07/9_02 移轴.jpg', 12, '0', '0', '2026-06-07 17:55:47', '', '2026-07-26 21:28:25', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (285, 0, 'shooting_technique', '变形宽银幕', '变形宽银幕，散景光斑被水平拉长成椭圆，逆光下出现水平方向的蓝色眩光条纹。', NULL, NULL, '/aid/storyboard/img/2026/06/07/9_03 变形宽荧幕.jpg', 13, '0', '0', '2026-06-07 17:55:47', '', '2026-07-26 21:28:24', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (286, 0, 'lens_type', '裂焦', '裂焦，画面左右分别对焦于极近前景与远处主体，中间保留一条焦平面过渡线。', NULL, NULL, '/aid/storyboard/img/2026/06/07/9_04 裂焦.jpg', 9, '1', '0', '2026-06-07 17:55:47', '', '2026-07-26 21:28:24', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (287, 0, 'exposure_blur', '浅景深', '浅景深，大光圈极窄焦平面，仅主体关键部位合焦，前后景全部化为柔和色块与光斑。', NULL, NULL, '/aid/storyboard/img/2026/06/07/9_05 浅景深.jpg', 4, '0', '0', '2026-06-07 18:22:31', '', '2026-07-26 21:28:24', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (288, 0, 'exposure_blur', '深景深', '深景深，小光圈宽焦平面，自最近前景至最远背景全部清晰，画面信息量最大。', NULL, NULL, '/aid/storyboard/img/2026/06/07/9_06 深景深.jpg', 5, '0', '0', '2026-06-07 18:22:31', '', '2026-07-26 21:28:24', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (289, 0, 'exposure_blur', '拉焦/变焦', '拉焦，焦点在拍摄过程中自近处元素转移到远处主体，呈现焦平面移动的过渡状态。', NULL, NULL, '/aid/storyboard/img/2026/06/07/9_07 拉焦:变焦.jpg', 9, '0', '0', '2026-06-07 18:22:31', '', '2026-07-26 21:28:24', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (290, 0, 'exposure_blur', '柔焦', '柔焦，镜头前加柔光镜，高光向暗部溢出形成光晕，整体轮廓边缘柔化。', NULL, NULL, '/aid/storyboard/img/2026/06/07/9_08 柔焦.jpg', 7, '0', '0', '2026-06-07 18:22:31', '', '2026-07-26 21:28:24', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (291, 0, 'exposure_blur', '分裂焦点', '分裂焦点，前景与远景同时合焦，中间层虚化，形成远近共存的双焦平面。', NULL, NULL, '/aid/storyboard/img/2026/06/07/9_09 分裂焦点.jpg', 10, '0', '0', '2026-06-07 18:22:31', '', '2026-07-26 21:28:25', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (292, 0, 'exposure_blur', '失焦', '完全失焦，画面无任何清晰边缘，全部化为模糊色块，仅靠色彩与明暗关系辨识。', NULL, NULL, '/aid/storyboard/img/2026/06/07/10_01 失焦.jpg', 8, '0', '0', '2026-06-07 18:22:31', '', '2026-07-26 21:28:24', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (293, 0, 'shooting_technique', '急推镜头', '急推，相机在极短时间内快速向前推进，取景由大到小，冲击感强烈。', NULL, NULL, '/aid/storyboard/video/2026/06/10/急推镜头.mp4', 5, '0', '0', '2026-06-10 22:34:58', '', '2026-07-26 20:56:47', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (294, 0, 'shooting_technique', '急拉镜头', '急拉，相机在极短时间内快速向后拉远，取景由小到大，形成抽离感。', NULL, NULL, '/aid/storyboard/video/2026/06/10/急拉镜头.mp4', 6, '0', '0', '2026-06-10 22:34:58', '', '2026-07-26 20:56:47', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (295, 0, 'shooting_technique', '第一人称', '第一人称视点，自主体自身视线高度拍摄，肢体或持物自画面下缘入画。', NULL, NULL, '/aid/storyboard/video/2026/06/10/第一人称.mp4', 7, '0', '0', '2026-06-10 22:34:58', '', '2026-07-26 20:56:47', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (296, 0, 'shooting_technique', '探针镜头', '探针镜头，超微距广角贴地穿行，在狭小空间内连续穿越，透视夸张纵深极强。', NULL, NULL, '/aid/storyboard/video/2026/06/10/探针镜头.mp4', 8, '0', '0', '2026-06-10 22:34:58', '', '2026-07-26 20:56:47', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (297, 0, 'shooting_technique', '旋转倾斜镜头', '旋转倾斜，相机绕光轴缓慢滚转，地平线由水平摇摆至倾斜再回正。', NULL, NULL, '/aid/storyboard/video/2026/06/10/旋转倾斜镜头.mp4', 9, '0', '0', '2026-06-10 22:34:58', '', '2026-07-26 20:56:47', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (298, 0, 'shooting_technique', 'FPV 穿梭', 'FPV穿越，相机高速连续穿行并伴随翻滚俯冲，一镜到底，空间关系急速变化。', NULL, NULL, '/aid/storyboard/video/2026/06/10/FPV 穿梭.mp4', 10, '0', '0', '2026-06-10 22:34:58', '', '2026-07-26 20:56:47', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (299, 0, 'shooting_technique', '微距特写', '微距推轨，相机贴近微小对象并向前推进，焦点由主体转移到近处细节。', NULL, NULL, '/aid/storyboard/video/2026/06/10/微距特写.mp4', 11, '0', '0', '2026-06-10 22:34:58', '', '2026-07-26 20:56:47', 'system', NULL);
INSERT INTO `aid_prompt_lib` VALUES (300, 0, 'shooting_technique', '慢镜头', '慢镜头，高帧率拍摄后放慢播放，动作细节被延展，运动轨迹清晰可辨。', NULL, NULL, '/aid/storyboard/video/2026/06/10/慢镜头.mp4', 12, '0', '0', '2026-06-10 22:34:58', '', '2026-07-26 20:56:47', 'system', NULL);

-- ----------------------------
-- Table structure for aid_provider_error_rule
-- ----------------------------
DROP TABLE IF EXISTS `aid_provider_error_rule`;
CREATE TABLE `aid_provider_error_rule`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键 ID',
  `provider_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '厂商编码（NULL 表示全局规则）',
  `model_code` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '模型编码（NULL 表示厂商所有模型）',
  `rule_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '规则名称（运营可读）',
  `match_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '匹配类型：HTTP_STATUS/CODE/KEYWORD/REGEX/JSON_PATH',
  `match_pattern` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '匹配内容（CODE/KEYWORD 用逗号分隔；HTTP_STATUS 支持 401,500-504）',
  `match_field` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'JSON_PATH 模式下的字段路径，如 $.error.code',
  `case_sensitive` tinyint(1) NULL DEFAULT 0 COMMENT '是否区分大小写（0 否 1 是）',
  `error_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '映射到的 TaskErrorCode 枚举名',
  `user_message` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '覆盖默认 userMessage（NULL 用枚举默认值）',
  `priority` int(11) NULL DEFAULT 100 COMMENT '优先级，数字越小越先匹配',
  `enabled` tinyint(1) NULL DEFAULT 1 COMMENT '启用 (0 禁 1 启)',
  `is_builtin` tinyint(1) NULL DEFAULT 0 COMMENT '内置规则 (1 内置不可删除，只能禁用)',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_provider`(`provider_code`, `enabled`, `priority`) USING BTREE,
  INDEX `idx_model`(`model_code`, `enabled`, `priority`) USING BTREE,
  INDEX `idx_error_code`(`error_code`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 94 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '上游错误归一化规则' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aid_provider_error_rule
-- ----------------------------
INSERT INTO `aid_provider_error_rule` VALUES (1, 'jimeng', NULL, '即梦 50411/50412/50413/50518 输入审核未通过', 'CODE', '50411,50412,50413,50518', NULL, 0, 'UPSTREAM_CONTENT_FILTERED', '提示词或参考图未通过审核，请修改后重试', 10, 1, 1, NULL, 'system', '2026-05-27 12:09:05', '', NULL);
INSERT INTO `aid_provider_error_rule` VALUES (2, 'jimeng', NULL, '即梦 50511/50512/50519 输出审核未通过', 'CODE', '50511,50512,50519', NULL, 0, 'UPSTREAM_CONTENT_FILTERED', '生成内容未通过审核，请调整提示词或参考图', 10, 1, 1, NULL, 'system', '2026-05-27 12:09:05', '', NULL);
INSERT INTO `aid_provider_error_rule` VALUES (3, 'jimeng', NULL, '即梦 50520/50521/50522 审核服务异常', 'CODE', '50520,50521,50522', NULL, 0, 'UPSTREAM_SERVER_ERROR', NULL, 10, 1, 1, NULL, 'system', '2026-05-27 12:09:05', '', NULL);
