INSERT INTO `aid_provider_error_rule` VALUES (76, NULL, NULL, '模型不支持/不可用', 'REGEX', 'model[^.]{0,60}not supported|not supported[^.]{0,40}model|unsupported model|no such model|model does not exist|模型不支持|不支持[^，。]{0,10}模型', NULL, 0, 'UPSTREAM_SERVICE_NOT_OPEN', '当前模型暂不可用，请更换模型后重试', 37, 1, 0, '上游返回模型不支持（如 gpt-5.4 model is not supported when using Codex），需早于规则44的 invalid_request_error 兜底，避免误报为请求参数异常', 'system', '2026-07-09 21:42:36', '', NULL);
INSERT INTO `aid_provider_error_rule` VALUES (77, NULL, NULL, '参考图包含真人', 'KEYWORD', 'inputimagesensit,contain real person,contains real person,may contain real person', NULL, 0, 'REAL_PERSON_RESTRICTED', '参考图可能包含真人，请更换参考图', 5, 1, 1, '细分真人参考图限制，需早于通用内容审核规则', 'system', '2026-07-23 21:33:17', '', NULL);
INSERT INTO `aid_provider_error_rule` VALUES (78, NULL, NULL, '模型没有可用账号', 'KEYWORD', 'no available compatible accounts,no compatible account', NULL, 0, 'MODEL_ACCOUNT_UNAVAILABLE', '当前模型暂时不可用，请更换模型', 6, 1, 1, '模型路由没有可用账号或节点', 'system', '2026-07-23 21:33:17', '', NULL);
