INSERT INTO `aid_provider_error_rule` VALUES (80, NULL, NULL, '内容策略拒绝生成', 'KEYWORD', 'content_policy_violation,unable to generate this content', NULL, 0, 'UPSTREAM_CONTENT_FILTERED', '提示词或参考图未通过审核，请修改后重试', 8, 1, 1, '补充带下划线的内容策略错误', 'system', '2026-07-23 21:33:17', '', NULL);
INSERT INTO `aid_provider_error_rule` VALUES (81, NULL, NULL, '模型供应商额度不足', 'KEYWORD', 'insufficient credits', NULL, 0, 'PROVIDER_QUOTA_EXHAUSTED', '模型额度不足，请联系管理员', 9, 1, 1, '供应商账户额度，不是用户余额', 'system', '2026-07-23 21:33:17', '', NULL);
INSERT INTO `aid_provider_error_rule` VALUES (82, NULL, NULL, '模型参数组合不兼容', 'KEYWORD', 'start_image parameter is required,multiple images, but mode was omitted,field is missing or empty', NULL, 0, 'MODEL_PARAMETER_INCOMPATIBLE', '当前参数不受模型支持，请调整后重试', 10, 1, 1, '缺少首帧、多图模式或模型必填字段', 'system', '2026-07-23 21:33:17', '', NULL);
