INSERT INTO `aid_provider_error_rule` VALUES (84, NULL, NULL, '上游返回有效结果为空', 'KEYWORD', '上游未返回任务标识、url或文本结果,模型返回为空,合成为空', NULL, 0, 'RESULT_INVALID', '模型未返回有效结果，请重新生成', 12, 1, 1, '覆盖文本、媒体和合成空结果', 'system', '2026-07-23 21:33:17', '', NULL);
INSERT INTO `aid_provider_error_rule` VALUES (85, NULL, NULL, '模型结构化结果异常', 'KEYWORD', '输出格式异常,模型返回异常,拆分内容异常,拆分内容缺失,拆分顺序异常,拆分格式异常', NULL, 0, 'RESULT_FORMAT_INVALID', '模型返回格式异常，请重新生成', 13, 1, 1, '模型有输出但不符合业务结构', 'system', '2026-07-23 21:33:17', '', NULL);
INSERT INTO `aid_provider_error_rule` VALUES (86, NULL, NULL, '模型网络或网关异常', 'REGEX', '^\\s*<!doctype html|unknownhostexception|connection reset|unexpected end of file|connection refused|failed to connect|could not connect', NULL, 0, 'UPSTREAM_NETWORK_ERROR', '模型网络异常，请稍后重试', 14, 1, 1, '域名解析、连接重置或网关返回HTML', 'system', '2026-07-23 21:33:17', 'system', '2026-07-23 21:33:17');
INSERT INTO `aid_provider_error_rule` VALUES (87, NULL, NULL, '模型节点未就绪', 'KEYWORD', 'comfyui is not reachable,image generation is not enabled for this group', NULL, 0, 'UPSTREAM_SERVICE_NOT_OPEN', '当前模型暂时不可用，请更换模型', 15, 1, 1, '生成节点离线或账号未开通能力', 'system', '2026-07-23 21:33:17', '', NULL);
INSERT INTO `aid_provider_error_rule` VALUES (88, NULL, NULL, '平台数据库异常', 'KEYWORD', 'error updating database,error querying database,could not open jdbc connection,data truncation,sqlsyntaxerrorexception', NULL, 0, 'PERSIST_FAILED', '任务数据处理异常，请联系管理员', 16, 1, 1, '数据库连接、字段或数据长度异常', 'system', '2026-07-23 21:33:17', '', NULL);
INSERT INTO `aid_provider_error_rule` VALUES (89, NULL, NULL, '服务重启导致任务中断', 'KEYWORD', '服务重启中断,任务被中断', NULL, 0, 'TASK_INTERRUPTED', '服务更新导致任务中断，费用已退回', 17, 1, 1, '明确告知用户任务中断和退款结果', 'system', '2026-07-23 21:33:17', '', NULL);
INSERT INTO `aid_provider_error_rule` VALUES (90, 'vidu', NULL, 'Vidu 提交内容审核未通过', 'KEYWORD', 'AuditSubmitIllegal,audit submit illegal', NULL, 0, 'UPSTREAM_CONTENT_FILTERED', '提示词或参考图未通过审核，请修改后重试', 4, 1, 1, 'Vidu 提交阶段审核拒绝，无法仅凭错误码区分提示词或参考图', 'system', '2026-08-04 00:00:00', 'system', '2026-08-04 00:00:00');
INSERT INTO `aid_provider_error_rule` VALUES (91, NULL, NULL, '参考图内容审核未通过', 'REGEX', '(input image|input images|reference image|source image).{0,120}(sensitive|risk not pass|policy violation|content filter|moderation|audit illegal)', NULL, 0, 'UPSTREAM_CONTENT_FILTERED', '参考图未通过内容审核，请更换后重试', 4, 1, 1, '输入图或参考图被上游内容审核拒绝', 'system', '2026-08-04 00:00:00', 'system', '2026-08-04 00:00:00');
INSERT INTO `aid_provider_error_rule` VALUES (92, NULL, NULL, '提示词内容审核未通过', 'REGEX', '(prompt|input text|text input).{0,120}(sensitive|risk not pass|policy violation|content filter|moderation|audit illegal)', NULL, 0, 'UPSTREAM_CONTENT_FILTERED', '提示词未通过内容审核，请修改后重试', 4, 1, 1, '提示词或文本输入被上游内容审核拒绝', 'system', '2026-08-04 00:00:00', 'system', '2026-08-04 00:00:00');
INSERT INTO `aid_provider_error_rule` VALUES (93, NULL, NULL, '生成内容审核未通过', 'REGEX', '(output|generated image|generated video|result).{0,120}(sensitive|risk not pass|policy violation|content filter|moderation|audit illegal)', NULL, 0, 'UPSTREAM_CONTENT_FILTERED', '生成内容未通过审核，请调整提示词或参考图', 4, 1, 1, '模型输出被上游内容审核拒绝', 'system', '2026-08-04 00:00:00', 'system', '2026-08-04 00:00:00');

-- ----------------------------
-- Table structure for aid_publish_whitelist
-- ----------------------------
DROP TABLE IF EXISTS `aid_publish_whitelist`;
CREATE TABLE `aid_publish_whitelist`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint(20) NOT NULL COMMENT '用户ID (关联 sys_user.user_id)',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注（加入原因等）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_publish_whitelist_user`(`user_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '作品发布白名单（名单内用户不受发布总开关限制）' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aid_publish_whitelist
-- ----------------------------

-- ----------------------------
-- Table structure for aid_recharge_package
-- ----------------------------
DROP TABLE IF EXISTS `aid_recharge_package`;
CREATE TABLE `aid_recharge_package`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `package_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '套餐名称',
  `credits` decimal(10, 2) NOT NULL COMMENT '获得积分',
  `original_price` decimal(10, 2) NOT NULL COMMENT '原价(元)',
  `discount` decimal(3, 2) NULL DEFAULT 1.00 COMMENT '折扣(0.90表示9折, 1.00表示无折扣)',
  `pay_price` decimal(10, 2) NOT NULL COMMENT '实付金额(元, original_price * discount)',
  `icon` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '图标',
  `description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '描述',
  `sort_order` int(11) NULL DEFAULT 0 COMMENT '排序(越小越靠前)',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '状态(0正常 1停用)',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志(0存在 1删除)',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '充值套餐配置表' ROW_FORMAT = Dynamic;

