-- ----------------------------
-- Table structure for aid_reference_audio
-- ----------------------------
DROP TABLE IF EXISTS `aid_reference_audio`;
CREATE TABLE `aid_reference_audio`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint(20) NOT NULL COMMENT '所属用户ID',
  `project_id` bigint(20) NOT NULL COMMENT '所属项目ID',
  `episode_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '所属剧集ID（0=全剧集通用）',
  `audio_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '音频名称（用户命名，列表选择用）',
  `audio_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '音频文件 URL（存相对路径，下发前拼域名）',
  `duration_ms` int(11) NOT NULL COMMENT '音频时长（毫秒），上传时探测，出片时不再重复下载',
  `audio_format` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '音频格式（wav / mp3）',
  `file_size` bigint(20) NULL DEFAULT NULL COMMENT '文件大小（字节）',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '状态：0启用 1停用',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志：0存在 2删除',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_project`(`user_id`, `project_id`, `episode_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户上传参考音频' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aid_reference_audio
-- ----------------------------

-- ----------------------------
-- Table structure for aid_role_prop_scene
-- ----------------------------
DROP TABLE IF EXISTS `aid_role_prop_scene`;
CREATE TABLE `aid_role_prop_scene`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `project_id` bigint(20) NOT NULL COMMENT '项目ID',
  `episode_id` bigint(20) NOT NULL COMMENT '剧集ID',
  `user_id` bigint(20) NULL DEFAULT NULL COMMENT '用户ID',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '名称(场景/角色/道具)',
  `aliases_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '别名',
  `introduction` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '角色介绍：身份定位、叙述视角映射、与其他角色的关系、常用称呼',
  `gender` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '性别(角色)',
  `age_range` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '年龄段(角色)，如\"约二十五岁\"',
  `role_level` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '角色重要性层级',
  `profile_data` json NULL COMMENT '角色档案JSON(原型/性格/时代/职业/服装等设定)',
  `expected_appearances` json NULL COMMENT '子形象列表JSON(id与形象变化原因)',
  `summary` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '简要说明(场景用途/道具简介)',
  `available_slots` json NULL COMMENT '场景可落位位置JSON数组(角色固定站位)',
  `has_crowd` tinyint(1) NULL DEFAULT 0 COMMENT '场景是否有人群(0:无 1:有)',
  `crowd_description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '人群类型描述(如：宴会宾客、集市人群)',
  `first_scene_code` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '最小场次编码(多场次场景排序键)',
  `asset_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '类型: scene场景, character角色, prop道具',
  `create_source` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'auto' COMMENT '创建来源: manual-手动创建, auto-自动提取',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志(0代表存在 2代表删除)',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_project_type`(`project_id`, `asset_type`) USING BTREE,
  INDEX `idx_episode`(`episode_id`) USING BTREE,
  INDEX `idx_role_level`(`project_id`, `role_level`) USING BTREE,
  INDEX `idx_first_scene_code`(`project_id`, `episode_id`, `asset_type`, `first_scene_code`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '角色道具场景表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aid_role_prop_scene
-- ----------------------------

-- ----------------------------
-- Table structure for aid_role_prop_scene_form
-- ----------------------------
DROP TABLE IF EXISTS `aid_role_prop_scene_form`;
CREATE TABLE `aid_role_prop_scene_form`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `asset_id` bigint(20) NOT NULL COMMENT '关联的主表ID (对应aid_role_prop_scene表的id)',
  `project_id` bigint(20) NOT NULL COMMENT '项目ID',
  `episode_id` bigint(20) NOT NULL COMMENT '剧集ID',
  `user_id` bigint(20) NULL DEFAULT NULL COMMENT '用户ID',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '形态名称 (例如：常服、战损版、侧脸)',
  `change_reason` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '形象变更原因(如：初始形象、战斗装束、出浴状态)',
  `prompt_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT 'AI生成提示词(该形态的专属特征提示词)',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志 (0代表存在 2代表删除)',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `visual_desc_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'completed' COMMENT '视觉描述状态: pending-待生成, completed-已完成',
  `create_source` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'auto' COMMENT '创建来源: manual-手动创建, auto-自动提取',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_asset_id`(`asset_id`) USING BTREE COMMENT '加速查询某个主表资产下的所有形态',
  INDEX `idx_project_episode`(`project_id`, `episode_id`) USING BTREE COMMENT '加速项目和剧集维度的查询'
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '角色形态' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aid_role_prop_scene_form
-- ----------------------------

-- ----------------------------
-- Table structure for aid_role_prop_scene_form_image
-- ----------------------------
DROP TABLE IF EXISTS `aid_role_prop_scene_form_image`;
CREATE TABLE `aid_role_prop_scene_form_image`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `form_id` bigint(20) NOT NULL COMMENT '关联形态ID，对应aid_role_prop_scene_form.id',
  `asset_id` bigint(20) NOT NULL COMMENT '冗余主资产ID，对应aid_role_prop_scene.id',
  `project_id` bigint(20) NOT NULL COMMENT '项目ID',
  `episode_id` bigint(20) NOT NULL COMMENT '剧集ID',
  `user_id` bigint(20) NULL DEFAULT NULL COMMENT '用户ID',
  `name` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '图片名称，默认 资产名_形态名_序号',
  `image_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '形态图OSS地址',
  `source_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'upload' COMMENT '来源类型：ai_auto/ai_manual/upload/official/migrate',
  `description_index` int(11) NULL DEFAULT NULL COMMENT '提示词下标，从0开始；上传/官方图可为空',
  `prompt_snapshot` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '本次实际使用的提示词快照',
  `reference_images` json NULL COMMENT '本次生图使用的参考图JSON数组',
  `batch_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '同一次生成批次号',
  `sort_order` int(11) NOT NULL DEFAULT 0 COMMENT '同形态下排序',
  `is_use` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否使用中(0否1是)，同一form仅允许一条为1',
  `image_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'completed' COMMENT '图片状态：pending/processing/completed/failed',
  `is_split_source` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否为拆分源图(1=已被拆分,不可再次拆分)',
  `is_split_child` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否为拆分产物(1=由其他图片拆分而来,不可作为源图再拆)',
  `split_parent_image_id` bigint(20) NULL DEFAULT NULL COMMENT '拆分产物的源图ID（仅 is_split_child=1 时有值）',
  `fail_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '失败原因',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '删除标志(0存在 2删除)',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_form_id`(`form_id`) USING BTREE,
  INDEX `idx_asset_id`(`asset_id`) USING BTREE,
  INDEX `idx_project_episode`(`project_id`, `episode_id`) USING BTREE,
  INDEX `idx_form_use`(`form_id`, `is_use`, `del_flag`) USING BTREE,
  INDEX `idx_batch_no`(`batch_no`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '形态图片' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aid_role_prop_scene_form_image
-- ----------------------------

-- ----------------------------
-- Table structure for aid_role_voice_binding
-- ----------------------------
DROP TABLE IF EXISTS `aid_role_voice_binding`;
CREATE TABLE `aid_role_voice_binding`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `asset_id` bigint(20) NOT NULL COMMENT '角色ID（aid_role_prop_scene.id，要求 asset_type=character）',
  `project_id` bigint(20) NULL DEFAULT NULL COMMENT '项目ID（冗余，查询过滤用）',
  `episode_id` bigint(20) NULL DEFAULT NULL COMMENT '剧集ID（冗余）',
  `user_id` bigint(20) NOT NULL COMMENT '用户ID（冗余，归属校验用）',
  `voice_library_id` bigint(20) NOT NULL COMMENT '所绑定音色ID（aid_ai_voice_library.id）',
  `voice_code` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '冗余：音色厂商编码（调用 TTS 时原样透传）',
  `voice_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '冗余：音色展示名',
  `avatar_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '冗余：音色头像图 URL',
  `sample_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '冗余：试听音频 URL',
  `sample_text` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '冗余：试听文案',
  `sample_duration_ms` int(11) NULL DEFAULT NULL COMMENT '冗余：试听音频时长毫秒',
  `reference_audio_id` bigint(20) NULL DEFAULT NULL COMMENT '所绑定上传参考音频ID（aid_reference_audio.id）',
  `reference_audio_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '冗余：上传参考音频 URL',
  `reference_audio_duration_ms` int(11) NULL DEFAULT NULL COMMENT '冗余：上传参考音频时长毫秒',
  `language` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '冗余：语言区域码（zh-CN/en-US/...）',
  `gender` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '冗余：性别（female/male/neutral）',
  `age_range` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '冗余：年龄段（child/teen/young/adult/middle/elderly）',
  `model_id` bigint(20) NULL DEFAULT NULL COMMENT '冗余：音色所属模型ID（aid_ai_model.id）',
  `provider_id` bigint(20) NULL DEFAULT NULL COMMENT '冗余：音色所属服务商ID（aid_ai_provider.id）',
  `override_speed` decimal(3, 2) NULL DEFAULT NULL COMMENT '覆盖语速（0.50~2.00）；null 走音色默认',
  `override_pitch` decimal(4, 2) NULL DEFAULT NULL COMMENT '覆盖音调（-12.00~12.00）；null 走音色默认',
  `override_emotion` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '覆盖情感标签（命中 aid_config.voice_emotion）',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '状态：0启用 1停用',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志：0存在 2删除',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `live_asset_id` bigint(20) GENERATED ALWAYS AS (if((`del_flag` = '0'),`asset_id`,NULL)) STORED NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_live_asset`(`live_asset_id`) USING BTREE,
  INDEX `idx_asset`(`asset_id`) USING BTREE,
  INDEX `idx_user_project`(`user_id`, `project_id`) USING BTREE,
  INDEX `idx_voice_library`(`voice_library_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '音色绑定' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aid_role_voice_binding
-- ----------------------------

-- ----------------------------
-- Table structure for aid_scene_plot
-- ----------------------------
DROP TABLE IF EXISTS `aid_scene_plot`;
CREATE TABLE `aid_scene_plot`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `scene_id` bigint(20) NOT NULL COMMENT '所属场景 aid_role_prop_scene.id',
  `project_id` bigint(20) NOT NULL COMMENT '项目ID',
  `episode_id` bigint(20) NOT NULL COMMENT '剧集ID',
  `user_id` bigint(20) NOT NULL COMMENT '用户ID',
  `scene_code` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '全局递增场次序号',
  `plot_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '剧情原文（LLM 逐字保留）',
  `plot_summary` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '剧情梗概',
  `characters` json NULL COMMENT '出场人物 JSON 数组',
  `character_actions` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '人物动作事件',
  `character_states` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '角色状态',
  `key_dialogues` json NULL COMMENT '关键台词 JSON 数组',
  `scene_function` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '场次功能 叙事功能;故事节奏',
  `time_of_day` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '时间坐标 凌晨/早晨/上午/中午/下午/黄昏/夜晚/深夜/子夜',
  `era_coordinate` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '年代坐标 时代-年代-地域',
  `date_coordinate` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '日期坐标 季节-日期属性',
  `weather` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '气候天象 气候-天气-天象',
  `create_source` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'auto' COMMENT '创建来源 auto/manual',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '0存在 2软删',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_scene_id`(`scene_id`) USING BTREE,
  INDEX `idx_episode_plot`(`project_id`, `episode_id`, `scene_code`) USING BTREE,
  INDEX `idx_episode_del`(`project_id`, `episode_id`, `del_flag`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '剧情节拍' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aid_scene_plot
-- ----------------------------

-- ----------------------------
-- Table structure for aid_storyboard
-- ----------------------------
DROP TABLE IF EXISTS `aid_storyboard`;
CREATE TABLE `aid_storyboard`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `project_id` bigint(20) NOT NULL,
  `episode_id` bigint(20) NULL DEFAULT 0,
  `source_scene_id` bigint(20) NULL DEFAULT NULL COMMENT '来源场景ID(手动创建为null)',
  `user_id` bigint(20) NULL DEFAULT NULL COMMENT '所属用户ID',
  `sort_order` int(11) NULL DEFAULT 0 COMMENT '分镜序号',
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '分镜标题 (如: 分镜脚本01)',
  `story_script` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '分镜剧本内容(对该镜头的剧情描述，固定不变)',
  `dialogue_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '分镜台词配音文本(该镜头角色的对话，固定不变)',
  `batch_id` bigint(20) NULL DEFAULT NULL COMMENT '所属批次 aid_storyboard_batch.id（手动分镜为 NULL）',
  `source_scene_code` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '来源场次编码(手动分镜为null)',
  `final_image_id` bigint(20) NULL DEFAULT NULL COMMENT '选中的最终分镜图ID',
  `final_video_id` bigint(20) NULL DEFAULT NULL COMMENT '选定的最终视频ID',
  `final_audio_id` bigint(20) NULL DEFAULT NULL COMMENT '选定的最终配音ID',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0',
  `create_time` datetime NULL DEFAULT NULL,
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '',
  `update_time` datetime NULL DEFAULT NULL,
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `script_params` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '分镜脚本扩展参数JSON(景别/运镜/构图/氛围等)',
  `image_prompt` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '分镜图生图 prompt（分镜画师智能体输出）',
  `image_prompt_raw` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '分镜画师智能体的原始输出（JSON 数组形式）',
  `grid_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '宫格类型(四宫格/九宫格, 非宫格模式为null)',
  `video_prompt` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '视觉导演输出的视频提示词（纯字符串，约180字内）',
  `video_prompt_image` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '图生方向的视频提示词',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_storyboard_scene`(`project_id`, `episode_id`, `source_scene_id`) USING BTREE,
  INDEX `idx_batch_scene_code`(`batch_id`, `source_scene_code`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '分镜时间轴主表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aid_storyboard
-- ----------------------------

-- ----------------------------
-- Table structure for aid_storyboard_batch
-- ----------------------------
DROP TABLE IF EXISTS `aid_storyboard_batch`;
CREATE TABLE `aid_storyboard_batch`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `parent_task_id` bigint(20) NOT NULL COMMENT '父任务 aid_extract_task.id',
  `scene_id` bigint(20) NOT NULL COMMENT '所属主表 aid_role_prop_scene.id',
  `batch_index` int(11) NOT NULL COMMENT '批次序号（从 0 起，同 scene_id 内连续）',
  `shot_codes` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '该批包含的 sceneCode JSON 数组',
  `status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'PENDING' COMMENT '批次状态(PENDING/PROCESSING/SUCCEEDED/FAILED/CANCELLED)',
  `billing_status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'FROZEN' COMMENT 'FROZEN / SETTLED / REFUNDED',
  `frozen_amount` decimal(20, 8) NOT NULL DEFAULT 0.00000000 COMMENT '该批预冻结金额（元）',
  `settled_amount` decimal(20, 8) NULL DEFAULT NULL COMMENT '该批结算金额（成功时填）',
  `retry_round` int(11) NOT NULL DEFAULT 0 COMMENT '重试轮次（每次续生 +1，用于幂等 traceId）',
  `result_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '该批 LLM 输出 JSON 数组',
  `shot_count` int(11) NOT NULL DEFAULT 0 COMMENT '该批产出分镜数（成功时填）',
  `error_message` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '失败原因（截断 500 字以内）',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0',
  `create_time` datetime NULL DEFAULT NULL,
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '',
  `update_time` datetime NULL DEFAULT NULL,
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `shot_group_plan_id` bigint(20) NULL DEFAULT NULL COMMENT '镜头组拆分计划ID（专业版/宫格模式批次关联拆分计划）',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_task_scene_batch_round`(`parent_task_id`, `scene_id`, `batch_index`, `retry_round`) USING BTREE,
  INDEX `idx_parent_status`(`parent_task_id`, `status`) USING BTREE,
  INDEX `idx_storyboard_batch_plan_id`(`shot_group_plan_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '分镜批次' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aid_storyboard_batch
-- ----------------------------

-- ----------------------------
-- Table structure for aid_storyboard_shot_group_plan
-- ----------------------------
DROP TABLE IF EXISTS `aid_storyboard_shot_group_plan`;
CREATE TABLE `aid_storyboard_shot_group_plan`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `task_id` bigint(20) NOT NULL COMMENT '分镜脚本批量任务ID',
  `project_id` bigint(20) NOT NULL COMMENT '项目ID',
  `episode_id` bigint(20) NULL DEFAULT 0 COMMENT '剧集ID',
  `user_id` bigint(20) NOT NULL COMMENT '用户ID',
  `scene_plot_id` bigint(20) NOT NULL COMMENT '场次剧情ID',
  `scene_id` bigint(20) NULL DEFAULT NULL COMMENT '场景资产ID',
  `source_scene_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '来源场次编码',
  `group_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '场次内镜头组编码，如001',
  `group_index` int(11) NOT NULL COMMENT '场次内镜头组序号',
  `display_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '展示编码，如4-1',
  `plot_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '当前镜头组对应原始剧情内容',
  `characters_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '当前镜头组角色JSON',
  `key_dialogues_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '当前镜头组关键台词JSON',
  `split_reason` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '拆分原因',
  `previous_summary` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '上一组承接摘要',
  `next_summary` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '下一组承接摘要',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'PENDING' COMMENT '拆分计划状态(PENDING/PROCESSING/SUCCESS/FAILED/CANCELLED)',
  `storyboard_id` bigint(20) NULL DEFAULT NULL COMMENT '生成成功后的分镜ID',
  `error_msg` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '失败原因',
  `create_time` datetime NULL DEFAULT NULL,
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `update_time` datetime NULL DEFAULT NULL,
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_task_scene_group`(`task_id`, `scene_plot_id`, `group_code`, `del_flag`) USING BTREE,
  INDEX `idx_project_episode`(`project_id`, `episode_id`, `user_id`, `del_flag`) USING BTREE,
  INDEX `idx_task_status`(`task_id`, `status`, `del_flag`) USING BTREE,
  INDEX `idx_scene_order`(`task_id`, `source_scene_code`, `group_index`, `del_flag`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '分镜镜头组拆分计划' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aid_storyboard_shot_group_plan
-- ----------------------------

-- ----------------------------
-- Table structure for aid_user_ai_config
-- ----------------------------
DROP TABLE IF EXISTS `aid_user_ai_config`;
CREATE TABLE `aid_user_ai_config`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint(20) NOT NULL COMMENT '所属用户ID',
  `provider_id` bigint(20) NOT NULL COMMENT '要覆盖的服务商ID (关联 aid_ai_provider.id)',
  `custom_base_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用户自定义代理网关 (为空则走官方网关)',
  `custom_api_key` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用户自带API秘钥 (加密存储)',
  `custom_api_secret` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用户自带扩展秘钥 (如需)',
  `is_enable` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '是否启用自带配置 (0启用 1停用)',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志 (0存在 1删除)',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_user_provider`(`user_id`, `provider_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户模型配置' ROW_FORMAT = Dynamic;

