-- Records of aid_user_ai_config
-- ----------------------------

-- ----------------------------
-- Table structure for aid_user_comic_asset
-- ----------------------------
DROP TABLE IF EXISTS `aid_user_comic_asset`;
CREATE TABLE `aid_user_comic_asset`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint(20) NOT NULL COMMENT '用户ID',
  `asset_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '资产类型(如reference_character人物参考/style风格/pose姿势等)',
  `asset_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '资产名称',
  `personality_desc` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '特征描述/生成约束',
  `prompt_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '提示词内容',
  `image_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '主图URL',
  `source_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'USER' COMMENT '来源类型(USER用户创建 OFFICIAL_COPY官方复制 AI_GENERATED AI生成)',
  `sort_order` int(11) NULL DEFAULT 0 COMMENT '排序值',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '状态: 0正常 1停用',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志: 0存在 1删除',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_type`(`user_id`, `asset_type`, `del_flag`) USING BTREE,
  INDEX `idx_user_status`(`user_id`, `status`, `del_flag`) USING BTREE,
  INDEX `idx_asset_type`(`asset_type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '参考资产' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aid_user_comic_asset
-- ----------------------------

-- ----------------------------
-- Table structure for aid_user_onboarding_profile
-- ----------------------------
DROP TABLE IF EXISTS `aid_user_onboarding_profile`;
CREATE TABLE `aid_user_onboarding_profile`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint(20) NOT NULL COMMENT '用户ID（关联 sys_user.user_id）',
  `global_dismissed` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否全局关闭引导：0否 1是',
  `dismissed_at` datetime NULL DEFAULT NULL COMMENT '最后一次设置全局关闭（global_dismissed=1）的时间',
  `schema_version` int(11) NOT NULL DEFAULT 1 COMMENT '协议版本，与前端 schemaVersion 对齐',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志（0代表存在 1代表删除）',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_user_id`(`user_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户引导-全局配置' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aid_user_onboarding_profile
-- ----------------------------

-- ----------------------------
-- Table structure for aid_user_onboarding_tour
-- ----------------------------
DROP TABLE IF EXISTS `aid_user_onboarding_tour`;
CREATE TABLE `aid_user_onboarding_tour`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `user_id` bigint(20) NOT NULL COMMENT '用户ID',
  `tour_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'Tour 标识，来自 aid_onboarding_tour_config',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'completed/skipped/in_progress',
  `tour_version` int(11) NOT NULL DEFAULT 1 COMMENT '用户完成/跳过时该 Tour 的前端版本号',
  `last_step_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '进行中时最后一步 stepId',
  `client_updated_at` datetime NOT NULL COMMENT '客户端上报时间（冲突合并依据）',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_user_tour`(`user_id`, `tour_id`) USING BTREE,
  INDEX `idx_user_id`(`user_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '引导进度' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aid_user_onboarding_tour
-- ----------------------------

-- ----------------------------
-- Table structure for aid_user_profile
-- ----------------------------
DROP TABLE IF EXISTS `aid_user_profile`;
CREATE TABLE `aid_user_profile`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint(20) NOT NULL COMMENT '用户ID (关联sys_user.user_id)',
  `balance` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '账户余额 (元)',
  `frozen_balance` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '冻结余额 (元)',
  `is_real` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '是否实名认证',
  `real_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '真实姓名',
  `id_card` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '身份证',
  `member_level` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'normal' COMMENT '会员等级编码 (关联aid_member_level.level_code)',
  `member_expire_time` datetime NULL DEFAULT NULL COMMENT '会员到期时间 (NULL非会员)',
  `total_recharge` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '累计充值金额',
  `total_consumption` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '累计消费金额',
  `wechat_notify_enabled` tinyint(1) NOT NULL DEFAULT 0 COMMENT '微信模板消息推送开关',
  `balance_reminder_available` tinyint(1) NOT NULL DEFAULT 0 COMMENT '余额不足提醒资格',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志（0代表存在 1代表删除）',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `publish_enabled` tinyint(1) NOT NULL DEFAULT 1 COMMENT '作品发布权限(1允许 0禁止)',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_user_id`(`user_id`) USING BTREE,
  INDEX `idx_member_level`(`member_level`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户扩展信息' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aid_user_profile
-- ----------------------------

-- ----------------------------
-- Table structure for aid_user_social
-- ----------------------------
DROP TABLE IF EXISTS `aid_user_social`;
CREATE TABLE `aid_user_social`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint(20) NOT NULL COMMENT '用户ID',
  `platform_source` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '平台类型',
  `openid` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '三方平台唯一标识',
  `unionid` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '三方平台全平台唯一标识 (如微信的unionid)',
  `raw_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '三方平台返回的原始数据报文',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_platform_openid`(`platform_source`, `openid`) USING BTREE,
  INDEX `idx_user_platform`(`user_id`, `platform_source`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户第三方登录授权表' ROW_FORMAT = Dynamic;

